def provider_recovery_resumed_summary_text(response_language: str | None) -> str:
    if response_language and response_language.lower().startswith("zh"):
        return "Provider 连接已恢复。继续当前学习主线，只完成一个小而可验证的动作。"
    return "Provider connection recovered. Continue the current learning lane with one small, verifiable action."


def provider_recovery_resumed_next_step_text(
    scenario: str,
    response_language: str | None,
) -> str:
    normalized = str(scenario or "").strip().lower()
    if normalized == "remote_workspace":
        return (
            "在你当前的 VS Code 窗口里，带回一个能证明工作区落点的真实信号，比如 Explorer 里的路径、终端里的 `pwd`，"
            "或者左下角的 remote host 标签。"
            if response_language and response_language.lower().startswith("zh")
            else "Return one real boundary signal from the current VS Code window, such as an Explorer path, `pwd`, or the remote host label."
        )
    if normalized == "debug_loop":
        return (
            "告诉我你会先停在哪个断点，以及准备先检查哪一个值、分支或 stack frame。"
            if response_language and response_language.lower().startswith("zh")
            else "Tell me where you will pause first and which single value, branch, or stack frame you expect to inspect."
        )
    if normalized == "function_guidance":
        return (
            "给我函数名，以及你现在就能打开的一个 call site。"
            if response_language and response_language.lower().startswith("zh")
            else "Give me the function name and one call site you can open right now."
        )
    if normalized == "project_adaptation":
        return (
            "告诉我什么必须保持稳定、什么必须改变，以及你想先适配的第一条边界。"
            if response_language and response_language.lower().startswith("zh")
            else "Tell me what must stay stable, what must change, and the first boundary you want to adapt."
        )
    if response_language and response_language.lower().startswith("zh"):
        return "从最近的说明里选一个最小可验证动作，然后带着结果回来。"
    return "Take the smallest verifiable action from the latest explanation, then return with what happened."


def _pedagogy_controls_for_workspace(runtime: TrainerRuntime, workspace_id: str):
    from ..pedagogy.evidence_controls import controls_from_profile

    memory = runtime.memory_service.snapshot(workspace_id)
    return controls_from_profile(getattr(memory, "coaching_adaptation", None))


def _workspace_training_mint_overlay(
    runtime: TrainerRuntime,
    workspace_id: str,
    request_payload: CardGenerationRequest,
) -> dict[str, object]:
    """Strip leftover formal title/summary from card mint anchors."""

    repository = getattr(runtime, "repository", None)
    plan = repository.get_latest_plan(workspace_id) if repository is not None else None
    memory = runtime.memory_service.snapshot(workspace_id)
    workspace = memory.workspace if isinstance(memory.workspace, dict) else {}
    plan_runtime = select_plan_runtime_for_scope(
        workspace.get(PLAN_RUNTIME_KEY) or workspace.get("latestPlanRuntime"),
        workspace_id,
    ) or {}
    task = normalize_latest_current_task(
        workspace.get(CURRENT_TASK_KEY)
        or workspace.get("current_task")
        or workspace.get("currentTask"),
        workspace_id,
    ) or {}
    task_title = str(task.get("title") or "").strip()
    recovered_step = str(plan_runtime.get("current_step") or "").strip()
    live_plan = formal_plan_is_live_runtime_identity(
        plan=plan,
        runtime=plan_runtime,
        existing=plan_runtime,
        current_step=recovered_step,
    )
    live_task = formal_task_is_live_runtime_identity(
        recovered=bool(plan_runtime),
        runtime_current_step=recovered_step,
        task_title=task_title,
    )
    anchors = live_training_mint_anchors(
        plan=plan,
        runtime=plan_runtime,
        existing=plan_runtime,
        task_title=task_title,
        why_now=request_payload.why_now,
        target_skill=request_payload.target_skill,
        focus_area=request_payload.focus_area,
    )
    leftover = leftover_formal_training_labels(
        plan=plan,
        task_title=task_title,
        live_plan=live_plan,
        live_task=live_task,
    )
    return {
        "anchors": anchors,
        "leftover": leftover,
        "recovered_step": recovered_step,
    }


def _apply_pedagogy_controls_to_card_request(request_payload: CardGenerationRequest, runtime: TrainerRuntime):
    from ..pedagogy.evidence_controls import apply_controls_to_context

    controls = _pedagogy_controls_for_workspace(runtime, request_payload.workspace_id)
    if controls is None:
        return request_payload
    difficulty = str(request_payload.difficulty or "").strip().lower()
    if difficulty in {"", "medium"}:
        return apply_controls_to_context(request_payload, controls)
    return request_payload.model_copy(
        update={
            "hint_count": request_payload.hint_count or controls.hint_count,
            "code_reveal": request_payload.code_reveal or controls.code_reveal,
            "practice_type": request_payload.practice_type or controls.practice_type,
            "review_frequency": request_payload.review_frequency or controls.review_frequency,
            "material_recommendation": request_payload.material_recommendation
            or controls.material_recommendation,
            "next_plan_step": request_payload.next_plan_step or controls.next_plan_step,
            "should_reveal_code": (
                request_payload.should_reveal_code
                if request_payload.should_reveal_code is not None
                else controls.should_reveal_code
            ),
            "pedagogy_mode": request_payload.pedagogy_mode or controls.pedagogy_mode,
        }
    )


def _request_is_plan_agent_turn(
    request: TurnRequest | SessionMessageRequest,
    payload: dict | None = None,
) -> bool:
    """Plan discussion and revision share the executable planning loop."""

    if str(getattr(request, "active_view", "") or "").strip().lower() == "plan":
        return True
    if str(getattr(request, "intent", "") or "").strip().lower() == "plan":
        return True
    if not isinstance(payload, dict):
        return False
    raw_intent = str(payload.get("intent") or "").strip().lower()
    if raw_intent == "plan":
        return True
    raw_view = str(payload.get("active_view") or payload.get("activeView") or "").strip().lower()
    return raw_view == "plan"


def _request_is_library_agent_turn(
    request: TurnRequest | SessionMessageRequest,
    payload: dict | None = None,
) -> bool:
    """Resources library work uses the same executable agent loop as formal-plan turns."""

    if str(getattr(request, "active_view", "") or "").strip().lower() == "resources":
        return True
    if str(getattr(request, "intent", "") or "").strip().lower() == "resources":
        return True
    if getattr(request, "resource_composer_intent", None) is not None:
        return True
    if not isinstance(payload, dict):
        return False
    raw_intent = str(payload.get("intent") or "").strip().lower()
    if raw_intent == "resources":
        return True
    raw_view = str(payload.get("active_view") or payload.get("activeView") or "").strip().lower()
    return raw_view == "resources"


def _workspace_snapshot_from_payload(payload: dict | None) -> dict | None:
    if not isinstance(payload, dict):
        return None
    snapshot = payload.get("workspace_file_snapshot") or payload.get("workspaceFileSnapshot")
    return snapshot if isinstance(snapshot, dict) and snapshot else None


def _attach_requested_workspace_files(
    payload: dict[str, object],
    runtime: object,
    workspace_id: str | None,
) -> dict[str, object]:
    getter = getattr(runtime, "requested_workspace_file_paths", None)
    files = getter(workspace_id) if callable(getter) else []
    if not files:
        return payload
    payload["requested_workspace_files"] = list(files)
    payload["requestedWorkspaceFiles"] = list(files)
    return payload


def _stamp_library_sandbox_work(
    coach_context: dict[str, object] | None,
    request: TurnRequest | SessionMessageRequest,
    payload: dict | None = None,
) -> None:
    if not isinstance(coach_context, dict):
        return
    snapshot = getattr(request, "workspace_file_snapshot", None)
    if snapshot is None and isinstance(payload, dict):
        snapshot = payload.get("workspace_file_snapshot") or payload.get("workspaceFileSnapshot")
    if isinstance(snapshot, dict) and snapshot:
        coach_context["workspace_file_snapshot"] = snapshot
        if snapshot.get("is_remote") is True:
            coach_context["library_sandbox_work"] = True
    if _request_is_library_agent_turn(request, payload):
        coach_context["library_sandbox_work"] = True
    composer = getattr(request, "resource_composer_intent", None)
    if composer is None:
        return
    mode = str(getattr(composer, "mode", "") or "").strip().lower()
    coach_context["resource_composer_intent"] = {
        "mode": mode,
        "resource_ids": list(getattr(composer, "resource_ids", []) or []),
    }
    if mode == "download":
        coach_context["explicit_resource_import"] = True
    if mode == "organize":
        coach_context["explicit_resource_organize"] = True


def _resolve_agent_loop_enabled(
    request: TurnRequest | SessionMessageRequest,
    coaching_service: ProviderService,
    *,
    stream: bool = False,
    payload: dict | None = None,
) -> bool:
    """Choose the tool loop only for requests that need executable tool authority."""
    config = getattr(coaching_service, "_config", None)
    capabilities = getattr(config, "capabilities", None) if config is not None else None
    supports_tools = getattr(coaching_service, "supports_executable_tools", None)
    provider_supports_tools = (
        bool(supports_tools())
        if callable(supports_tools)
        else bool(
            coaching_service.has_api_key
            and capabilities is not None
            and bool(getattr(capabilities, "tools", False))
        )
    )
    formal_plan_turn = bool(
        isinstance(request, TurnRequest)
        and request.intent == "plan"
        and request.formal_plan_mutation
    )
    snapshot = getattr(request, "workspace_file_snapshot", None)
    if snapshot is None and isinstance(payload, dict):
        snapshot = payload.get("workspace_file_snapshot") or payload.get("workspaceFileSnapshot")
    remote_workspace_turn = isinstance(snapshot, dict) and snapshot.get("is_remote") is True
    if remote_workspace_turn and provider_supports_tools:
        return True
    if formal_plan_turn:
        # A formal plan is a model-authored mutation. Never silently downgrade
        # it to the local planner when the caller omitted useAgentLoop.
        return provider_supports_tools
    if _request_is_plan_agent_turn(request, payload):
        explicit_flag = request.use_agent_loop
        if explicit_flag is None and isinstance(payload, dict):
            if "use_agent_loop" in payload:
                explicit_flag = payload.get("use_agent_loop")
            elif "useAgentLoop" in payload:
                explicit_flag = payload.get("useAgentLoop")
        if explicit_flag is False:
            return False
        return provider_supports_tools
    if _request_is_library_agent_turn(request, payload):
        # Resources/library turns need the same ReAct loop so the coach can
        # list, edit, and index the managed sandbox instead of talking about it.
        # An explicit false still lets a host keep a resources discussion on
        # the plain model stream.
        explicit_flag = request.use_agent_loop
        if explicit_flag is None and isinstance(payload, dict):
            if "use_agent_loop" in payload:
                explicit_flag = payload.get("use_agent_loop")
            elif "useAgentLoop" in payload:
                explicit_flag = payload.get("useAgentLoop")
        if explicit_flag is False:
            return False
        return provider_supports_tools
    # Images use the independently verified vision/image transport gate; file
    # attachments require the executable tools binding for grounded reads.
    if request.attachments:
        return bool(
            coaching_service.has_api_key
            and all(getattr(attachment, "kind", "image") == "image" for attachment in request.attachments)
        )
    if request.use_agent_loop is not None:
        # Explicit Agent requests must have a verified tools capability in both
        # buffered and streaming paths. The previous non-streaming branch
        # accepted any keyed provider, then failed later inside tool binding.
        return bool(request.use_agent_loop) and provider_supports_tools
    # Plan discussion and Training feedback stay on the model stream unless the
    # host asked for tools. Resources/library work is handled above.
    return False


def _request_requires_agent_tools(request: TurnRequest | SessionMessageRequest) -> bool:
    """Return whether a request needs verified executable tool authority."""
    formal_plan_turn = bool(
        isinstance(request, TurnRequest)
        and request.intent == "plan"
        and request.formal_plan_mutation
    )
    # Image attachments use the independent vision gate; file attachments
    # require verified tools because they need grounded file access.
    if formal_plan_turn:
        return True
    if request.attachments:
        return any(getattr(attachment, "kind", "image") == "file" for attachment in request.attachments)
    return request.use_agent_loop is True


def _normalize_resource_turn_request(request: TurnRequest) -> TurnRequest:
    """Treat the Resources composer lane as a grounded coach turn internally."""
    if request.intent != "resources":
        return request
    return request.model_copy(update={"intent": "coach"})


def overlay_session_response_honesty_stamps(
    payload: dict[str, object],
    *,
    pressure_blocks: bool = False,
    streak_blocks: bool = False,
    recovered_leftover: bool = False,
) -> dict[str, object]:
    """Fail-closed: ensure honesty stamps on a (possibly cached) session payload.

    Completed-session request dedup must not serve an older snapshot that dropped
    pressure/streak mint-blocks or leftover-not-live recovered after a later hydrate.
    Stamps are additive only (never cleared).
    """
    if not pressure_blocks and not streak_blocks and not recovered_leftover:
        return payload

    out = copy.deepcopy(payload)

    def _stamp_mapping(target: dict[str, object]) -> None:
        if pressure_blocks:
            target["pressure_blocks_live_object_mint"] = True
        if streak_blocks:
            target["streak_blocks_live_object_mint"] = True

    if pressure_blocks or streak_blocks:
        agent_meta = out.get("agent_meta")
        if not isinstance(agent_meta, dict):
            agent_meta = out.get("agent")
        if not isinstance(agent_meta, dict):
            agent_meta = {"agentic": False}
        else:
            agent_meta = dict(agent_meta)
        _stamp_mapping(agent_meta)
        out["agent_meta"] = agent_meta
        out["agent"] = agent_meta

        coach_turn = out.get("coach_turn")
        if isinstance(coach_turn, dict):
            coach_turn = dict(coach_turn)
            out["coach_turn"] = coach_turn
            ctx = coach_turn.get("coach_context") or coach_turn.get("coachContext")
            if not isinstance(ctx, dict):
                ctx = {}
            else:
                ctx = dict(ctx)
            coach_turn["coach_context"] = ctx
            _stamp_mapping(ctx)

        reply = out.get("reply")
        if isinstance(reply, dict):
            reply = dict(reply)
            out["reply"] = reply
            meta = reply.get("metadata")
            if not isinstance(meta, dict):
                meta = {}
            else:
                meta = dict(meta)
            reply["metadata"] = meta
            focus = meta.get("coach_focus") or meta.get("coachFocus")
            if not isinstance(focus, dict):
                focus = {}
            else:
                focus = dict(focus)
            meta["coach_focus"] = focus
            _stamp_mapping(focus)

    if recovered_leftover:
        snapshot = out.get("snapshot")
        if isinstance(snapshot, dict):
            snapshot = dict(snapshot)
            out["snapshot"] = snapshot
            status = snapshot.get("plan_runtime_status") or snapshot.get("planRuntimeStatus")
            if not isinstance(status, dict):
                status = {}
            else:
                status = dict(status)
            snapshot["plan_runtime_status"] = status
            status["recovered"] = True

    return out


def claim_session_request_singleflight(
    request_key: tuple[str, str, str],
    *,
    completed: dict[tuple[str, str, str], dict[str, object]],
    inflight: dict[tuple[str, str, str], asyncio.Future],
    guard: Lock,
) -> tuple[Literal["cached", "owner", "wait"], dict[str, object] | None, asyncio.Future | None]:
    """Fail-closed: same request_id is single-flight — wait or own, never double-exec."""
    with guard:
        cached = completed.get(request_key)
        if cached is not None:
            return "cached", cached, None
        existing = inflight.get(request_key)
        if existing is not None and not existing.done():
            return "wait", None, existing
        if existing is not None:
            inflight.pop(request_key, None)
        future: asyncio.Future = asyncio.get_running_loop().create_future()
        inflight[request_key] = future
        return "owner", None, future


def publish_session_request_singleflight(
    request_key: tuple[str, str, str],
    payload: dict[str, object],
    *,
    completed: dict[tuple[str, str, str], dict[str, object]],
    inflight: dict[tuple[str, str, str], asyncio.Future],
    guard: Lock,
) -> dict[str, object]:
    """Store completed payload and release any same-request_id waiters."""
    with guard:
        completed[request_key] = payload
        future = inflight.pop(request_key, None)
    if future is not None and not future.done():
        future.set_result(payload)
    return payload


def fail_session_request_singleflight(
    request_key: tuple[str, str, str],
    error: BaseException,
    *,
    inflight: dict[tuple[str, str, str], asyncio.Future],
    guard: Lock,
) -> None:
    """Release waiters with the owner failure — do not leave them hung."""
    with guard:
        future = inflight.pop(request_key, None)
    if future is not None and not future.done():
        future.set_exception(error)


def build_router(runtime: TrainerRuntime) -> APIRouter:
    router = APIRouter()
    asset_library = AssetLibraryService(runtime.repository)
    action_id_counter = 0
    resource_training_card_locks: dict[str, Lock] = {}
    resource_training_card_locks_guard = Lock()

    # Stream cancellation is deliberately scoped to this router/runtime. The
    # sidecar is a local process, so an in-memory registry gives the active
    # request and the explicit cancel endpoint a shared, bounded signal
    # without persisting transient transport state in the learner session.
    stream_cancellation_events: dict[str, asyncio.Event] = {}
    stream_cancellation_guard = Lock()
    completed_session_requests: dict[tuple[str, str, str], dict[str, object]] = {}
    completed_session_requests_guard = Lock()
    # First-pass same request_id must not double-mint; waiters share owner result.
    # Shared across /session/message(+stream) and /turn(+stream): same
    # (workspace_id, session_id, request_id) key is one inflight/completed entry.
    inflight_session_requests: dict[tuple[str, str, str], asyncio.Future] = {}
    # Explicit /training/generate-card/stream — separate from coach session/turn so
    # a coaching request_id never collapses with a card mint (or vice versa).
    completed_training_card_requests: dict[tuple[str, str, str], dict[str, object]] = {}
    completed_training_card_requests_guard = Lock()
    inflight_training_card_requests: dict[tuple[str, str, str], asyncio.Future] = {}

    def resolve_stream_id(payload: object) -> str:
        value = None
        if isinstance(payload, dict):
            value = payload.get("stream_id") or payload.get("streamId")
        normalized = str(value or "").strip()
        if not normalized or len(normalized) > 256:
            return f"stream_{uuid4().hex}"
        return normalized

    def register_stream_cancellation(stream_id: str) -> None:
        with stream_cancellation_guard:
            if stream_id in stream_cancellation_events:
                raise HTTPException(status_code=409, detail="This Trainer stream_id is already active.")
            stream_cancellation_events[stream_id] = asyncio.Event()

    def unregister_stream_cancellation(stream_id: str) -> None:
        with stream_cancellation_guard:
            stream_cancellation_events.pop(stream_id, None)

    def request_stream_cancellation(stream_id: str) -> bool:
        with stream_cancellation_guard:
            event = stream_cancellation_events.get(stream_id)
            if event is None:
                return False
            event.set()
            return True

    def stream_cancellation_requested(stream_id: str) -> bool:
        with stream_cancellation_guard:
            event = stream_cancellation_events.get(stream_id)
            return bool(event and event.is_set())

    def resource_training_card_lock(workspace_id: str) -> Lock:
        """Keep one workspace's resource-card route and active selection in sync."""

        with resource_training_card_locks_guard:
            return resource_training_card_locks.setdefault(workspace_id, Lock())

    @dataclass(frozen=True)
    class TrainerRootSelection:
        """The user-selected Trainer data container, separate from a code project."""

        root_id: str | None
        root_path: str | None

    project_discoveries: dict[str, tuple[str, ProjectDiscovery, TrainerRootSelection]] = {}
    project_discoveries_guard = Lock()

    class CoachTurnPayload(TypedDict):
        """Stable data returned by ``resolve_coach_turn`` to every reply path."""

        scenario: str
        learner_signal: str
        coach_context: dict[str, object]
        suggested_actions: list[dict[str, object]]
        artifacts: dict[str, object]
        coach_turn: CoachTurnSummary
        stream: bool

    def extract_coach_turn_payload(value: object) -> CoachTurnPayload:
        """Restore the stable coach-turn contract after legacy recovery helpers."""

        if not isinstance(value, dict):
            raise TypeError("Coach turn payload must be a mapping.")
        scenario = value.get("scenario")
        learner_signal = value.get("learner_signal")
        coach_context = value.get("coach_context")
        suggested_actions = value.get("suggested_actions")
        artifacts = value.get("artifacts")
        coach_turn = value.get("coach_turn")
        stream = value.get("stream")
        if not isinstance(scenario, str) or not isinstance(learner_signal, str):
            raise TypeError("Coach turn payload is missing its text fields.")
        if not isinstance(coach_context, dict) or not isinstance(artifacts, dict):
            raise TypeError("Coach turn payload is missing its mapping fields.")
        if not isinstance(suggested_actions, list) or not all(
            isinstance(action, dict) for action in suggested_actions
        ):
            raise TypeError("Coach turn payload has invalid suggested actions.")
        if not isinstance(coach_turn, CoachTurnSummary) or not isinstance(stream, bool):
            raise TypeError("Coach turn payload is missing its summary fields.")
        return cast(CoachTurnPayload, value)

    def coach_turn_mapping(value: CoachTurnPayload) -> dict[str, object]:
        """Adapt the stable payload to existing mutable-dict helper boundaries."""

        return cast(dict[str, object], value)

    coach_summary_scenarios = {
        "general",
        "onboarding",
        "idea_implementation",
        "project_idea",
        "project_idea_mining",
        "project_adaptation",
        "project_sourcing",
        "principle",
        "principle_explanation",
        "remote_workspace",
        "debug_loop",
        "function_guidance",
        "review",
        "review_reflection",
        "plan",
        "task",
        "next_task",
    }

    def require_asset_context_authority(context_id: str | None) -> str | None:
        """Resolve only registered project contexts before mutating asset metadata."""

        normalized_context_id = str(context_id or "").strip()
        if not normalized_context_id:
            return None
        context = runtime.repository.get_project_context(normalized_context_id)
        if context is None:
            raise HTTPException(status_code=404, detail="Unknown project context.")
        root = runtime.repository.get_trainer_root(context.root_id)
        if root is None:
            raise HTTPException(status_code=409, detail="Project context has no registered Trainer root.")
        try:
            authority = WorkspaceAuthority(
                root_path=root.root_path,
                initial_permission=PermissionLevel.INSPECT,
            )
        except (OSError, ValueError) as exc:
            raise HTTPException(
                status_code=409,
                detail="Project context root is not available for asset operations.",
            ) from exc
        if not authority.can_perform("list", root.root_path):
            raise HTTPException(status_code=403, detail="Project context is not available for asset inspection.")
        return context.context_id

    def resolve_asset_context_identity(
        project_id: str | None,
        context_id: str | None,
    ) -> tuple[str | None, str | None]:
        normalized_project_id = str(project_id or "").strip() or None
        normalized_context_id = str(context_id or "").strip() or None
        if normalized_context_id:
            canonical_context_id = require_asset_context_authority(normalized_context_id)
            assert canonical_context_id is not None
            context = runtime.repository.get_project_context(canonical_context_id)
            assert context is not None
            if normalized_project_id and context.project_id != normalized_project_id:
                raise HTTPException(status_code=422, detail="projectId does not match contextId.")
            return context.project_id, context.context_id
        if normalized_project_id:
            context = runtime.repository.get_project_context_for_project(normalized_project_id)
            if context is None:
                raise HTTPException(status_code=404, detail="Unknown project.")
            require_asset_context_authority(context.context_id)
            return context.project_id, context.context_id
        return None, None

    def asset_response(asset: LibraryAsset) -> dict[str, object]:
        payload = cast(dict[str, object], asset.model_dump(by_alias=True, mode="json"))
        payload["capabilities"] = asset_library.capabilities(asset)
        payload["sourceState"] = asset_library.source_state(asset)
        return payload

    def prefers_chinese(response_language: str | None) -> bool:
        return bool(response_language and response_language.lower().startswith("zh"))

    def contains_cjk_text(value: str | None) -> bool:
        return bool(value and any("\u3400" <= char <= "\u9fff" for char in value))

    LATIN1_MOJIBAKE_PATTERN = re.compile(
        r"(?:[\u00C2\u00C3\u00C4\u00C5\u00C6\u00C7\u00C8\u00C9\u00CF\u00D0\u00E2\u00E3\u00E4\u00E5\u00E6\u00E7\u00E8\u00E9\u00EF\u00F0][\u0080-\u00BF]{1,2}){2,}"
    )
    GBK_MOJIBAKE_MARKERS = (
        "\u6d93",
        "\u7f01",
        "\u93c8",
        "\u59e3",
        "\u8930",
        "\u93b4",
        "\u9410",
        "\u7487",
        "\u95c4",
        "\u9359",
        "\u9365",
        "\u5a0c",
        "\u741b",
        "\u5bf0",
    )
    GBK_MOJIBAKE_FRAGMENTS = (
        "\u6d93\u5b29\u7af4",
        "\u7f01\u0445\u753b",
        "\u6fe1\u509b\u7049",
        "\u8930\u64b3\u58a0",
        "\u59e3\u5fd3\u59e9",
        "\u93c8\u20ac",
        "\u95c4\u52eb",
        "\u9365\u5267\u5896",
        "\u741b\u30e4\u7af5",
    )

    def looks_like_mojibake_text(value: object) -> bool:
        text = str(value or "").strip()
        if not text:
            return False
        suspicious_markers = ("�", "鈧", "偓", "閸", "鐠", "娑", "缂", "濞", "瑜", "绱", "顒", "鍐")
        return any("\ue000" <= character <= "\uf8ff" for character in text) or any(
            marker in text for marker in suspicious_markers
        ) or any(fragment in text for fragment in GBK_MOJIBAKE_FRAGMENTS) or sum(
            marker in text for marker in GBK_MOJIBAKE_MARKERS
        ) >= 2 or bool(LATIN1_MOJIBAKE_PATTERN.search(text))

    def localized_text(english: str, chinese: str, response_language: str | None) -> str:
        if prefers_chinese(response_language):
            extended_markers = ("\ufffd", "\ue000", "\ue1ec", "鈧", "閸", "鐠", "娑", "缂")
            if looks_like_mojibake_text(chinese) or any(marker in chinese for marker in extended_markers):
                return english
        return chinese if prefers_chinese(response_language) else english

    def localized_actions(
        response_language: str | None,
        english: list[str],
        chinese: list[str],
    ) -> list[str]:
        if not prefers_chinese(response_language):
            return english
        resolved: list[str] = []
        for index, label in enumerate(chinese):
            fallback = english[index] if index < len(english) else ""
            visible_label = fallback if not label or looks_like_mojibake_text(label) else label
            if visible_label:
                resolved.append(visible_label)
        return resolved

    def provider_api_key_from_payload(payload: dict) -> str | None:
        api_key_raw = payload.get("api_key") or payload.get("apiKey")
        return api_key_raw.strip() if isinstance(api_key_raw, str) else None

    def normalize_provider_base_url(value: object, protocol: ProviderProtocol) -> str:
        """Keep a pasted request endpoint from becoming the client's base URL."""
        raw_value = str(value or "").strip()
        if not raw_value:
            return ""

        try:
            parsed = urlsplit(raw_value)
        except ValueError:
            return raw_value.rstrip("/")

        if not parsed.scheme or not parsed.netloc:
            return raw_value.rstrip("/")

        path = parsed.path.rstrip("/")
        lowered_path = path.lower()
        if protocol in {
            "openai_responses",
            "openai_chat_completions",
            "openai_chat_completions_compatible",
        }:
            for suffix in ("/chat/completions", "/responses"):
                if lowered_path.endswith(suffix):
                    path = path[: -len(suffix)] or "/"
                    break
        elif protocol == "anthropic_messages" and lowered_path.endswith("/messages"):
            path = path[: -len("/messages")] or "/"
        elif protocol == "gemini_generate_content":
            model_marker = "/models/"
            marker_index = lowered_path.rfind(model_marker)
            if marker_index >= 0 and lowered_path.endswith(":generatecontent"):
                path = path[:marker_index] or "/"

        return urlunsplit((parsed.scheme, parsed.netloc, path, parsed.query, parsed.fragment))

    def provider_connection_type_from_payload(provider_payload: dict) -> str | None:
        raw = (
            provider_payload.get("connection_type")
            or provider_payload.get("connectionType")
            or provider_payload.get("_type")
            or provider_payload.get("protocol")
        )
        if not isinstance(raw, str):
            return None
        return normalize_provider_connection_type(raw)

    def provider_protocol_from_payload(provider_payload: dict) -> ProviderProtocol | None:
        raw = provider_payload.get("protocol") or provider_payload.get("api") or ""
        value = str(raw or "").strip().lower()
        if not value:
            return None
        if normalize_provider_connection_type(value) is not None:
            return None
        if value in {"anthropic_messages", "anthropic", "claude"}:
            return "anthropic_messages"
        if value in {"openai_responses", "responses"}:
            return "openai_responses"
        if value in {"gemini_generate_content", "gemini", "google"}:
            return "gemini_generate_content"
        if value in {"openai_chat_completions", "openai"}:
            return "openai_chat_completions"
        if value in {"openai_chat_completions_compatible", "openai-compatible", "compatible"}:
            return "openai_chat_completions_compatible"
        return normalize_provider_protocol(value)

    def provider_mode_from_payload(
        provider_payload: dict,
    ) -> Literal["direct", "gateway"] | None:
        raw_mode = provider_payload.get("mode")
        if not isinstance(raw_mode, str):
            return None
        normalized_mode = raw_mode.strip()
        if normalized_mode == "direct":
            return "direct"
        if normalized_mode == "gateway":
            return "gateway"
        return None

    def provider_credential_mode_from_payload(
        provider_payload: dict,
    ) -> ProviderCredentialMode | None:
        raw_mode = provider_payload.get("credential_mode") or provider_payload.get("credentialMode")
        if not isinstance(raw_mode, str):
            return None
        normalized_mode = raw_mode.strip()
        if normalized_mode == "workspace_secret":
            return "workspace_secret"
        if normalized_mode == "ui_proxy":
            return "ui_proxy"
        return None

    def provider_payload_declares_protocol(provider_payload: dict) -> bool:
        for key in ("protocol", "api", "provider_key", "providerKey"):
            raw_value = provider_payload.get(key)
            if isinstance(raw_value, str) and raw_value.strip():
                return True
        return False

    def provider_capabilities_from_payload(provider_payload: dict) -> CapabilityFlags:
        explicit_capabilities = provider_payload.get("capabilities")
        if isinstance(explicit_capabilities, dict) and explicit_capabilities:
            return CapabilityFlags.model_validate(explicit_capabilities)
        protocol = provider_protocol_from_payload(provider_payload) or (
            "openai_chat_completions_compatible"
        )
        defaults = default_capabilities_for_protocol(protocol)
        if not provider_payload_declares_protocol(provider_payload):
            defaults = defaults.model_copy(
                update={
                    "embeddings": False,
                    "tools": False,
                    "json_schema": False,
                    "structured_output": False,
                }
            )
        return defaults

    def provider_declared_window_payload(
        provider: ProviderConfig | None,
    ) -> dict[str, object]:
        if provider is None:
            return {
                "context_window_tokens": None,
                "max_output_tokens": None,
                "model_token_limits": {},
                "capabilities": {},
                "model_capabilities": {},
            }

        limits: dict[str, object] = {}
        raw_limits = getattr(provider, "model_token_limits", None) or {}
        if isinstance(raw_limits, dict):
            for model_name, limit in raw_limits.items():
                key = str(model_name).strip()
                if not key:
                    continue
                if hasattr(limit, "model_dump"):
                    dumped = limit.model_dump(by_alias=True)
                elif isinstance(limit, dict):
                    dumped = dict(limit)
                else:
                    dumped = {}
                limits[key] = dumped

        window = provider.context_window_tokens
        max_output = provider.max_output_tokens
        model = str(provider.model or "").strip()
        if model and window and model not in limits:
            entry: dict[str, object] = {
                "contextWindowTokens": window,
                "context_window_tokens": window,
            }
            if max_output:
                entry["maxOutputTokens"] = max_output
                entry["max_output_tokens"] = max_output
            limits[model] = entry

        capabilities: dict[str, object] = {}
        flags = getattr(provider, "capabilities", None)
        if hasattr(flags, "model_dump"):
            capabilities = flags.model_dump(by_alias=True)
        elif isinstance(flags, dict):
            capabilities = dict(flags)

        serialized_model_capabilities: dict[str, object] = {}
        raw_model_capabilities = getattr(provider, "model_capabilities", None) or {}
        if isinstance(raw_model_capabilities, dict):
            for cap_model, cap_flags in raw_model_capabilities.items():
                cap_key = str(cap_model).strip()
                if not cap_key:
                    continue
                if hasattr(cap_flags, "model_dump"):
                    serialized_model_capabilities[cap_key] = cap_flags.model_dump(by_alias=True)
                elif isinstance(cap_flags, dict):
                    serialized_model_capabilities[cap_key] = dict(cap_flags)
        if model and capabilities and model not in serialized_model_capabilities:
            serialized_model_capabilities[model] = capabilities

        return {
            "context_window_tokens": window,
            "max_output_tokens": max_output,
            "model_token_limits": limits,
            "capabilities": capabilities,
            "model_capabilities": serialized_model_capabilities,
        }

    def empty_provider_test_capability_payload(
        provider: ProviderConfig | None = None,
    ) -> dict[str, object]:
        return {
            "capability_evidence": [],
            "tools_ready": False,
            "tool_probe_status": "unverified",
            "streaming_ready": False,
            "stream_probe_status": "unverified",
            "vision_ready": False,
            "vision_probe_status": "unverified",
            "thinking_ready": False,
            "thinking_probe_status": "unverified",
            "base_url": (provider.base_url if provider is not None else None) or None,
            "model": (provider.model if provider is not None else None) or None,
            "available_models": [],
            "resolved_model": None,
            "warnings": [],
            **provider_declared_window_payload(provider),
        }

    def provider_test_capability_payload(
        provider: ProviderConfig,
        result: ProviderTestResponse | None = None,
    ) -> dict[str, object]:
        if result is None or result.ok is not True:
            return empty_provider_test_capability_payload(provider)
        evidence = list(result.capability_evidence) if result.capability_evidence else []
        serialized = [
            {
                "name": item.name,
                "declared": item.declared,
                "observed": item.observed,
                "state": item.state,
            }
            for item in evidence
        ]

        def verified_ready(name: str, ready_flag: bool) -> bool:
            match = next(
                (item for item in serialized if str(item.get("name") or "").strip().lower() == name),
                None,
            )
            return bool(
                ready_flag
                and match
                and match.get("state") == "verified"
                and match.get("observed") is True
            )

        tools_ready = verified_ready("tools", bool(result.tools_ready))
        streaming_ready = verified_ready("streaming", bool(result.streaming_ready))
        vision_ready = verified_ready("vision", bool(result.vision_ready))
        thinking_ready = verified_ready("thinking", bool(result.thinking_ready))
        tools = next((item for item in serialized if item["name"] == "tools"), None)
        streaming = next((item for item in serialized if item["name"] == "streaming"), None)
        vision = next((item for item in serialized if item["name"] == "vision"), None)
        thinking = next((item for item in serialized if item["name"] == "thinking"), None)
        return {
            "capability_evidence": serialized,
            "tools_ready": tools_ready,
            "tool_probe_status": "verified" if tools_ready else str(tools.get("state") if tools else "unverified"),
            "streaming_ready": streaming_ready,
            "stream_probe_status": "verified" if streaming_ready else str(
                streaming.get("state") if streaming else "unverified"
            ),
            "vision_ready": vision_ready,
            "vision_probe_status": "verified" if vision_ready else str(
                vision.get("state") if vision else "unverified"
            ),
            "thinking_ready": thinking_ready,
            "thinking_probe_status": "verified" if thinking_ready else str(
                thinking.get("state") if thinking else "unverified"
            ),
            "base_url": provider.base_url or None,
            "model": provider.model or None,
            "available_models": [],
            "resolved_model": None,
            "warnings": [],
            **provider_declared_window_payload(provider),
        }

    def provider_config_from_payload(payload: dict) -> ProviderConfig | None:
        provider_payload = payload.get("provider")
        if not isinstance(provider_payload, dict):
            return None
        provider_protocol = provider_protocol_from_payload(provider_payload)
        declared_protocol_raw = provider_payload.get("protocol") or provider_payload.get("api")
        declared_protocol = (
            isinstance(declared_protocol_raw, str) and bool(str(declared_protocol_raw).strip())
        )
        connection_type = provider_connection_type_from_payload(provider_payload)
        if declared_protocol and provider_protocol is None:
            return None
        if provider_protocol is None and connection_type == NEWAPI_CONNECTION_TYPE:
            return None
        if provider_protocol is None:
            provider_protocol = "openai_chat_completions_compatible"
        provider_name_raw = (
            provider_payload.get("name")
            or provider_payload.get("label")
            or provider_payload.get("provider_key")
            or provider_payload.get("providerKey")
            or provider_payload.get("api")
            or "custom-openai-compatible"
        )
        return ProviderConfig(
            name=str(provider_name_raw).strip() or "custom-openai-compatible",
            baseUrl=normalize_provider_base_url(
                provider_payload.get("base_url") or provider_payload.get("baseUrl", ""),
                provider_protocol,
            ),
            apiKeyRef=provider_payload.get("api_key_ref")
            or provider_payload.get("apiKeyRef", "trainer.default"),
            model=(provider_payload.get("model", "") or "").strip(),
            protocol=provider_protocol,
            label=(provider_payload.get("label") or provider_payload.get("name") or "").strip() or None,
            mode=provider_mode_from_payload(provider_payload),
            connectionType=connection_type,
            credentialMode=provider_credential_mode_from_payload(provider_payload),
            availableModels=list(provider_payload.get("available_models") or provider_payload.get("availableModels") or []),
            allowedModels=list(provider_payload.get("allowed_models") or provider_payload.get("allowedModels") or []),
            deniedModels=list(provider_payload.get("denied_models") or provider_payload.get("deniedModels") or []),
            modelAliases=dict(provider_payload.get("model_aliases") or provider_payload.get("modelAliases") or {}),
            modelCapabilities=dict(
                provider_payload.get("model_capabilities") or provider_payload.get("modelCapabilities") or {}
            ),
            modelTokenLimits=dict(
                provider_payload.get("model_token_limits") or provider_payload.get("modelTokenLimits") or {}
            ),
            taskBindings=dict(provider_payload.get("task_bindings") or provider_payload.get("taskBindings") or {}),
            contextWindowTokens=provider_payload.get("context_window_tokens")
            or provider_payload.get("contextWindowTokens"),
            maxOutputTokens=provider_payload.get("max_output_tokens")
            or provider_payload.get("maxOutputTokens"),
            embeddingModel=provider_payload.get("embedding_model")
            or provider_payload.get("embeddingModel"),
            catalogSource=(provider_payload.get("catalog_source") or provider_payload.get("catalogSource") or "").strip()
            or None,
            cacheTtlSeconds=provider_payload.get("cache_ttl_seconds")
            or provider_payload.get("cacheTtlSeconds"),
            profileId=(provider_payload.get("profile_id") or provider_payload.get("profileId") or "").strip()
            or None,
            profileLabel=(provider_payload.get("profile_label") or provider_payload.get("profileLabel") or "").strip()
            or None,
            profileMode=(provider_payload.get("profile_mode") or provider_payload.get("profileMode") or "").strip()
            or None,
            requestDefaults=provider_payload.get("request_defaults")
            or provider_payload.get("requestDefaults")
            or {},
            capabilities=provider_capabilities_from_payload(provider_payload),
        )

    def should_probe_language_integrity(message: str | None, response_language: str | None) -> bool:
        return prefers_chinese(response_language) or contains_cjk_text(message)

    KNOWN_CONTEXT_TRANSLATIONS_ZH: tuple[tuple[str, str], ...] = (
        ("function contract and call-site reading", "\u51fd\u6570\u5951\u7ea6\u4e0e call site \u5224\u65ad"),
        ("the smallest trustworthy debug loop", "最小可信的 debug loop"),
        ("remote workspace boundary", "远程工作区边界"),
        ("VS Code remote workflow", "VS Code 远程工作区"),
        ("Code remote workflow", "远程工作区边界"),
        ("VS Code remote workspace", "VS Code 远程工作区"),
        ("VS Code function guidance", "VS Code 函数提示"),
        ("function contract recovery", "\u6062\u590d\u51fd\u6570\u5951\u7ea6"),
        ("VS Code debug loop", "VS Code 调试闭环"),
    )

    def localize_known_context_phrases(
        value: str,
        response_language: str | None,
    ) -> str:
        if not value or not prefers_chinese(response_language):
            return value

        cleaned = value
        lane_match = re.match(
            r"""^Continue\s+['"](?P<focus>.+?)['"]\s+and do not open a new lane before this next move lands:\s*(?P<rest>.+)$""",
            cleaned,
            flags=re.IGNORECASE,
        )
        if lane_match:
            localized_focus = localize_known_context_phrases(
                lane_match.group("focus").strip(),
                response_language,
            )
            localized_rest = localize_known_context_phrases(
                lane_match.group("rest").strip(),
                response_language,
            )
            return f"继续沿着「{localized_focus}」这条主线，先别开新线：{localized_rest}".strip()

        for source, target in KNOWN_CONTEXT_TRANSLATIONS_ZH:
            cleaned = re.sub(re.escape(source), target, cleaned, flags=re.IGNORECASE)

        exact_focus_map = {
            "debug loop": "调试闭环",
            "function contract": "\u51fd\u6570\u5951\u7ea6\u5224\u65ad",
            "call-site reading": "call site 判断",
        }
        normalized_cleaned = cleaned.strip()
        localized_exact = exact_focus_map.get(normalized_cleaned.casefold())
        if localized_exact:
            return localized_exact

        return cleaned

    def language_aligned_context_text(
        value: object,
        response_language: str | None,
    ) -> str:
        if not isinstance(value, str):
            return ""
        normalized = re.sub(r"\s+", " ", value).strip()
        if not normalized:
            return ""
        if prefers_chinese(response_language) and looks_like_mojibake_text(normalized):
            return ""
        if not prefers_chinese(response_language) and contains_cjk_text(normalized):
            latin_fragments = [
                re.sub(r"\s+", " ", fragment).strip(" \t\r\n-:;,.!?/|()[]{}<>")
                for fragment in re.split(r"[\u3400-\u9fff]+", normalized)
            ]
            salvage = " ".join(
                fragment
                for fragment in latin_fragments
                if fragment and re.search(r"[A-Za-z0-9`]", fragment)
            ).strip()
            return normalize_visible_coach_text(salvage)
        return localize_known_context_phrases(
            normalize_visible_coach_text(normalized),
            response_language,
        )

    def language_aligned_context_list(
        value: object,
        response_language: str | None,
        *,
        limit: int | None = None,
    ) -> list[str]:
        if not isinstance(value, list):
            return []
        aligned: list[str] = []
        for item in value:
            normalized = language_aligned_context_text(item, response_language)
            if not normalized or normalized in aligned:
                continue
            aligned.append(normalized)
            if limit is not None and len(aligned) >= limit:
                break
        return aligned

    def language_aligned_flat_payload(
        value: dict[str, object] | None,
        response_language: str | None,
        *,
        list_limit: int = 6,
    ) -> dict[str, object] | None:
        if not isinstance(value, dict):
            return None
        aligned = dict(value)
        for key, item in list(aligned.items()):
            if isinstance(item, str):
                aligned[key] = language_aligned_context_text(item, response_language)
                continue
            if isinstance(item, list):
                if all(not isinstance(entry, dict) for entry in item):
                    aligned[key] = language_aligned_context_list(
                        item,
                        response_language,
                        limit=list_limit,
                    )
        return aligned

