    def focus_looks_like_request_sentence(value: object) -> bool:
        cleaned = normalize_focus_candidate(value)
        if not cleaned:
            return False
        lowered = cleaned.lower()
        if lowered.startswith(
            (
                "teach me ",
                "help me ",
                "show me ",
                "tell me ",
                "walk me through ",
                "how to ",
                "this is ",
                "i want ",
                "create ",
                "generate ",
                "please ",
                "continue ",
            )
        ):
            return True
        return len(cleaned.split()) >= 7 and any(
            token in lowered
            for token in (
                "remote workspace",
                "debug loop",
                "typescript function",
                "function",
            )
        )

