    def guided_lane_comparison_requested(message: str | None) -> bool:
        lowered = str(message or "").casefold()
        if not lowered:
            return False
        markers = (
            "compare",
            "comparison",
            "difference",
            "different",
            "versus",
            "compared to",
            "对比",
            "区别",
            "相比",
        )
        return any(marker.casefold() in lowered for marker in markers)

