    def clean_active_thread_task(
        task: TaskSpec,
        response_language: str | None,
        active_thread: object | None,
        *,
        plan: LearningPlan | None = None,
        snapshot: WorkbenchSnapshot | None = None,
        runtime: dict[str, object] | None = None,
    ) -> TaskSpec:
        if task.metadata.get("source") != "active_thread":
            return task

        def _thread_text(key: str) -> str:
            if active_thread is None:
                return ""
            if isinstance(active_thread, dict):
                return str(active_thread.get(key) or "").strip()
            return str(getattr(active_thread, key, "") or "").strip()

        def _first_clean_step() -> str:
            leftover_runtime = runtime if isinstance(runtime, dict) else coach_focus_runtime_from_snapshot(snapshot)
            candidates = live_task_clean_step_candidates(
                plan=plan,
                task=task,
                runtime=leftover_runtime,
                existing=leftover_runtime,
                next_step=_thread_text("next_step"),
                goal=task.natural_language_goal,
                task_title=task.title,
            )
            for candidate in candidates:
                text = normalize_visible_coach_text(candidate)
                if not text:
                    continue
                if prefers_chinese(response_language):
                    provider_index = text.find("\u5148\u5207\u6362 provider")
                    if provider_index >= 0:
                        return text[provider_index:].strip(" \t\r\n:：。") + "\u3002"
                    if contains_cjk_text(text) and not looks_like_mojibake_text(text):
                        return text
                    continue
                if not looks_like_mojibake_text(text):
                    return text
            return localized_text(
                "Return to the current coaching thread and verify one small next move.",
                "\u5148\u5207\u6362 provider \u6216 gateway\uff0c\u518d\u56de\u5230\u5f53\u524d\u6559\u7ec3\u4e3b\u7ebf\u505a\u4e00\u4e2a\u5c0f\u9a8c\u8bc1\u3002",
                response_language,
            )

        needs_cleanup = any(
            looks_like_mojibake_text(value)
            for value in (
                task.title,
                task.natural_language_goal,
                *task.outputs,
                *task.constraints,
                *task.verification_strategy,
            )
        )
        if not prefers_chinese(response_language) and not needs_cleanup:
            return task

        focus = display_focus_label(
            _thread_text("focus_area")
            or (str(task.metadata.get("concepts", [""])[0]) if task.metadata.get("concepts") else ""),
            response_language,
        )
        next_step = _first_clean_step()
        if prefers_chinese(response_language):
            return task.model_copy(
                update={
                    "title": f"\u7ee7\u7eed\uff1a{focus}",
                    "natural_language_goal": (
                        "\u6cbf\u7740\u5f53\u524d\u6559\u7ec3\u4e3b\u7ebf\u7ee7\u7eed\u63a8\u8fdb\uff1a"
                        f"{next_step}"
                    ),
                    "inputs": ["\u5f53\u524d project context", "\u5f53\u524d\u6587\u4ef6\uff08\u5982\u679c\u76f8\u5173\uff09"],
                    "outputs": [
                        "\u4e00\u4e2a\u56f4\u7ed5\u5f53\u524d\u4e3b\u7ebf\u7684\u5c0f\u4fee\u6539",
                        "\u4e00\u4e2a\u5feb\u901f\u9a8c\u8bc1\u7ed3\u679c",
                    ],
                    "constraints": ["\u8fd9\u4e00\u6b65\u843d\u5730\u524d\uff0c\u4e0d\u8981\u6269\u5927\u8303\u56f4\u3002"],
                    "verification_strategy": [
                        "\u8865\u4e01\u843d\u5730\u540e\uff0c\u53ea\u9a8c\u8bc1\u5f53\u524d\u4e3b\u7ebf\u8fd9\u4e00\u6b65\u662f\u5426\u6210\u7acb\u3002"
                    ],
                }
            )
        return task.model_copy(
            update={
                "title": f"Continue: {focus}",
                "natural_language_goal": (
                    "Stay on the current coaching thread and finish one small verifiable move: "
                    f"{next_step}"
                ),
                "outputs": [
                    "One focused change on the active thread",
                    "One quick verification result",
                ],
                "constraints": ["Do not widen scope before this move lands."],
                "verification_strategy": [
                    "After the patch lands, verify only this active-thread step."
                ],
            }
        )

    def preview_coach_context(
        *,
        workspace_id: str,
        snapshot: WorkbenchSnapshot,
        profile: UserProfile | None,
        response_language: str | None,
        answer_mode: str | None,
        scenario: str | None,
        learner_signal: str | None,
    ) -> dict[str, object]:
        preview = snapshot.model_copy(deep=True)
        preview.profile = profile
        preview.memory = runtime.memory_service.snapshot(workspace_id)
        leftover_runtime = coach_focus_runtime_from_snapshot(snapshot)
        language_hint = live_language_detection_hint(
            plan=snapshot.plan,
            task=snapshot.current_task,
            runtime=leftover_runtime,
            existing=leftover_runtime,
            hint=snapshot.current_task.natural_language_goal if snapshot.current_task else "",
            goal=snapshot.current_task.natural_language_goal if snapshot.current_task else "",
            task_title=snapshot.current_task.title if snapshot.current_task else "",
        )
        resolved_response_language = effective_response_language(
            workspace_id,
            response_language,
            language_hint or None,
        )
        resolved_answer_mode = effective_answer_mode(
            workspace_id,
            answer_mode,
            profile,
            message=snapshot.messages[-1].content if snapshot.messages else None,
        )
        hydrate_snapshot(
            preview,
            response_language=resolved_response_language,
            answer_mode=resolved_answer_mode,
            scenario=scenario,
            learner_signal=learner_signal,
            message=snapshot.messages[-1].content if snapshot.messages else None,
            session_workspace_id=workspace_id,
        )
        return build_coach_context(
            preview,
            response_language=resolved_response_language,
            message=snapshot.messages[-1].content if snapshot.messages else None,
        )

    async def execute_turn(
        request: TurnRequest,
        payload: dict,
        *,
        stream: bool = False,
        stream_id: str | None = None,
    ) -> tuple[object, object, object]:
        workspace_id = current_workspace_id(session_id=request.session_id, workspace_id=request.workspace_id)
        state = runtime.ensure_session(request.session_id, workspace_id=workspace_id)
        profile = resolved_profile(state.workspace_id)
        frozen_formal_plan_mutation_requested = bool(
            request.intent == "plan"
            and request.formal_plan_mutation
            and leftover_frozen_blocks_turn_generation(state.workspace_id)
        )
        raw_requested_answer_mode = str(
            payload.get("answer_mode") or payload.get("answerMode") or ""
        ).strip()
        saved_answer_mode = str(workspace_preferences(workspace_id).get("answer_mode") or "").strip()
        request = request_with_workspace_defaults(
            request,
            workspace_id=workspace_id,
            profile=profile,
        )
        profile = profile_with_teaching_style(profile, request.teaching_style)
        coaching_service = build_coaching_service(payload)
        use_agent_loop = _resolve_agent_loop_enabled(
            request, coaching_service, stream=stream, payload=payload
        )
        ensure_coach_provider_ready(
            coaching_service,
            response_language=request.response_language,
        )
        provider_live_usable = provider_is_live_usable(coaching_service, payload)
        if provider_live_usable:
            ensure_agent_tools_ready(request, coaching_service)
        attachments_payload = [a.model_dump() for a in request.attachments]
        attachment_delivery = describe_request_attachment_delivery(
            request,
            coaching_service,
            use_agent_loop=use_agent_loop,
        )

        user_message = ChatMessage(
            id=f"message-{uuid4().hex[:10]}",
            role="user",
            content=request.message,
            timestamp=datetime.now(UTC),
            metadata=build_user_message_metadata(
                request,
                profile,
                attachment_delivery,
                stream_id=stream_id,
                stream_state="in_progress" if stream_id else None,
            ),
        )
        state.snapshot.messages.append(user_message)
        state.snapshot.profile = profile
        if stream:
            runtime.save_session_state(state.session_id)

        scenario = infer_coaching_scenario(request)
        suggested_actions = honest_suggested_actions_without_live_object(
            structured_suggested_actions(
                coach_suggested_actions(
                    request.response_language,
                    scenario=scenario,
                    snapshot=state.snapshot,
                ),
                response_language=request.response_language,
                scenario=scenario,
                focus_area=stateful_focus_area(
                    state.snapshot.current_task,
                    state.snapshot.plan,
                    state.snapshot.evaluation,
                    snapshot=state.snapshot,
                ),
            ),
            workspace_id=workspace_id,
            response_language=request.response_language,
            snapshot=state.snapshot,
            current_task=state.snapshot.current_task,
            current_plan=state.snapshot.plan,
            current_evaluation=state.snapshot.evaluation,
            message=request.message,
            scenario=scenario,
        )
        artifacts: dict[str, object] = {}
        assistant_content = ""
        learner_signal = infer_learner_signal(request.message, getattr(request, "current_file", None))
        agent_meta: dict[str, object] = {}
        language_corruption_detected = False
        provider_failure_detected = False

        if request.intent == "coach" and provider_live_usable:
            if stream:
                return state, coaching_service, user_message
            safe_activate_training_card_from_coach_request(
                workspace_id=state.workspace_id,
                snapshot=state.snapshot,
                message=request.message,
                current_file=request.current_file,
                response_language=request.response_language,
                provider_service_override=coaching_service,
            )
            state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
            state.snapshot.profile = profile
            coach_turn: CoachTurnPayload = resolve_coach_turn(
                state=state,
                profile=profile,
                request=request,
                message=request.message,
                coaching_service=coaching_service,
                current_task=state.snapshot.current_task,
                current_plan=state.snapshot.plan,
                current_evaluation=state.snapshot.evaluation,
            )
            scenario = str(coach_turn.get("scenario") or "general")
            if guarantee_guided_learn_first_training_card(
                workspace_id=state.workspace_id,
                scenario=str(coach_turn["scenario"] or ""),
                message=request.message,
                current_file=request.current_file,
                response_language=request.response_language,
                active_thread=state.snapshot.memory.active_thread,
                requested_answer_mode=raw_requested_answer_mode,
                saved_answer_mode=saved_answer_mode,
                profile=profile,
            ):
                state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
            scenario = str(coach_turn["scenario"])
            learner_signal = str(coach_turn["learner_signal"])
            if infer_learner_signal(request.message, getattr(request, "current_file", None)) == "blocked":
                learner_signal = "blocked"
            artifacts = dict(coach_turn["artifacts"])
            suggested_actions = list(coach_turn["suggested_actions"])
            if not provider_live_usable:
                suggested_actions = honest_suggested_actions_without_usable_provider(
                    suggested_actions,
                    response_language=request.response_language,
                    snapshot=state.snapshot,
                    current_task=state.snapshot.current_task,
                    current_plan=state.snapshot.plan,
                    current_evaluation=state.snapshot.evaluation,
                )
            guided_training_prefers_local_reply = should_bypass_agent_loop_for_guided_training(
                workspace_id=state.workspace_id,
                scenario=scenario,
                message=request.message,
                active_view=request.active_view,
                requested_answer_mode=raw_requested_answer_mode,
                saved_answer_mode=saved_answer_mode,
                profile=profile,
            )
            guided_training_local_reply = (
                build_guided_training_visible_fallback(
                    workspace_id=state.workspace_id,
                    response_language=request.response_language,
                )
                if guided_training_prefers_local_reply
                else None
            )
            preflight_language_probe = detect_provider_language_corruption(
                coaching_service,
                message=request.message,
                response_language=request.response_language,
                coach_context=dict(coach_turn["coach_context"]),
            )
            if preflight_language_probe is not None:
                language_corruption_detected = True
                coach_turn = extract_coach_turn_payload(
                    isolate_preflight_language_corruption_turn(
                        coach_turn_mapping(coach_turn),
                        message=request.message,
                        current_file=request.current_file.model_dump() if request.current_file else None,
                    )
                )
                assistant_content, updated_coach_turn, agent_meta = apply_language_corruption_override(
                    coaching_service=coaching_service,
                    snapshot=state.snapshot,
                    coach_turn=coach_turn_mapping(coach_turn),
                    message=request.message,
                    response_language=request.response_language,
                    allow_guided_recovery=False,
                )
                coach_turn = extract_coach_turn_payload(updated_coach_turn)
                ensure_explicit_training_card_after_language_block(
                    state=state,
                    message=request.message,
                    current_file=request.current_file,
                    response_language=request.response_language,
                    fallback_scenario=str(coach_turn.get("scenario") or scenario),
                    force_training_card=(
                        auto_preference_requests_training_card(
                            request.message,
                            requested_scenario=str(coach_turn.get("scenario") or scenario),
                            requested_answer_mode=raw_requested_answer_mode,
                            saved_answer_mode=saved_answer_mode,
                            profile=profile,
                        )
                        or auto_lane_learn_first_force_training_card(
                            request.message,
                            requested_scenario=str(coach_turn.get("scenario") or scenario),
                            requested_answer_mode=raw_requested_answer_mode,
                            saved_answer_mode=saved_answer_mode,
                            profile=profile,
                        )
                ),
                provider_service_override=coaching_service,
            )
                scenario = str(coach_turn.get("scenario") or scenario)
                agent_meta["scenario"] = scenario
            else:
                if guided_training_local_reply is not None:
                    assistant_content, updated_coach_turn, agent_meta = apply_guided_training_visible_fallback(
                        coach_turn=coach_turn_mapping(coach_turn),
                        fallback=guided_training_local_reply,
                    )
                    coach_turn = extract_coach_turn_payload(updated_coach_turn)
                elif use_agent_loop and not guided_training_prefers_local_reply:
                    agent_context = dict(coach_turn["coach_context"])
                    agent_context["__runtime__"] = runtime
                    agent_context["workspace_id"] = workspace_id
                    agent_context["session_id"] = state.session_id
                    _stamp_library_sandbox_work(agent_context, request, payload)
                    agent_outcome = await coaching_service.coaching_reply_agentic(
                        profile,
                        request.message,
                        request.current_file.model_dump() if request.current_file else None,
                        response_language=request.response_language,
                        answer_mode=request.answer_mode,
                        coach_context=agent_context,
                        attachments=attachments_payload,
                        protocol=getattr(coaching_service._config, "protocol", None) if coaching_service._config else None,
                        history=build_conversation_history(
                            state.snapshot.messages,
                            drop_latest_user=True,
                        ),
                    )
                    assistant_content = str(agent_outcome.get("content") or "").strip()
                    agent_resume_thread = str(agent_outcome.get("resume_thread") or "").strip()
                    if not agent_resume_thread:
                        agent_resume_thread = build_resume_thread_text(
                            str(agent_outcome.get("summary") or "").strip(),
                            str(agent_outcome.get("next_step") or "").strip(),
                            response_language=request.response_language,
                        )
                    agent_meta = {
                        "stop_reason": agent_outcome.get("stop_reason"),
                        "summary": agent_outcome.get("summary"),
                        "next_step": agent_outcome.get("next_step"),
                        "decision": agent_outcome.get("decision"),
                        "blocker": agent_outcome.get("blocker"),
                        "teaching_note": agent_outcome.get("teaching_note"),
                        "resume_thread": agent_resume_thread,
                        "confidence": agent_outcome.get("confidence"),
                        "evidence": agent_outcome.get("evidence"),
                        "steps": agent_outcome.get("steps", []),
                        "tool_events": agent_outcome.get("tool_events", []),
                        "fell_back": bool(agent_outcome.get("fell_back")),
                        "recovered_stop_reason": agent_outcome.get("recovered_stop_reason"),
                        "agentic": True,
                    }
                    apply_attachment_delivery_metadata(agent_meta, agent_outcome)
                    original_agent_stop_reason = str(agent_outcome.get("stop_reason") or "").strip()
                    local_sequence_fallback = build_local_sequence_visible_fallback(
                        coach_context=dict(coach_turn["coach_context"]),
                        response_language=request.response_language,
                    )
                    force_local_sequence = bool(
                        local_sequence_fallback is not None
                        and (
                            original_agent_stop_reason == "empty_response"
                            or not reply_explicitly_lists_prepared_sequence(
                                assistant_content,
                                coach_context=dict(coach_turn["coach_context"]),
                            )
                        )
                    )
                    if force_local_sequence and local_sequence_fallback is not None:
                        assistant_content = local_sequence_fallback["reply"]
                        coaching_service.clear_last_reply_override()
                        agent_meta["summary"] = (
                            agent_meta.get("summary") or local_sequence_fallback["summary"]
                        )
                        agent_meta["next_step"] = (
                            agent_meta.get("next_step") or local_sequence_fallback["next_step"]
                        )
                        agent_meta["teaching_note"] = (
                            agent_meta.get("teaching_note") or local_sequence_fallback["teaching_note"]
                        )
                        if not str(agent_meta.get("resume_thread") or "").strip():
                            agent_meta["resume_thread"] = local_sequence_fallback["resume_thread"]
                        if original_agent_stop_reason == "empty_response":
                            agent_meta["fell_back"] = True
                            agent_meta["recovered_stop_reason"] = original_agent_stop_reason
                            agent_meta["stop_reason"] = "completed"
                        else:
                            agent_meta["grounded_sequence_enforced"] = True
                        agent_meta["local_sequence_fallback"] = True
                    elif not assistant_content:
                        if local_sequence_fallback is None:
                            assistant_content = await coaching_service.coaching_reply(
                                profile,
                                request.message,
                                request.current_file.model_dump() if request.current_file else None,
                                response_language=request.response_language,
                                answer_mode=request.answer_mode,
                                coach_context=dict(coach_turn["coach_context"]),
                                history=build_conversation_history(
                                    state.snapshot.messages,
                                    drop_latest_user=True,
                                ),
                            )
                        else:
                            assistant_content = local_sequence_fallback["reply"]
                            coaching_service.clear_last_reply_override()
                            agent_meta["summary"] = (
                                agent_meta.get("summary") or local_sequence_fallback["summary"]
                            )
                            agent_meta["next_step"] = (
                                agent_meta.get("next_step") or local_sequence_fallback["next_step"]
                            )
                            agent_meta["teaching_note"] = (
                                agent_meta.get("teaching_note") or local_sequence_fallback["teaching_note"]
                            )
                            if not str(agent_meta.get("resume_thread") or "").strip():
                                agent_meta["resume_thread"] = local_sequence_fallback["resume_thread"]
                        agent_meta["fell_back"] = True
                        if original_agent_stop_reason == "empty_response":
                            agent_meta["recovered_stop_reason"] = original_agent_stop_reason
                            agent_meta["stop_reason"] = "completed"
                        agent_meta["local_sequence_fallback"] = local_sequence_fallback is not None
                    updated_coach_turn = merge_agent_finalize_into_coach_turn(
                        coach_turn_mapping(coach_turn),
                        summary=agent_outcome.get("summary")
                        or (local_sequence_fallback or {}).get("summary"),
                        next_step=agent_outcome.get("next_step")
                        or (local_sequence_fallback or {}).get("next_step"),
                        blocker=agent_outcome.get("blocker"),
                        resume_thread=agent_resume_thread
                        or (local_sequence_fallback or {}).get("resume_thread"),
                        decision=agent_outcome.get("decision"),
                        teaching_note=agent_outcome.get("teaching_note")
                        or (local_sequence_fallback or {}).get("teaching_note"),
                        confidence=agent_outcome.get("confidence"),
                        evidence=agent_outcome.get("evidence"),
                    )
                    coach_turn = extract_coach_turn_payload(updated_coach_turn)
                else:
                    assistant_content = await coaching_service.coaching_reply(
                        profile,
                        request.message,
                        request.current_file.model_dump() if request.current_file else None,
                        response_language=request.response_language,
                        answer_mode=request.answer_mode,
                        coach_context=dict(coach_turn["coach_context"]),
                        history=build_conversation_history(
                            state.snapshot.messages,
                            drop_latest_user=True,
                        ),
                    )
                provider_empty_reply_override = consume_provider_empty_reply_override(
                    coaching_service=coaching_service,
                    snapshot=state.snapshot,
                    coach_turn=coach_turn_mapping(coach_turn),
                    response_language=request.response_language,
                    assistant_content=assistant_content,
                )
                if provider_empty_reply_override is not None:
                    provider_failure_detected = True
                    assistant_content, updated_coach_turn, override_meta = provider_empty_reply_override
                    coach_turn = extract_coach_turn_payload(updated_coach_turn)
                    agent_meta.update(override_meta)
                else:
                    provider_failure_override = consume_provider_reply_failure_override(
                        coaching_service=coaching_service,
                        snapshot=state.snapshot,
                        coach_turn=coach_turn_mapping(coach_turn),
                        message=request.message,
                        response_language=request.response_language,
                        workspace_id=state.workspace_id,
                    )
                    if provider_failure_override is not None:
                        provider_failure_detected = True
                        assistant_content, updated_coach_turn, override_meta = provider_failure_override
                        coach_turn = extract_coach_turn_payload(updated_coach_turn)
                        agent_meta.update(override_meta)
                    elif not language_corruption_detected and coaching_service.detect_language_corruption(
                        message=request.message,
                        reply=assistant_content,
                        response_language=request.response_language,
                    ):
                        language_corruption_detected = True
                        assistant_content, updated_coach_turn, override_meta = apply_language_corruption_override(
                            coaching_service=coaching_service,
                            snapshot=state.snapshot,
                            coach_turn=coach_turn_mapping(coach_turn),
                            message=request.message,
                            response_language=request.response_language,
                            reply_corruption=True,
                        )
                        coach_turn = extract_coach_turn_payload(updated_coach_turn)
                        ensure_explicit_training_card_after_language_block(
                            state=state,
                            message=request.message,
                            current_file=request.current_file,
                            response_language=request.response_language,
                            fallback_scenario=str(coach_turn.get("scenario") or scenario),
                            force_training_card=(
                                auto_preference_requests_training_card(
                                    request.message,
                                    requested_scenario=str(coach_turn.get("scenario") or scenario),
                                    requested_answer_mode=raw_requested_answer_mode,
                                    saved_answer_mode=saved_answer_mode,
                                    profile=profile,
                                )
                                or auto_lane_learn_first_force_training_card(
                                    request.message,
                                    requested_scenario=str(coach_turn.get("scenario") or scenario),
                                    requested_answer_mode=raw_requested_answer_mode,
                                    saved_answer_mode=saved_answer_mode,
                                    profile=profile,
                                )
                            ),
                            provider_service_override=coaching_service,
                        )
                        scenario = str(coach_turn.get("scenario") or scenario)
                        agent_meta.update(override_meta)
                if not provider_failure_detected:
                    resource_contract_fallback = None
                    if grounded_resource_contract_needs_repair(
                        assistant_content,
                        coach_context=dict(coach_turn["coach_context"]),
                    ):
                        resource_contract_fallback = build_grounded_resource_contract_visible_fallback(
                            workspace_id=workspace_id,
                            coach_context=dict(coach_turn["coach_context"]),
                            agent_meta=agent_meta,
                            response_language=request.response_language,
                        )
                    if resource_contract_fallback is not None:
                        assistant_content = resource_contract_fallback["reply"]
                        agent_meta["summary"] = resource_contract_fallback["summary"]
                        agent_meta["next_step"] = resource_contract_fallback["next_step"]
                        agent_meta["teaching_note"] = resource_contract_fallback["teaching_note"]
                        agent_meta["resume_thread"] = resource_contract_fallback["resume_thread"]
                        agent_meta["grounded_resource_contract_repaired"] = True
                        agent_meta["scenario"] = str(coach_turn.get("scenario") or scenario)
                        updated_coach_turn = merge_agent_finalize_into_coach_turn(
                            coach_turn_mapping(coach_turn),
                            summary=resource_contract_fallback["summary"],
                            next_step=resource_contract_fallback["next_step"],
                            blocker=agent_meta.get("blocker"),
                            resume_thread=resource_contract_fallback["resume_thread"],
                            decision=agent_meta.get("decision"),
                            teaching_note=resource_contract_fallback["teaching_note"],
                            confidence=agent_meta.get("confidence"),
                            evidence=agent_meta.get("evidence"),
                        )
                        coach_turn = extract_coach_turn_payload(updated_coach_turn)
                    assistant_content, updated_coach_turn, agent_meta, _guided_lane_repaired = (
                        apply_guided_lane_visible_fallback(
                            reply=assistant_content,
                            scenario=str(coach_turn.get("scenario") or scenario),
                            learner_message=request.message,
                            response_language=request.response_language,
                            coach_turn=coach_turn_mapping(coach_turn),
                            agent_meta=agent_meta,
                        )
                    )
                    coach_turn = extract_coach_turn_payload(updated_coach_turn)
                    ensure_explicit_training_card_after_coach_reply(
                        state=state,
                        message=request.message,
                        current_file=request.current_file,
                        response_language=request.response_language,
                        fallback_scenario=str(coach_turn.get("scenario") or scenario),
                        force_training_card=auto_preference_requests_training_card(
                            request.message,
                            requested_scenario=str(coach_turn.get("scenario") or scenario),
                            requested_answer_mode=raw_requested_answer_mode,
                            saved_answer_mode=saved_answer_mode,
                            profile=profile,
                        )
                        or auto_lane_learn_first_force_training_card(
                            request.message,
                            requested_scenario=str(coach_turn.get("scenario") or scenario),
                            requested_answer_mode=raw_requested_answer_mode,
                            saved_answer_mode=saved_answer_mode,
                            profile=profile,
                        ),
                        provider_service_override=coaching_service,
                    )
        elif request.intent == "coach":
            # Remapped task/next_task (no live plan) still uses task honesty copy so
            # the learner hears "did not invent a task" rather than bare coach failure.
            raw_intent = str(payload.get("intent") or "").strip()
            unusable_kind: Literal["task", "plan", "coach"] = (
                "task" if raw_intent in {"task", "next_task"} else "coach"
            )
            if scenario == "general":
                scenario = infer_message_coaching_scenario(
                    request.message,
                    normalize_current_file_payload(getattr(request, "current_file", None)),
                    default="general",
                )
                if message_requests_project_sourcing(request.message):
                    scenario = "project_sourcing"
            coach_turn = honest_unusable_provider_coach_turn(
                response_language=request.response_language,
                snapshot=state.snapshot,
                coaching_service=coaching_service,
                object_kind=unusable_kind,
                scenario=scenario,
            )
            scenario = str(coach_turn["scenario"] or scenario)
            artifacts = {}
            suggested_actions = list(coach_turn["suggested_actions"])
            assistant_content = str(coach_turn["coach_turn"].summary)
            agent_meta = {
                "summary": coach_turn["coach_turn"].summary,
                "next_step": coach_turn["coach_turn"].next_step,
            }
        elif request.intent == "next_task":
            if not provider_live_usable:
                coach_turn = honest_unusable_provider_coach_turn(
                    response_language=request.response_language,
                    snapshot=state.snapshot,
                    coaching_service=coaching_service,
                    object_kind="task",
                )
                scenario = "general"
                artifacts = {}
                suggested_actions = list(coach_turn["suggested_actions"])
                assistant_content = str(coach_turn["coach_turn"].summary)
                agent_meta = {
                    "summary": coach_turn["coach_turn"].summary,
                    "next_step": coach_turn["coach_turn"].next_step,
                }
            else:
                task = review_aware_next_task(
                    workspace_id=workspace_id,
                    profile=profile,
                    focus_area=request.focus_area,
                    response_language=request.response_language,
                )
                task = clean_active_thread_task(
                    task,
                    request.response_language,
                    runtime.memory_service.snapshot(state.workspace_id).active_thread,
                    plan=state.snapshot.plan,
                    snapshot=state.snapshot,
                )
                state.snapshot.current_task = task
                state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
                state.snapshot.profile = profile
                coach_turn = resolve_coach_turn(
                    state=state,
                    profile=profile,
                    request=request,
                    message=request.message,
                    coaching_service=coaching_service,
                    current_task=task,
                    current_plan=state.snapshot.plan,
                    current_evaluation=state.snapshot.evaluation,
                    force_scenario="next_task",
                )
                scenario = "next_task"
                learner_signal = str(coach_turn["learner_signal"])
                artifacts = dict(coach_turn["artifacts"])
                suggested_actions = list(coach_turn["suggested_actions"])
                leftover_runtime = coach_focus_runtime_from_snapshot(state.snapshot)
                picked = live_task_picked_copy(
                    plan=state.snapshot.plan,
                    task=task,
                    runtime=leftover_runtime,
                    existing=leftover_runtime,
                    task_title=task.title,
                )
                assistant_content = localized_text(picked["en"], picked["zh"], request.response_language)
        elif request.intent == "task":
            if not provider_live_usable:
                coach_turn = honest_unusable_provider_coach_turn(
                    response_language=request.response_language,
                    snapshot=state.snapshot,
                    coaching_service=coaching_service,
                    object_kind="task",
                )
                scenario = "general"
                artifacts = {}
                suggested_actions = list(coach_turn["suggested_actions"])
                assistant_content = str(coach_turn["coach_turn"].summary)
                agent_meta = {
                    "summary": coach_turn["coach_turn"].summary,
                    "next_step": coach_turn["coach_turn"].next_step,
                }
            else:
                task = runtime.spec_service.specify(
                    TaskSpecifyRequest(
                        session_id=request.session_id,
                        workspace_id=workspace_id,
                        natural_language_goal=request.message,
                    )
                )
                state.snapshot.current_task = task
                state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
                state.snapshot.profile = profile
                coach_turn = resolve_coach_turn(
                    state=state,
                    profile=profile,
                    request=request,
                    message=request.message,
                    coaching_service=coaching_service,
                    current_task=task,
                    current_plan=state.snapshot.plan,
                    current_evaluation=state.snapshot.evaluation,
                    force_scenario="task",
                )
                scenario = "task"
                learner_signal = str(coach_turn["learner_signal"])
                artifacts = dict(coach_turn["artifacts"])
                suggested_actions = list(coach_turn["suggested_actions"])
                leftover_runtime = coach_focus_runtime_from_snapshot(state.snapshot)
                converted = live_task_converted_copy(
                    plan=state.snapshot.plan,
                    task=task,
                    runtime=leftover_runtime,
                    existing=leftover_runtime,
                    task_title=task.title,
                )
                assistant_content = localized_text(converted["en"], converted["zh"], request.response_language)
        elif request.intent == "plan":
            # Formal plans are committed by the model through save_formal_plan.
            # Leftover stored plans stay stored. Do not paint them live without
            # recovered runtime identity, and do not synthesize a replacement.
            leftover_plan, leftover_runtime = leftover_runtime_for_workspace(workspace_id)
            plan = (
                leftover_plan
                if leftover_formal_plan_is_live_for_fill(
                    plan=leftover_plan,
                    runtime=leftover_runtime,
                    existing=leftover_runtime,
                )
                else None
            )
            runtime.memory_service.record_profile(workspace_id, profile)
            state.snapshot.plan = plan
            state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
            state.snapshot.profile = profile
            if not provider_live_usable:
                coach_turn = honest_unusable_provider_coach_turn(
                    response_language=request.response_language,
                    snapshot=state.snapshot,
                    coaching_service=coaching_service,
                    object_kind="plan",
                    scenario="plan",
                )
                scenario = "plan"
                artifacts = {}
                suggested_actions = list(coach_turn["suggested_actions"])
                assistant_content = str(coach_turn["coach_turn"].summary)
                agent_meta = {
                    "summary": coach_turn["coach_turn"].summary,
                    "next_step": coach_turn["coach_turn"].next_step,
                }
            else:
                coach_turn = resolve_coach_turn(
                    state=state,
                    profile=profile,
                    request=request,
                    message=request.message,
                    coaching_service=coaching_service,
                    current_task=state.snapshot.current_task,
                    current_plan=plan,
                    current_evaluation=state.snapshot.evaluation,
                    force_scenario="plan",
                )
                stage_count = len(plan.phases) if plan is not None else 0
                scenario = "plan"
                learner_signal = str(coach_turn["learner_signal"])
                artifacts = dict(coach_turn["artifacts"])
                suggested_actions = list(coach_turn["suggested_actions"])
                assistant_content = (
                    ""
                    if request.formal_plan_mutation
                    else localized_text(
                        (
                            f"I refreshed your learning plan with {stage_count} stages. "
                            "Anchor on the current stage first, then convert it into a small set of actions you can actually finish."
                        ),
                        f"\u6211\u5df2\u7ecf\u66f4\u65b0\u4e86\u4f60\u7684\u5b66\u4e60\u8ba1\u5212\uff0c\u5171 {stage_count} \u4e2a\u9636\u6bb5\u3002"
                        "\u5148\u56f4\u7ed5\u5f53\u524d\u9636\u6bb5\u63a8\u8fdb\uff0c\u518d\u628a\u5b83\u62c6\u6210\u4f60\u73b0\u5728\u80fd\u5b8c\u6210\u7684\u5c0f\u52a8\u4f5c\u3002",
                        request.response_language,
                    )
                )
        elif request.intent == "review":
            if request.current_file is None:
                raise HTTPException(status_code=400, detail="Current file is required for review turns.")
            leftover = leftover_plan_state_fields(workspace_id)
            leftover_runtime = leftover.get("leftover_runtime")
            report = stamp_produced_workspace_record(
                runtime.evaluator_service.evaluate_current_file(
                    EvaluateCurrentFileRequest(
                        session_id=request.session_id,
                        workspace_id=workspace_id,
                        task_spec_id=state.snapshot.current_task.id if state.snapshot.current_task else None,
                        file_path=request.current_file.path,
                        language_id=request.current_file.language_id,
                        content=request.current_file.content,
                    ),
                    state.snapshot.current_task,
                    leftover_plan=leftover.get("leftover_plan"),
                    leftover_runtime=leftover_runtime if isinstance(leftover_runtime, dict) else {},
                    leftover_task_title=str(leftover.get("leftover_task_title") or ""),
                ),
                workspace_id,
            )
            state.snapshot.evaluation = report
            persist_evaluation_learning_loop(
                workspace_id=workspace_id,
                state=state,
                report=report,
                action_type="review",
                fallback_focus_area=(
                    Path(str(request.current_file.path or "")).stem.strip() or "review"
                ),
            )
            advance_plan_after_evaluation(
                workspace_id=workspace_id,
                state=state,
                report=report,
            )
            state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
            state.snapshot.profile = profile
            coach_turn = resolve_coach_turn(
                state=state,
                profile=profile,
                request=request,
                message=request.message,
                coaching_service=coaching_service,
                current_task=state.snapshot.current_task,
                current_plan=state.snapshot.plan,
                current_evaluation=report,
                force_scenario="review",
            )
            scenario = "review"
            learner_signal = str(coach_turn["learner_signal"])
            artifacts = dict(coach_turn["artifacts"])
            suggested_actions = list(coach_turn["suggested_actions"])
            assistant_content = localized_text(
                f"Review finished. {report.summary} Highest-leverage next step: {report.next_step}",
                f"\u8bc4\u5ba1\u5b8c\u6210\u3002{report.summary} \u5f53\u524d\u6700\u503c\u5f97\u5148\u505a\u7684\u4e0b\u4e00\u6b65\uff1a{report.next_step}",
                request.response_language,
            )
        else:
            raise HTTPException(status_code=400, detail="Unsupported turn intent.")

        final_resource_context = compose_resource_context(
            state.workspace_id,
            request_resource_ids(request),
            message=request.message,
            resource_composer_intent=request.resource_composer_intent,
        )
        runtime.memory_service.record_session_message(
            state.session_id,
            f"user: {request.message}",
            workspace_id=state.workspace_id,
        )
        request_coach_context = coach_turn.get("coach_context")
        if isinstance(request_coach_context, dict):
            request_coach_context = dict(request_coach_context)
            if final_resource_context:
                for key, value in final_resource_context.items():
                    request_coach_context.setdefault(key, value)
        else:
            request_coach_context = build_coach_context(
                state.snapshot,
                final_resource_context,
                message=request.message,
                active_view=request.active_view,
                current_file=request.current_file,
                response_language=request.response_language,
                plan_runtime_recovery=getattr(request, "plan_runtime_recovery", None),
            )
        if request.intent == "plan" and not stream and provider_live_usable:
            history = build_conversation_history(
                state.snapshot.messages,
                drop_latest_user=True,
            )
            if use_agent_loop:
                agent_context = dict(request_coach_context or {})
                agent_context["__runtime__"] = runtime
                agent_context["workspace_id"] = workspace_id
                agent_context["session_id"] = state.session_id
                _stamp_library_sandbox_work(agent_context, request, payload)
                agent_outcome = await coaching_service.coaching_reply_agentic(
                    profile,
                    request.message,
                    request.current_file.model_dump() if request.current_file else None,
                    response_language=request.response_language,
                    answer_mode=request.answer_mode,
                    coach_context=agent_context,
                    attachments=attachments_payload,
                    protocol=(
                        getattr(coaching_service._config, "protocol", None)
                        if coaching_service._config
                        else None
                    ),
                    history=history,
                )
                assistant_content = str(agent_outcome.get("content") or "").strip()
                agent_resume_thread = str(agent_outcome.get("resume_thread") or "").strip()
                if not agent_resume_thread:
                    agent_resume_thread = build_resume_thread_text(
                        str(agent_outcome.get("summary") or "").strip(),
                        str(agent_outcome.get("next_step") or "").strip(),
                        response_language=request.response_language,
                    )
                agent_meta = {
                    "stop_reason": agent_outcome.get("stop_reason"),
                    "summary": agent_outcome.get("summary"),
                    "next_step": agent_outcome.get("next_step"),
                    "decision": agent_outcome.get("decision"),
                    "blocker": agent_outcome.get("blocker"),
                    "teaching_note": agent_outcome.get("teaching_note"),
                    "resume_thread": agent_resume_thread,
                    "confidence": agent_outcome.get("confidence"),
                    "evidence": agent_outcome.get("evidence"),
                    "steps": agent_outcome.get("steps", []),
                    "tool_events": agent_outcome.get("tool_events", []),
                    "fell_back": bool(agent_outcome.get("fell_back")),
                    "recovered_stop_reason": agent_outcome.get("recovered_stop_reason"),
                    "agentic": True,
                }
                apply_attachment_delivery_metadata(agent_meta, agent_outcome)
                if request.formal_plan_mutation:
                    persisted_plan = runtime.repository.get_latest_plan(workspace_id)
                    _leftover_after, leftover_runtime_after = leftover_runtime_for_workspace(
                        workspace_id
                    )
                    if persisted_plan is not None and leftover_formal_plan_is_live_for_fill(
                        plan=persisted_plan,
                        runtime=leftover_runtime_after,
                        existing=leftover_runtime_after,
                    ):
                        state.snapshot.plan = persisted_plan
            else:
                # When the Agent loop is disabled, keep the legacy provider
                # reply path. It still cannot synthesize or persist a formal
                # plan because this branch is discussion-only.
                assistant_content = await coaching_service.coaching_reply(
                    profile,
                    request.message,
                    request.current_file.model_dump() if request.current_file else None,
                    response_language=request.response_language,
                    answer_mode=request.answer_mode,
                    coach_context=request_coach_context,
                    history=history,
                )
        if should_attach_auto_resource_events(agent_meta):
            agent_meta = apply_auto_resource_agent_evidence(
                agent_meta,
                auto_resource_lookup_tool_events(
                    request_coach_context if isinstance(request_coach_context, dict) else None,
                    request.message,
                ),
            )
        if not use_agent_loop and agent_meta:
            agent_meta["agentic"] = False
        request_turn_summary = coach_turn.get("coach_turn")
        coach_turn_payload = {
            "scenario": scenario,
            "learner_signal": learner_signal,
            "coach_context": request_coach_context,
            "coach_turn": (
                request_turn_summary
                if isinstance(request_turn_summary, CoachTurnSummary)
                else build_turn_summary(
                    snapshot=state.snapshot,
                    scenario=scenario,
                    learner_signal=learner_signal,
                    artifacts=artifacts,
                    suggested_actions=suggested_actions,
                    coach_context=request_coach_context,
                    response_language=request.response_language,
                )
            ),
        }
        if isinstance(agent_meta, dict):
            coach_turn_payload = merge_agent_finalize_into_coach_turn(
                coach_turn_payload,
                summary=agent_meta.get("summary"),
                next_step=agent_meta.get("next_step"),
                blocker=agent_meta.get("blocker"),
                resume_thread=agent_meta.get("resume_thread") or agent_meta.get("resumeThread"),
                decision=agent_meta.get("decision"),
                teaching_note=agent_meta.get("teaching_note") or agent_meta.get("teachingNote"),
                confidence=agent_meta.get("confidence"),
                evidence=agent_meta.get("evidence"),
            )
            stop_reason = str(agent_meta.get("stop_reason") or "").strip()
            preserve_active_thread = should_preserve_active_thread_for_turn(
                scenario,
                state.snapshot.memory.active_thread,
                message=request.message,
                grounding_context=request_coach_context if isinstance(request_coach_context, dict) else None,
                active_view=request.active_view,
            )
            if (
                not preserve_active_thread
                and stop_reason in PROVIDER_REPLY_STOP_REASONS
                and isinstance(coach_turn_payload, dict)
            ):
                coach_context = coach_turn_payload.get("coach_context")
                turn_summary = coach_turn_payload.get("coach_turn")
                if isinstance(coach_context, dict) and isinstance(turn_summary, CoachTurnSummary):
                    focus_hint = extract_focus_hint_from_message(request.message) or ""
                    visible_focus_hint = guided_focus_display_value(
                        focus_hint,
                        scenario=scenario,
                        response_language=request.response_language,
                    )
                    if visible_focus_hint:
                        coach_context["current_focus"] = visible_focus_hint
                    coach_context["active_thread"] = {
                        "scenario": scenario,
                        "focus_area": visible_focus_hint or focus_hint,
                        "summary": turn_summary.summary,
                        "next_step": turn_summary.next_step,
                        "blocker": turn_summary.blocker,
                        "decision": turn_summary.decision,
                        "teaching_note": turn_summary.teaching_note,
                        "confidence": turn_summary.confidence,
                        "evidence": list(turn_summary.evidence or []),
                    }
        response_snapshot = state.snapshot.model_copy(deep=True)
        persist_turn_reflection(
            workspace_id=workspace_id,
            session_id=state.session_id,
            user_message=request.message,
            scenario=scenario,
            response_language=request.response_language,
            answer_mode=answer_mode_preference_for_persistence(
                raw_requested_answer_mode,
                saved_answer_mode,
                request.answer_mode,
                profile.answer_policy,
            ),
            coach_defaults=request.coach_defaults,
            coach_turn_data=coach_turn_payload,
            stop_reason=str(agent_meta.get("stop_reason") or ""),
            recovered_stop_reason=str(agent_meta.get("recovered_stop_reason") or ""),
            local_sequence_fallback=bool(agent_meta.get("local_sequence_fallback")),
        )
        persist_recovered_plan_resume_after_turn(
            workspace_id=workspace_id,
            request=request,
            reply_content=assistant_content,
            agent_meta=agent_meta if isinstance(agent_meta, dict) else None,
            coach_context=request_coach_context if isinstance(request_coach_context, dict) else None,
            recovered_status=state.snapshot.plan_runtime_status
            if isinstance(state.snapshot.plan_runtime_status, dict)
            else None,
        )
        if not language_corruption_detected and not provider_failure_detected:
            persist_external_references_as_background(
                workspace_id=workspace_id,
                scenario=scenario,
                coach_turn_data=coach_turn_payload,
            )
        if not provider_live_usable:
            suggested_actions = honest_suggested_actions_without_usable_provider(
                suggested_actions,
                response_language=request.response_language,
                snapshot=state.snapshot,
                current_task=state.snapshot.current_task,
                current_plan=state.snapshot.plan,
                current_evaluation=state.snapshot.evaluation,
            )
        if agent_meta:
            # Stamp reliability only onto a real agent meta. Stamping an empty
            # dict would resurrect agent_meta for clean non-agent turns and the
            # AgentMeta default (agentic=True) would mislabel the reply lane.
            agent_meta["reliability"] = operation_reliability_record(
                phase="acked",
                outcome=(
                    "failure"
                    if not provider_live_usable or provider_failure_detected
                    else "success"
                ),
                request_id=str(request.request_id or "").strip() or None,
            )
        state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
        state.snapshot.profile = runtime.repository.get_profile(workspace_id) or profile
        hydrate_snapshot(
            state.snapshot,
            response_language=request.response_language,
            answer_mode=request.answer_mode or profile.answer_policy,
            scenario=scenario,
            learner_signal=learner_signal,
            message=request.message,
            current_file=request.current_file,
            active_view=request.active_view,
            session_workspace_id=workspace_id,
        )
        if frozen_formal_plan_mutation_requested:
            assistant_content = "\n\n".join(
                part
                for part in (frozen_plan_mutation_notice(request.response_language), assistant_content)
                if part
            )
            agent_meta["formal_plan_mutation_blocked"] = True
        if not (scenario == "idea_implementation" and request.current_file is not None):
            response_snapshot = state.snapshot

        if stream and request.intent != "coach":
            return (
                {
                    "__turn_stream_preparation__": True,
                    "state": state,
                    "request": request,
                    "profile": profile,
                    "scenario": scenario,
                    "learner_signal": learner_signal,
                    "coach_turn_data": coach_turn_payload,
                    "artifacts": artifacts,
                    "suggested_actions": suggested_actions,
                    "agent_meta": agent_meta,
                    "response_snapshot": response_snapshot,
                    "attachment_delivery": attachment_delivery,
                    "fallback_reply": assistant_content,
                    "use_agent_loop": use_agent_loop,
                },
                artifacts,
                coaching_service,
            )

        return (
            build_session_response(
                state=state,
                request=request,
                reply_content=assistant_content,
                artifacts=artifacts,
                suggested_actions=suggested_actions,
                scenario=scenario,
                learner_signal=learner_signal,
                coach_turn_data=coach_turn_payload,
                response_snapshot=response_snapshot,
                agent_meta=agent_meta or None,
                attachment_delivery=attachment_delivery,
            ),
            artifacts,
            coaching_service,
        )

    @router.get("/health")
    def health(request: Request) -> dict[str, object]:
        database_path = str(runtime.repository.database_path)
        provider_config = runtime.provider_service._config  # noqa: SLF001
        provider_name = provider_config.name if provider_config else None
        provider_model = provider_config.model if provider_config else None
        provider_base_url = provider_config.base_url if provider_config else None
        return {
            "status": "ok",
            "initialized": True,
            "database_path": database_path,
            "provider": {
                "configured": provider_config is not None,
                "name": provider_name,
                "model": provider_model,
                "base_url": provider_base_url,
                "has_api_key": runtime.provider_service.has_api_key,
            },
            "research": {
                "provider_attached": True,
            },
            "resource_fetch": {
                "network_enabled": bool(getattr(runtime.resource_service, "enable_network_fetch", False)),
            },
        }

    def workspace_discovery_owner_id(payload: dict) -> str:
        workspace_id = str(payload.get("workspace_id") or "").strip()
        session_id = str(payload.get("session_id") or "").strip()
        # Discovery ownership is an ephemeral client key.  Resolving an old
        # workspace alias here would change the key immediately after adoption
        # and make a repeated decision look like a different discovery owner.
        if workspace_id:
            return workspace_id
        if session_id:
            return current_workspace_id(session_id=session_id)
        return ""

    def normalize_trainer_root_path(value: str) -> str:
        raw_path = str(value or "").strip()
        if not raw_path:
            raise ProjectProvisioningConflictError("A Trainer workspace root is required.")
        try:
            normalized = Path(raw_path).expanduser().resolve(strict=False)
        except (OSError, RuntimeError) as exc:
            raise ProjectProvisioningConflictError(
                "The selected Trainer workspace root cannot be normalized."
            ) from exc
        if not normalized.is_dir():
            raise ProjectProvisioningConflictError(
                "The selected Trainer workspace root must be an available directory."
            )
        return str(normalized)

    def workspace_admission_conflict(
        code: str,
        category: str,
        path_state: str,
        detail: str,
    ) -> HTTPException:
        return HTTPException(
            status_code=409,
            detail={
                "code": code,
                "category": category,
                "path_state": path_state,
                "message": detail,
            },
        )

    def trainer_root_selection_from_payload(
        payload: dict,
        workspace_id: str,
    ) -> TrainerRootSelection:
        """Resolve the data root without treating the project path as that root."""
        requested_root_id = str(payload.get("root_id") or payload.get("rootId") or "").strip() or None
        requested_root_path = str(payload.get("root_path") or payload.get("rootPath") or "").strip() or None
        if requested_root_id:
            stored_root = runtime.repository.get_trainer_root(requested_root_id)
            if stored_root is None:
                raise ProjectProvisioningConflictError("The selected Trainer workspace root is unavailable.")
            if requested_root_path:
                try:
                    normalized_requested_path = str(Path(requested_root_path).expanduser().resolve(strict=False))
                except (OSError, RuntimeError) as exc:
                    raise ProjectProvisioningConflictError(
                        "The selected Trainer workspace root cannot be normalized."
                    ) from exc
                if normalized_requested_path != str(Path(stored_root.root_path).resolve(strict=False)):
                    raise ProjectProvisioningConflictError(
                        "The selected Trainer workspace root ID does not match its path."
                    )
            return TrainerRootSelection(
                root_id=stored_root.root_id,
                root_path=normalize_trainer_root_path(stored_root.root_path),
            )
        if requested_root_path:
            normalized_path = normalize_trainer_root_path(requested_root_path)
            stored_root = runtime.repository.get_trainer_root_by_path(normalized_path)
            return TrainerRootSelection(
                root_id=stored_root.root_id if stored_root is not None else None,
                root_path=normalized_path,
            )

        # Compatibility for direct API users that configured a root before the
        # discovery request. This is never used as a project-path fallback by
        # provisioning itself, so a project cannot silently become its own root.
        legacy_root_path = runtime.resolve_workspace_path(workspace_id)
        if legacy_root_path:
            normalized_path = normalize_trainer_root_path(legacy_root_path)
            stored_root = runtime.repository.get_trainer_root_by_path(normalized_path)
            return TrainerRootSelection(
                root_id=stored_root.root_id if stored_root is not None else None,
                root_path=normalized_path,
            )
        return TrainerRootSelection(root_id=None, root_path=None)

    def project_discovery_authority(
        project_path: str,
        root_selection: TrainerRootSelection,
    ) -> WorkspaceAuthority | None:
        """Authorize reads from the selected project, not from Trainer's data root."""
        if not root_selection.root_path:
            return None
        try:
            return WorkspaceAuthority(
                root_path=project_path,
                initial_permission=PermissionLevel.INSPECT,
            )
        except (OSError, ValueError):
            return None

    def root_selections_match(left: TrainerRootSelection, right: TrainerRootSelection) -> bool:
        return left.root_id == right.root_id and left.root_path == right.root_path

    def project_adoption_job_response(
        job: ProjectAdoptionJobRecord,
        discovery: ProjectDiscovery | None = None,
    ) -> dict[str, object]:
        payload = {"project_adoption_job": job.to_payload()}
        result = job.result
        if isinstance(result, dict):
            payload.update(result)
        elif discovery is not None:
            payload["project_discovery"] = discovery.to_payload()
        return payload

    @router.post("/workspace/classify", response_model=None)
    async def workspace_classify(payload: dict) -> dict[str, object]:
        workspace_id = workspace_discovery_owner_id(payload)
        requested_response_language = (
            str(payload.get("response_language") or payload.get("responseLanguage") or "").strip() or None
        )
        response_language = effective_response_language(workspace_id, requested_response_language)
        folder_path = str(
            payload.get("folder_path")
            or payload.get("project_path")
            or payload.get("workspace_path")
            or ""
        ).strip()
        if not folder_path and workspace_id:
            folder_path = runtime.resolve_workspace_path(workspace_id) or ""
        if not folder_path:
            raise HTTPException(status_code=400, detail="folder_path is required.")

        try:
            root_selection = trainer_root_selection_from_payload(payload, workspace_id)
        except ProjectProvisioningConflictError as exc:
            detail = str(exc)
            if "ID does not match" in detail:
                raise workspace_admission_conflict(
                    "root_id_mismatch", "workspace_root", "unknown", "The selected Trainer workspace root ID does not match its path."
                ) from exc
            if "unavailable" in detail or "available directory" in detail:
                raise workspace_admission_conflict(
                    "root_path_unavailable", "workspace_root", "unavailable", "The selected Trainer workspace root is unavailable."
                ) from exc
            raise workspace_admission_conflict(
                "root_missing", "workspace_root", "missing", "A Trainer workspace root is required."
            ) from exc

        # Register the explicitly selected Trainer data root before observing a
        # project. This does not adopt the project and never grants authority to
        # the candidate path; it only makes the root registry canonical.
        if root_selection.root_path:
            try:
                registered_root = runtime.register_trainer_root(
                    root_id=root_selection.root_id,
                    root_path=root_selection.root_path,
                )
            except (KeyError, ValueError) as exc:
                raise HTTPException(status_code=409, detail=str(exc)) from exc
            root_selection = TrainerRootSelection(
                root_id=registered_root.root_id,
                root_path=registered_root.root_path,
            )
        snapshot = payload.get("workspace_file_snapshot") or payload.get("workspaceFileSnapshot")
        if not isinstance(snapshot, dict):
            snapshot = None
        remote_name = str(
            payload.get("remote_name") or payload.get("remoteName") or ""
        ).strip() or None
        summary = classify_heuristic(
            folder_path,
            response_language=response_language,
            workspace_file_snapshot=snapshot,
            remote_name=remote_name,
        )
        classification_service = runtime.provider_service
        override_config = provider_config_from_payload(payload)
        api_key_override = provider_api_key_from_payload(payload)
        if override_config is not None or api_key_override is not None:
            # Do not retain request-scoped credentials in the runtime service cache.
            classification_service = ProviderService(config=override_config, api_key=api_key_override)
        if (
            classification_service.has_api_key
            and runtime.provider_connection_verified(classification_service)
        ):
            summary = await classify_with_llm(
                folder_path,
                classification_service,
                heuristic_result=summary,
                response_language=response_language,
            )
        discovery = discover_project(
            folder_path,
            summary=summary,
            # Classification only observes the candidate. The project-specific
            # authority is created at the explicit decision boundary below.
            authority=None,
            remote_workspace=bool(
                remote_name
                or (isinstance(snapshot, dict) and snapshot.get("is_remote") is True)
                or "://" in folder_path
            ),
        )
        with project_discoveries_guard:
            project_discoveries[discovery.discovery_id] = (workspace_id, discovery, root_selection)

        response = summary.model_dump(mode="json")
        response["project_discovery"] = discovery.to_payload()
        if root_selection.root_path:
            response["root_identity"] = {
                "rootId": root_selection.root_id,
                "rootPath": root_selection.root_path,
            }
        return cast(dict[str, object], response)

    @router.post("/workspace/discovery/decision", response_model=None)
    def workspace_discovery_decision(payload: dict) -> dict[str, object]:
        workspace_id = workspace_discovery_owner_id(payload)
        context_id = str(payload.get("context_id") or payload.get("contextId") or "").strip() or None
        discovery_id = str(payload.get("discovery_id") or "").strip()
        decision = str(payload.get("decision") or "").strip().lower()
        if not discovery_id:
            raise HTTPException(status_code=400, detail="discovery_id is required.")
        if decision not in {"adopt", "browse", "ignore"}:
            raise HTTPException(status_code=422, detail="decision must be adopt, browse, or ignore.")

        with project_discoveries_guard:
            stored = project_discoveries.get(discovery_id)
        if stored is None or stored[0] != workspace_id:
            # Do not reveal a discovery record's path or ownership context.
            raise HTTPException(status_code=404, detail="Project discovery was not found.")

        _, discovery, stored_root_selection = stored
        has_explicit_root_selection = bool(
            str(payload.get("root_id") or payload.get("rootId") or "").strip()
            or str(payload.get("root_path") or payload.get("rootPath") or "").strip()
        )
        if has_explicit_root_selection:
            try:
                requested_root_selection = trainer_root_selection_from_payload(payload, workspace_id)
            except ProjectProvisioningConflictError as exc:
                raise HTTPException(status_code=409, detail=str(exc)) from exc
            if not root_selections_match(stored_root_selection, requested_root_selection):
                raise HTTPException(
                    status_code=409,
                    detail="The selected Trainer workspace root changed after project discovery.",
                )
        root_selection = stored_root_selection
        if decision == "adopt" and discovery.status == "adopted":
            try:
                provisioning = runtime.get_project_provisioning(workspace_id)
            except ProjectProvisioningIntegrityError as exc:
                logger.error("Stored project provisioning evidence is incomplete: %s", type(exc).__name__)
                raise HTTPException(
                    status_code=409,
                    detail="The managed project needs repair before it can be resumed.",
                ) from exc
            if provisioning is None or provisioning.project_path != discovery.project_path:
                raise HTTPException(
                    status_code=409,
                    detail="The managed project record is unavailable for this discovery.",
                )
            persist_first_look_summary(provisioning.workspace_id, discovery.summary)
            return {
                "project_discovery": discovery.to_payload(),
                "project_provisioning": provisioning.model_dump(mode="json"),
                "project_identity": runtime.project_identity_payload(
                    provisioning,
                    idempotency="reused",
                ),
            }
        if decision == "adopt" and discovery.status == "adoption_requested" and discovery.adoption_job_id:
            if not root_selection.root_path:
                raise HTTPException(
                    status_code=409,
                    detail="The selected Trainer workspace root changed after project discovery.",
                )
            job = runtime.get_project_adoption_job(
                root_path=root_selection.root_path,
                job_id=discovery.adoption_job_id,
            )
            if job is None:
                raise HTTPException(
                    status_code=409,
                    detail="The project adoption job is no longer available and must be retried.",
                )
            return project_adoption_job_response(job, discovery)

        authority = project_discovery_authority(discovery.project_path, root_selection)
        try:
            resolved = resolve_project_discovery(
                discovery,
                decision,
                authority=authority,
            )
        except PermissionError as exc:
            logger.info("Workspace project discovery decision denied: %s", type(exc).__name__)
            raise HTTPException(
                status_code=403,
                detail="Choose a Trainer workspace root before opening this project.",
            ) from exc
        except ValueError as exc:
            message = str(exc).strip() or "The project discovery cannot be resolved in its current state."
            logger.info("Workspace project discovery decision could not be resolved: %s", type(exc).__name__)
            raise HTTPException(status_code=409, detail=message) from exc

        if decision != "adopt":
            with project_discoveries_guard:
                project_discoveries[discovery_id] = (workspace_id, resolved, root_selection)
            return {"project_discovery": resolved.to_payload()}

        if root_selection.root_path and Path(root_selection.root_path).resolve(strict=False) == Path(
            resolved.project_path
        ).resolve(strict=False):
            raise HTTPException(
                status_code=409,
                detail="This workspace is already associated with a different managed project.",
            )

        job_id = f"project-adoption-{uuid4().hex[:12]}"
        job_id_box: dict[str, str] = {"job_id": job_id}

        def finalize_adoption(inventory: dict[str, object]) -> dict[str, object]:
            existing = runtime.get_project_provisioning(context_id or workspace_id)
            provisioning = runtime.provision_project_adoption(
                workspace_id=workspace_id,
                context_id=context_id,
                root_id=root_selection.root_id,
                root_path=root_selection.root_path,
                project_path=resolved.project_path,
                project_name=resolved.project_name,
            )
            adopted = complete_project_adoption(
                replace(resolved, adoption_job_id=job_id_box.get("job_id")),
                provisioning.adoption_artifacts(),
            )
            persist_first_look_summary(provisioning.workspace_id, adopted.summary)
            with project_discoveries_guard:
                project_discoveries[discovery_id] = (workspace_id, adopted, root_selection)
            return {
                "project_discovery": adopted.to_payload(),
                "project_provisioning": provisioning.model_dump(mode="json"),
                "project_identity": runtime.project_identity_payload(
                    provisioning,
                    idempotency=(
                        "reused"
                        if existing is not None and existing.project_path == provisioning.project_path
                        else "created"
                    ),
                ),
                "project_adoption_inventory": inventory,
            }

        try:
            job = runtime.start_project_adoption_job(
                workspace_id=workspace_id,
                discovery_id=discovery_id,
                job_id=job_id,
                project_path=resolved.project_path,
                project_name=resolved.project_name,
                root_id=root_selection.root_id,
                root_path=root_selection.root_path or "",
                context_id=context_id,
                finalize=finalize_adoption,
            )
            requested = replace(resolved, adoption_job_id=job.job_id)
            with project_discoveries_guard:
                project_discoveries[discovery_id] = (workspace_id, requested, root_selection)
        except ProjectProvisioningConflictError as exc:
            logger.info("Workspace project provisioning conflict: %s", type(exc).__name__)
            raise HTTPException(
                status_code=409,
                detail="This workspace is already associated with a different managed project.",
            ) from exc
        except ProjectProvisioningIntegrityError as exc:
            logger.error("Workspace project provisioning integrity failure: %s", type(exc).__name__)
            raise HTTPException(
                status_code=409,
                detail="Project provisioning could not establish a complete recoverable project lane.",
            ) from exc

        return {
            "project_discovery": requested.to_payload(),
            "project_adoption_job": job.to_payload(),
        }

    @router.get("/workspace/adoption-job", response_model=None)
    def workspace_adoption_job(
        job_id: str | None = None,
        root_path: str | None = None,
        workspace_id: str | None = None,
    ) -> dict[str, object]:
        if not job_id:
            raise HTTPException(status_code=400, detail="job_id is required.")
        if not root_path:
            raise HTTPException(status_code=400, detail="root_path is required.")
        job = runtime.get_project_adoption_job(root_path=root_path, job_id=job_id)
        if job is None:
            raise HTTPException(status_code=404, detail="Project adoption job was not found.")
        if workspace_id is not None and str(workspace_id).strip() and job.workspace_id != workspace_id.strip():
            raise HTTPException(status_code=404, detail="Project adoption job was not found.")
        response = project_adoption_job_response(job)
        if job.status == "completed" and job.context_id:
            try:
                provisioning = runtime.get_project_provisioning(job.context_id)
            except ProjectProvisioningIntegrityError as exc:
                logger.error("Project adoption job recovered incomplete provisioning: %s", type(exc).__name__)
                raise HTTPException(
                    status_code=409,
                    detail="The managed project needs repair before it can be resumed.",
                ) from exc
            if provisioning is not None:
                response.setdefault("project_provisioning", provisioning.model_dump(mode="json"))
                response.setdefault(
                    "project_identity",
                    runtime.project_identity_payload(provisioning, idempotency="existing"),
                )
        return response

    @router.get("/workspace/project-provisioning", response_model=None)
    def workspace_project_provisioning(
        workspace_id: str | None = None,
        context_id: str | None = None,
        session_id: str | None = None,
    ) -> dict[str, object]:
        if not (workspace_id or context_id or session_id):
            raise HTTPException(status_code=400, detail="workspace_id, context_id, or session_id is required.")
        resolved_workspace_id = current_workspace_id(
            session_id=session_id,
            workspace_id=context_id or workspace_id,
        )
        try:
            provisioning = runtime.get_project_provisioning(resolved_workspace_id)
        except ProjectProvisioningIntegrityError as exc:
            logger.error("Project provisioning lookup found incomplete evidence: %s", type(exc).__name__)
            raise HTTPException(
                status_code=409,
                detail="The managed project needs repair before it can be resumed.",
            ) from exc
        if provisioning is None:
            raise HTTPException(status_code=404, detail="No managed project was found for this workspace.")
        return {
            "project_provisioning": provisioning.model_dump(mode="json"),
            "project_identity": runtime.project_identity_payload(provisioning, idempotency="existing"),
        }

    @router.get("/workspace/identity", response_model=None)
    def workspace_identity(
        workspace_id: str | None = None,
        context_id: str | None = None,
        session_id: str | None = None,
    ) -> dict[str, object]:
        if not (workspace_id or context_id or session_id):
            raise HTTPException(status_code=400, detail="workspace_id, context_id, or session_id is required.")
        resolved_workspace_id = current_workspace_id(
            session_id=session_id,
            workspace_id=context_id or workspace_id,
        )
        try:
            provisioning = runtime.get_project_provisioning(resolved_workspace_id)
        except ProjectProvisioningIntegrityError as exc:
            raise HTTPException(
                status_code=409,
                detail="The managed project needs repair before it can be resumed.",
            ) from exc
        if provisioning is None:
            raise HTTPException(status_code=404, detail="No managed project identity was found.")
        return runtime.project_identity_payload(provisioning, idempotency="existing")

    @router.post("/workspace/roots/{root_id}/reconcile", response_model=None)
    def workspace_root_reconcile(root_id: str, payload: dict) -> dict[str, object]:
        root_path = str(payload.get("root_path") or payload.get("rootPath") or "").strip()
        if not root_path:
            raise HTTPException(status_code=400, detail="root_path is required.")
        try:
            root = runtime.reconcile_trainer_root(root_id, root_path)
        except KeyError as exc:
            raise HTTPException(status_code=404, detail="Trainer root was not found.") from exc
        except ValueError as exc:
            raise HTTPException(status_code=409, detail="Trainer root cannot be reconciled.") from exc
        pending_project_ids: list[str] = []
        for project in runtime.repository.list_trainer_projects(root.root_id):
            try:
                Path(project.project_path).relative_to(Path(root.root_path))
            except ValueError:
                pending_project_ids.append(project.project_id)
        pending = bool(pending_project_ids)
        return {
            "root": root.model_dump(mode="json"),
            "root_identity": {
                "rootId": root.root_id,
                "rootPath": root.root_path,
                "revisions": {"root": root.revision},
                "pending": pending,
                "reconcile": {
                    "state": "pending_projects" if pending else "reconciled",
                    "pendingProjectIds": pending_project_ids,
                },
            },
        }

    @router.post("/workspace/projects/{project_id}/reconcile", response_model=None)
    def workspace_project_reconcile(project_id: str, payload: dict) -> dict[str, object]:
        root_id = str(payload.get("root_id") or payload.get("rootId") or "").strip()
        project_path = str(payload.get("project_path") or payload.get("projectPath") or "").strip()
        project_name = str(payload.get("project_name") or payload.get("projectName") or "").strip() or None
        if not root_id or not project_path:
            raise HTTPException(status_code=400, detail="root_id and project_path are required.")
        try:
            project = runtime.reconcile_project_location(
                root_id=root_id,
                project_id=project_id,
                project_path=project_path,
                project_name=project_name,
            )
        except KeyError as exc:
            raise HTTPException(status_code=404, detail="Trainer root or project was not found.") from exc
        except ValueError as exc:
            raise HTTPException(status_code=409, detail="Project location cannot be reconciled.") from exc
        context = runtime.repository.get_project_context_for_project(project.project_id)
        if context is None:
            raise HTTPException(status_code=409, detail="Project context is incomplete.")
        try:
            provisioning = runtime.get_project_provisioning(context.context_id)
        except ProjectProvisioningIntegrityError as exc:
            raise HTTPException(
                status_code=409,
                detail="The managed project needs repair before it can be resumed.",
            ) from exc
        if provisioning is None:
            raise HTTPException(status_code=409, detail="Project context cannot be loaded.")
        return {
            "project": project.model_dump(mode="json"),
            "project_identity": runtime.project_identity_payload(
                provisioning,
                idempotency="reconciled",
                reconcile_state="reconciled",
            ),
        }

    def force_new_session_requested(payload: dict) -> bool:
        """Treat only an explicit truthy flag as a request to discard the active thread."""
        value = payload.get("force_new")
        if value is None:
            value = payload.get("forceNew")
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return value == 1
        if isinstance(value, str):
            return value.strip().lower() in {"1", "true", "yes", "on"}
        return False

    def project_provisioning_repair_detail(response_language: str | None) -> dict[str, object]:
        return {
            "state": "repair_required",
            "status": "blocked",
            "recoverable": True,
            "detail": localized_text(
                "The managed project needs repair before it can be resumed.",
                "这个托管项目需要先修复，才能恢复会话。",
                response_language,
            ),
            "next_step": localized_text(
                "Restore the missing structured memory, then re-run /session/start.",
                "先恢复缺失的 structured_memory，然后重新调用 /session/start。",
                response_language,
            ),
        }

    def validate_project_provisioning_or_repair(workspace_id: str, response_language: str | None) -> object | None:
        try:
            return runtime.get_project_provisioning(workspace_id)
        except ProjectProvisioningIntegrityError as exc:
            raise HTTPException(
                status_code=409,
                detail=project_provisioning_repair_detail(response_language),
            ) from exc

    @router.post("/session/start", response_model=None)
    def session_start(payload: dict) -> object:
        requested_response_language = (
            str(payload.get("response_language") or payload.get("responseLanguage") or "").strip() or None
        )
        if "user_profile" in payload:
            workspace_context = payload.get("workspace_context", {})
            workspace_id = current_workspace_id(
                workspace_id=str(workspace_context.get("workspace_id") or "workspace-default")
            )
            workspace_name = workspace_context.get("name", "Trainer")
            workspace_path = workspace_context.get("root_path") or workspace_context.get("workspace_path")
            remote_name = str(
                workspace_context.get("remote_name")
                or workspace_context.get("remoteName")
                or payload.get("remote_name")
                or payload.get("remoteName")
                or ""
            ).strip()
            project_provisioning = validate_project_provisioning_or_repair(workspace_id, requested_response_language)
            profile_payload = payload.get("user_profile", {})
            profile = UserProfile(
                long_term_goals=profile_payload.get("long_term_goals", []),
                weekly_hours=profile_payload.get("weekly_hours", 4),
                teaching_style=profile_payload.get("teaching_style", "auto"),
                answer_policy="direct" if profile_payload.get("allow_direct_answers") else "auto",
                preferred_libraries=profile_payload.get("focus_libraries", []),
            )
            runtime.memory_service.record_profile(workspace_id, profile)
            if workspace_path is None and project_provisioning is not None:
                workspace_path = project_provisioning.project_path
            runtime.register_workspace_path(workspace_id, workspace_path)
            runtime.memory_service.update_workspace_state(
                workspace_id,
                remote_name=remote_name,
                is_remote_workspace=bool(remote_name),
                workspace_trusted=bool(
                    workspace_context.get("workspace_trusted")
                    if "workspace_trusted" in workspace_context
                    else workspace_context.get("trusted")
                    if "trusted" in workspace_context
                    else payload.get("workspace_trusted", payload.get("trusted", False))
                ),
            )
            persist_requested_response_language(workspace_id, requested_response_language)
            start_response_language = effective_response_language(
                workspace_id,
                requested_response_language,
                str(payload.get("initial_message") or "").strip() or None,
            )
            state = runtime.start_session(workspace_id, workspace_name)
            if workspace_path:
                maybe_persist_first_look_from_path(
                    workspace_id,
                    str(workspace_path),
                    response_language=start_response_language,
                    workspace_file_snapshot=_workspace_snapshot_from_payload(payload),
                    remote_name=str(remote_name or "").strip() or None,
                )
            should_seed_learning_project_prompt = workspace_learning_project_prompt_needed(workspace_id)
            if should_seed_learning_project_prompt:
                runtime.memory_service.update_workspace_state(
                    workspace_id,
                    learning_project_prompt_status="pending",
                    learning_project_source_path=str(workspace_path or ""),
                )
            user_message = ChatMessage(
                id=f"message-{uuid4().hex[:10]}",
                role="user",
                content=payload.get("initial_message", "Let's begin."),
                timestamp=datetime.now(UTC),
            )
            assistant_message = ChatMessage(
                id=f"message-{uuid4().hex[:10]}",
                role="assistant",
                content=(
                    "We have a starting profile. Next, we should lock the target outcome, "
                    "decide the answer policy, and pick the first narrow exercise."
                ),
                timestamp=datetime.now(UTC),
            )
            seeded_messages = [user_message, assistant_message]
            if should_seed_learning_project_prompt:
                seeded_messages.append(
                    ChatMessage(
                        id=f"message-{uuid4().hex[:10]}",
                        role="assistant",
                        content=workspace_learning_project_prompt_text(
                            workspace_path=str(workspace_path or ""),
                            response_language=start_response_language,
                        ),
                        timestamp=datetime.now(UTC),
                    )
                )
            state.snapshot.messages.extend(seeded_messages)
            return {
                "session_id": state.session_id,
                "stage": "intake",
                "summary": f"Learning session for {workspace_name}; goals: {', '.join(profile.long_term_goals)}.",
                "messages": [message.model_dump() for message in seeded_messages],
            }

        try:
            request = SessionStartRequest.model_validate(payload)
        except ValidationError as exc:
            raise HTTPException(
                status_code=422,
                detail=exc.errors(include_context=False),
            ) from exc
        workspace_id = current_workspace_id(workspace_id=request.workspace_id)
        project_provisioning = validate_project_provisioning_or_repair(workspace_id, requested_response_language)
        workspace_path = request.workspace_path
        if request.root_path:
            normalized_root_path = normalize_trainer_root_path(request.root_path)
            root = runtime.repository.get_trainer_root(request.root_id) if request.root_id else None
            if root is None:
                root = runtime.repository.get_trainer_root_by_path(normalized_root_path)
            if root is None or root.root_path != normalized_root_path:
                raise HTTPException(status_code=409, detail="The selected Trainer workspace root is not registered.")
            if project_provisioning is not None and project_provisioning.root_id != root.root_id:
                raise HTTPException(status_code=409, detail="The session project does not belong to the selected Trainer root.")
        if workspace_path is None and project_provisioning is not None:
            workspace_path = project_provisioning.project_path
        if request.profile:
            runtime.memory_service.record_profile(workspace_id, request.profile)
        if workspace_path is not None:
            runtime.register_workspace_path(workspace_id, workspace_path)
        if "remote_name" in payload or "remoteName" in payload:
            remote_name = str(request.remote_name or "").strip()
            trusted_patch: dict[str, object] = {
                "remote_name": remote_name,
                "is_remote_workspace": bool(remote_name),
            }
            if "workspace_trusted" in payload or "trusted" in payload or "workspaceTrusted" in payload:
                trusted_patch["workspace_trusted"] = bool(
                    payload.get(
                        "workspace_trusted",
                        payload.get("workspaceTrusted", payload.get("trusted", False)),
                    )
                )
            runtime.memory_service.update_workspace_state(workspace_id, **trusted_patch)
        elif "workspace_trusted" in payload or "trusted" in payload or "workspaceTrusted" in payload:
            runtime.memory_service.update_workspace_state(
                workspace_id,
                workspace_trusted=bool(
                    payload.get(
                        "workspace_trusted",
                        payload.get("workspaceTrusted", payload.get("trusted", False)),
                    )
                ),
            )
        persist_requested_response_language(workspace_id, requested_response_language)
        start_response_language = effective_response_language(
            workspace_id,
            requested_response_language,
            None,
        )

        # VS Code calls this route during rehydration without a session id. Keep that
        # ordinary path attached to the latest thread; starting over is explicit.
        initial_message = str(payload.get("initial_message") or "").strip()
        can_resume = (
            request.profile is None
            and not initial_message
            and not force_new_session_requested(payload)
        )
        if can_resume:
            restored = runtime.restore_latest_session_for_workspace(workspace_id)
            if restored is not None:
                restored.workspace_name = request.workspace_name
                restored.snapshot.context_id = workspace_id
                restored.snapshot.profile = runtime.repository.get_profile(workspace_id)
                restored.snapshot.memory = runtime.memory_service.snapshot(workspace_id)
                runtime.hydrate_plan_context(restored.snapshot, workspace_id)
                hydrate_snapshot(
                    restored.snapshot,
                    response_language=None,
                    answer_mode=(
                        restored.snapshot.profile.answer_policy
                        if restored.snapshot.profile
                        else None
                    ),
                )
                runtime.save_session_state(restored.session_id)
                snapshot_payload = restored.snapshot.model_dump(by_alias=True)
                snapshot_payload["session_id"] = restored.session_id
                return snapshot_payload

        state = runtime.start_session(workspace_id, request.workspace_name)
        if workspace_path:
            maybe_persist_first_look_from_path(
                workspace_id,
                workspace_path,
                response_language=start_response_language,
                workspace_file_snapshot=_workspace_snapshot_from_payload(payload),
                remote_name=str(request.remote_name or "").strip() or None,
            )
        if workspace_learning_project_prompt_needed(workspace_id):
            runtime.memory_service.update_workspace_state(
                workspace_id,
                learning_project_prompt_status="pending",
                learning_project_source_path=str(workspace_path or ""),
            )
            state.snapshot.messages.append(
                ChatMessage(
                    id=f"message-{uuid4().hex[:10]}",
                    role="assistant",
                    content=workspace_learning_project_prompt_text(
                        workspace_path=str(workspace_path or ""),
                        response_language=start_response_language,
                    ),
                    timestamp=datetime.now(UTC),
                )
            )
        state.snapshot.profile = runtime.repository.get_profile(workspace_id)
        state.snapshot.memory = runtime.memory_service.snapshot(workspace_id)
        hydrate_snapshot(
            state.snapshot,
            response_language=None,
            answer_mode=state.snapshot.profile.answer_policy if state.snapshot.profile else None,
        )
        runtime.save_session_state(state.session_id)
        snapshot_payload = state.snapshot.model_dump(by_alias=True)
        snapshot_payload["session_id"] = state.session_id
        return snapshot_payload

    @router.post("/session/message", response_model=None)
    async def session_message(payload: dict) -> object:
        request = SessionMessageRequest.model_validate(payload)
        workspace_id = current_workspace_id(session_id=request.session_id, workspace_id=request.workspace_id)
        # Mid-session host re-attest so trust flips apply before authority/capability.
        apply_host_workspace_trust_attestation(workspace_id, payload)
        request_id = str(request.request_id or "").strip()
        request_key = (workspace_id, str(request.session_id or "").strip(), request_id)
        owner_future: asyncio.Future | None = None

        def _overlay_completed_session_response(cached_response: dict[str, object]) -> dict[str, object]:
            # Fail-closed: never serve a completed/shared snapshot missing current
            # honesty stamps added by a later hydrate (leftover recovered / mint blocks).
            state = runtime.ensure_session(request.session_id, workspace_id=workspace_id)
            snapshot = state.snapshot
            pressure_blocks = pressure_without_live_object_blocks_mint(
                workspace_id,
                snapshot=snapshot,
                current_task=snapshot.current_task,
                current_plan=snapshot.plan,
                message=request.message,
            )
            streak_blocks = streak_without_live_object_blocks_mint(
                workspace_id,
                snapshot=snapshot,
                current_task=snapshot.current_task,
                current_plan=snapshot.plan,
            )
            live_status = (
                snapshot.plan_runtime_status
                if isinstance(snapshot.plan_runtime_status, dict)
                else {}
            )
            leftover_plan, leftover_runtime = leftover_runtime_for_workspace(workspace_id)
            leftover_runtime = leftover_runtime if isinstance(leftover_runtime, dict) else {}
            live_for_attach = bool(leftover_runtime) and leftover_formal_plan_is_live_for_fill(
                plan=snapshot.plan or leftover_plan,
                runtime=leftover_runtime,
                existing=leftover_runtime,
            )
            recovered_leftover = False
            if not live_for_attach:
                if leftover_plan is not None:
                    recovered_leftover = True
                elif live_status.get("recovered") is True and snapshot.plan is None:
                    recovered_leftover = True
            stamped = overlay_session_response_honesty_stamps(
                cached_response,
                pressure_blocks=pressure_blocks,
                streak_blocks=streak_blocks,
                recovered_leftover=recovered_leftover,
            )
            if stamped is not cached_response:
                with completed_session_requests_guard:
                    completed_session_requests[request_key] = stamped
            return stamped

        def _finish_session_response(payload: dict[str, object]) -> dict[str, object]:
            stamped = _attach_requested_workspace_files(payload, runtime, workspace_id)
            if not request_id:
                return stamped
            return publish_session_request_singleflight(
                request_key,
                stamped,
                completed=completed_session_requests,
                inflight=inflight_session_requests,
                guard=completed_session_requests_guard,
            )

        def _owner_task_cleanup(task: asyncio.Task) -> None:
            if owner_future is None or owner_future.done():
                return
            with completed_session_requests_guard:
                inflight_session_requests.pop(request_key, None)
                cached = completed_session_requests.get(request_key)
            if cached is not None:
                owner_future.set_result(cached)
                return
            if task.cancelled():
                owner_future.set_exception(asyncio.CancelledError())
                return
            try:
                exc = task.exception()
            except asyncio.CancelledError as cancelled:
                owner_future.set_exception(cancelled)
                return
            if exc is not None:
                owner_future.set_exception(exc)
                return
            owner_future.set_exception(
                RuntimeError("session request completed without publishing a payload")
            )

        if request_id:
            kind, cached_response, shared_future = claim_session_request_singleflight(
                request_key,
                completed=completed_session_requests,
                inflight=inflight_session_requests,
                guard=completed_session_requests_guard,
            )
            if kind == "wait":
                assert shared_future is not None
                shared_payload = await shared_future
                return _overlay_completed_session_response(shared_payload)
            if kind == "cached":
                assert cached_response is not None
                return _overlay_completed_session_response(cached_response)
            owner_future = shared_future
            current_task = asyncio.current_task()
            if current_task is not None:
                current_task.add_done_callback(_owner_task_cleanup)
        state = runtime.ensure_session(request.session_id, workspace_id=workspace_id)
        profile = resolved_profile(state.workspace_id)
        raw_requested_answer_mode = str(
            payload.get("answer_mode") or payload.get("answerMode") or ""
        ).strip()
        saved_answer_mode = str(workspace_preferences(workspace_id).get("answer_mode") or "").strip()
        request = request_with_workspace_defaults(
            request,
            workspace_id=workspace_id,
            profile=profile,
        )
        profile = profile_with_teaching_style(profile, request.teaching_style)

        # Per-request provider config override
        coaching_service = runtime.provider_service
        override_config = provider_config_from_payload(payload)
        api_key_override = provider_api_key_from_payload(payload)
        if override_config is not None or api_key_override is not None:
            coaching_service = runtime.provider_service_for(override_config, api_key_override)
        ensure_coach_provider_ready(
            coaching_service,
            response_language=request.response_language,
        )
        provider_live_usable = provider_is_live_usable(coaching_service, payload)
        if not provider_live_usable:
            turn_request = turn_request_from_stream_payload(payload, intent="coach")
            response, artifacts, _ = await execute_turn(turn_request, payload, stream=False)
            response_payload = json_object_payload(response)
            if artifacts:
                response_payload["artifacts"] = artifacts
            return _finish_session_response(
                attach_operation_reliability(
                    response_payload,
                    phase="acked",
                    outcome="failure",
                    request_id=str(request.request_id or "").strip() or None,
                )
            )
        ensure_agent_tools_ready(request, coaching_service)
        use_agent_loop = _resolve_agent_loop_enabled(request, coaching_service, payload=payload)
        attachments_payload = [a.model_dump() for a in request.attachments]
        attachment_delivery = describe_request_attachment_delivery(
            request,
            coaching_service,
            use_agent_loop=use_agent_loop,
        )

        user_message = ChatMessage(
            id=f"message-{uuid4().hex[:10]}",
            role="user",
            content=request.message,
            timestamp=datetime.now(UTC),
            metadata=build_user_message_metadata(request, profile, attachment_delivery),
        )
        state.snapshot.messages.append(user_message)
        state.snapshot.profile = profile
        runtime.memory_service.record_session_message(
            state.session_id,
            f"user: {request.message}",
            workspace_id=state.workspace_id,
        )
        safe_activate_training_card_from_coach_request(
            workspace_id=state.workspace_id,
            snapshot=state.snapshot,
            message=request.message,
            current_file=request.current_file,
            response_language=request.response_language,
            provider_service_override=coaching_service,
        )
        state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
        learning_project_state = workspace_learning_project_state(state.workspace_id)
        if learning_project_state.get("prompt_status") == "pending":
            handled_reply: str | None = None
            if message_confirms_learning_project_folder(request.message):
                _linked_root, handled_reply = adopt_workspace_learning_project_folder(
                    workspace_id=state.workspace_id,
                    workspace_name=state.workspace_name,
                    response_language=request.response_language,
                )
            elif message_rejects_learning_project_folder(request.message):
                runtime.memory_service.update_workspace_state(
                    state.workspace_id,
                    learning_project_prompt_status="dismissed",
                )
                handled_reply = localized_text(
                    "Okay. Trainer will keep the current sandbox arrangement for now and will not create a learning project folder yet.",
                    "好。Trainer 先保留当前的 sandbox 方式，暂时不创建学习项目文件夹。",
                    request.response_language,
                )
            if handled_reply:
                state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
                state.snapshot.profile = profile
                hydrate_snapshot(
                    state.snapshot,
                    response_language=request.response_language,
                    answer_mode=request.answer_mode or (profile.answer_policy if profile else None),
                    scenario="general",
                    learner_signal="steady",
                    message=request.message,
                    active_view=request.active_view,
                )
                response = build_session_response(
                    state=state,
                    request=request,
                    reply_content=handled_reply,
                    artifacts={},
                    suggested_actions=[],
                    scenario="general",
                    learner_signal="steady",
                    coach_turn_data=None,
                    agent_meta=None,
                    attachment_delivery=attachment_delivery,
                )
                runtime.save_session_state(state.session_id)
                return _finish_session_response(to_json_payload(response))
        coach_turn: CoachTurnPayload = resolve_coach_turn(
            state=state,
            profile=profile,
            request=request,
            message=request.message,
            coaching_service=coaching_service,
            current_task=state.snapshot.current_task,
            current_plan=state.snapshot.plan,
            current_evaluation=state.snapshot.evaluation,
        )
        scenario = str(coach_turn.get("scenario") or "general")
        if guarantee_guided_learn_first_training_card(
            workspace_id=state.workspace_id,
            scenario=str(coach_turn["scenario"] or ""),
            message=request.message,
            current_file=request.current_file,
            response_language=request.response_language,
            active_thread=state.snapshot.memory.active_thread,
            requested_answer_mode=raw_requested_answer_mode,
            saved_answer_mode=saved_answer_mode,
            profile=profile,
        ):
            state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
        auto_resource_events = auto_resource_lookup_tool_events(
            dict(coach_turn["coach_context"]),
            request.message,
        )
        guided_training_prefers_local_reply = should_bypass_agent_loop_for_guided_training(
            workspace_id=state.workspace_id,
            scenario=str(coach_turn["scenario"] or scenario),
            message=request.message,
            active_view=request.active_view,
            requested_answer_mode=raw_requested_answer_mode,
            saved_answer_mode=saved_answer_mode,
            profile=profile,
        )
        guided_training_local_reply = (
            build_guided_training_visible_fallback(
                workspace_id=state.workspace_id,
                response_language=request.response_language,
            )
            if guided_training_prefers_local_reply
            else None
        )

        agent_meta: dict[str, object] = {}
        language_corruption_detected = False
        provider_failure_detected = False
        preflight_language_probe = detect_provider_language_corruption(
            coaching_service,
            message=request.message,
            response_language=request.response_language,
            coach_context=dict(coach_turn["coach_context"]),
        )
        if preflight_language_probe is not None:
            language_corruption_detected = True
            coach_turn = extract_coach_turn_payload(
                isolate_preflight_language_corruption_turn(
                    coach_turn_mapping(coach_turn),
                    message=request.message,
                    current_file=request.current_file.model_dump() if request.current_file else None,
                )
            )
            assistant_content, updated_coach_turn, agent_meta = apply_language_corruption_override(
                coaching_service=coaching_service,
                snapshot=state.snapshot,
                coach_turn=coach_turn_mapping(coach_turn),
                message=request.message,
                response_language=request.response_language,
                allow_guided_recovery=False,
            )
            coach_turn = extract_coach_turn_payload(updated_coach_turn)
            ensure_explicit_training_card_after_language_block(
                state=state,
                message=request.message,
                current_file=request.current_file,
                response_language=request.response_language,
                fallback_scenario=str(coach_turn.get("scenario") or scenario),
                force_training_card=(
                    auto_preference_requests_training_card(
                        request.message,
                        requested_scenario=str(coach_turn.get("scenario") or scenario),
                        requested_answer_mode=raw_requested_answer_mode,
                        saved_answer_mode=saved_answer_mode,
                        profile=profile,
                    )
                    or auto_lane_learn_first_force_training_card(
                        request.message,
                        requested_scenario=str(coach_turn.get("scenario") or scenario),
                        requested_answer_mode=raw_requested_answer_mode,
                        saved_answer_mode=saved_answer_mode,
                        profile=profile,
                    )
                ),
                provider_service_override=coaching_service,
            )
            scenario = str(coach_turn.get("scenario") or scenario)
            agent_meta["scenario"] = scenario
        elif guided_training_local_reply is not None:
            assistant_content, updated_coach_turn, agent_meta = apply_guided_training_visible_fallback(
                coach_turn=coach_turn_mapping(coach_turn),
                fallback=guided_training_local_reply,
            )
            coach_turn = extract_coach_turn_payload(updated_coach_turn)
        elif use_agent_loop and not guided_training_prefers_local_reply:
            agent_context = dict(coach_turn["coach_context"])
            agent_context["__runtime__"] = runtime
            agent_context["workspace_id"] = workspace_id
            agent_context["session_id"] = state.session_id
            _stamp_library_sandbox_work(agent_context, request, payload)
            agent_outcome = await coaching_service.coaching_reply_agentic(
                profile,
                request.message,
                request.current_file.model_dump() if request.current_file else None,
                response_language=request.response_language,
                answer_mode=request.answer_mode,
                coach_context=agent_context,
                attachments=attachments_payload,
                protocol=getattr(coaching_service._config, "protocol", None) if coaching_service._config else None,
                history=build_conversation_history(
                    state.snapshot.messages,
                    drop_latest_user=True,
                ),
            )
            assistant_content = str(agent_outcome.get("content") or "").strip()
            agent_resume_thread = str(agent_outcome.get("resume_thread") or "").strip()
            if not agent_resume_thread:
                agent_resume_thread = build_resume_thread_text(
                    str(agent_outcome.get("summary") or "").strip(),
                    str(agent_outcome.get("next_step") or "").strip(),
                    response_language=request.response_language,
                )
            agent_meta = {
                "stop_reason": agent_outcome.get("stop_reason"),
                "summary": agent_outcome.get("summary"),
                "next_step": agent_outcome.get("next_step"),
                "decision": agent_outcome.get("decision"),
                "blocker": agent_outcome.get("blocker"),
                "teaching_note": agent_outcome.get("teaching_note"),
                "resume_thread": agent_resume_thread,
                "confidence": agent_outcome.get("confidence"),
                "evidence": agent_outcome.get("evidence"),
                "steps": agent_outcome.get("steps", []),
                "tool_events": agent_outcome.get("tool_events", []),
                "fell_back": bool(agent_outcome.get("fell_back")),
                "recovered_stop_reason": agent_outcome.get("recovered_stop_reason"),
                "agentic": True,
            }
            apply_attachment_delivery_metadata(agent_meta, agent_outcome)
            original_agent_stop_reason = str(agent_outcome.get("stop_reason") or "").strip()
            local_sequence_fallback: dict[str, str] | None = None
            local_sequence_fallback = build_local_sequence_visible_fallback(
                coach_context=dict(coach_turn["coach_context"]),
                response_language=request.response_language,
            )
            force_local_sequence = bool(
                local_sequence_fallback is not None
                and (
                    str(agent_outcome.get("stop_reason") or "").strip() == "empty_response"
                    or not reply_explicitly_lists_prepared_sequence(
                        assistant_content,
                        coach_context=dict(coach_turn["coach_context"]),
                    )
                )
            )
            if force_local_sequence and local_sequence_fallback is not None:
                assistant_content = local_sequence_fallback["reply"]
                coaching_service.clear_last_reply_override()
                agent_meta["summary"] = agent_meta.get("summary") or local_sequence_fallback["summary"]
                agent_meta["next_step"] = (
                    agent_meta.get("next_step") or local_sequence_fallback["next_step"]
                )
                agent_meta["teaching_note"] = (
                    agent_meta.get("teaching_note") or local_sequence_fallback["teaching_note"]
                )
                if not str(agent_meta.get("resume_thread") or "").strip():
                    agent_meta["resume_thread"] = local_sequence_fallback["resume_thread"]
                if original_agent_stop_reason == "empty_response":
                    agent_meta["fell_back"] = True
                    agent_meta["recovered_stop_reason"] = original_agent_stop_reason
                    agent_meta["stop_reason"] = "completed"
                else:
                    agent_meta["grounded_sequence_enforced"] = True
                agent_meta["local_sequence_fallback"] = True
            elif not assistant_content:
                if local_sequence_fallback is None:
                    assistant_content = await coaching_service.coaching_reply(
                        profile,
                        request.message,
                        request.current_file.model_dump() if request.current_file else None,
                        response_language=request.response_language,
                        answer_mode=request.answer_mode,
                        coach_context=dict(coach_turn["coach_context"]),
                        history=build_conversation_history(
                            state.snapshot.messages,
                            drop_latest_user=True,
                        ),
                    )
                else:
                    assistant_content = local_sequence_fallback["reply"]
                    coaching_service.clear_last_reply_override()
                    agent_meta["summary"] = agent_meta.get("summary") or local_sequence_fallback["summary"]
                    agent_meta["next_step"] = (
                        agent_meta.get("next_step") or local_sequence_fallback["next_step"]
                    )
                    agent_meta["teaching_note"] = (
                        agent_meta.get("teaching_note") or local_sequence_fallback["teaching_note"]
                    )
                    if not str(agent_meta.get("resume_thread") or "").strip():
                        agent_meta["resume_thread"] = local_sequence_fallback["resume_thread"]
                agent_meta["fell_back"] = True
                if original_agent_stop_reason == "empty_response":
                    agent_meta["recovered_stop_reason"] = original_agent_stop_reason
                    agent_meta["stop_reason"] = "completed"
                agent_meta["local_sequence_fallback"] = local_sequence_fallback is not None
            updated_coach_turn = merge_agent_finalize_into_coach_turn(
                coach_turn_mapping(coach_turn),
                summary=agent_outcome.get("summary")
                or (local_sequence_fallback or {}).get("summary"),
                next_step=agent_outcome.get("next_step")
                or (local_sequence_fallback or {}).get("next_step"),
                blocker=agent_outcome.get("blocker"),
                resume_thread=agent_resume_thread
                or (local_sequence_fallback or {}).get("resume_thread"),
                decision=agent_outcome.get("decision"),
                teaching_note=agent_outcome.get("teaching_note")
                or (local_sequence_fallback or {}).get("teaching_note"),
                confidence=agent_outcome.get("confidence"),
                evidence=agent_outcome.get("evidence"),
            )
            coach_turn = extract_coach_turn_payload(updated_coach_turn)
        else:
            assistant_content = await coaching_service.coaching_reply(
                profile,
                request.message,
                request.current_file.model_dump() if request.current_file else None,
                response_language=request.response_language,
                answer_mode=request.answer_mode,
                coach_context=dict(coach_turn["coach_context"]),
                history=build_conversation_history(
                    state.snapshot.messages,
                    drop_latest_user=True,
                ),
            )
        provider_empty_reply_override = consume_provider_empty_reply_override(
            coaching_service=coaching_service,
            snapshot=state.snapshot,
            coach_turn=coach_turn_mapping(coach_turn),
            response_language=request.response_language,
            assistant_content=assistant_content,
        )
        if provider_empty_reply_override is not None:
            provider_failure_detected = True
            assistant_content, updated_coach_turn, override_meta = provider_empty_reply_override
            coach_turn = extract_coach_turn_payload(updated_coach_turn)
            agent_meta.update(override_meta)
        else:
            provider_failure_override = consume_provider_reply_failure_override(
                coaching_service=coaching_service,
                snapshot=state.snapshot,
                coach_turn=coach_turn_mapping(coach_turn),
                message=request.message,
                response_language=request.response_language,
                workspace_id=state.workspace_id,
            )
            if provider_failure_override is not None:
                provider_failure_detected = True
                assistant_content, updated_coach_turn, override_meta = provider_failure_override
                coach_turn = extract_coach_turn_payload(updated_coach_turn)
                agent_meta.update(override_meta)
            elif not language_corruption_detected and coaching_service.detect_language_corruption(
                message=request.message,
                reply=assistant_content,
                response_language=request.response_language,
            ):
                language_corruption_detected = True
                assistant_content, updated_coach_turn, override_meta = apply_language_corruption_override(
                    coaching_service=coaching_service,
                    snapshot=state.snapshot,
                    coach_turn=coach_turn_mapping(coach_turn),
                    message=request.message,
                    response_language=request.response_language,
                    reply_corruption=True,
                )
                coach_turn = extract_coach_turn_payload(updated_coach_turn)
                ensure_explicit_training_card_after_language_block(
                    state=state,
                    message=request.message,
                    current_file=request.current_file,
                    response_language=request.response_language,
                    fallback_scenario=str(coach_turn.get("scenario") or scenario),
                    force_training_card=(
                        auto_preference_requests_training_card(
                            request.message,
                            requested_scenario=str(coach_turn.get("scenario") or scenario),
                            requested_answer_mode=raw_requested_answer_mode,
                            saved_answer_mode=saved_answer_mode,
                            profile=profile,
                        )
                        or auto_lane_learn_first_force_training_card(
                            request.message,
                            requested_scenario=str(coach_turn.get("scenario") or scenario),
                            requested_answer_mode=raw_requested_answer_mode,
                            saved_answer_mode=saved_answer_mode,
                            profile=profile,
                        )
                    ),
                    provider_service_override=coaching_service,
                )
                scenario = str(coach_turn.get("scenario") or scenario)
                agent_meta.update(override_meta)
        if not provider_failure_detected:
            resource_contract_fallback = None
            if grounded_resource_contract_needs_repair(
                assistant_content,
                coach_context=dict(coach_turn["coach_context"]),
            ):
                resource_contract_fallback = build_grounded_resource_contract_visible_fallback(
                    workspace_id=workspace_id,
                    coach_context=dict(coach_turn["coach_context"]),
                    agent_meta=agent_meta,
                    response_language=request.response_language,
                )
            if resource_contract_fallback is not None:
                assistant_content = resource_contract_fallback["reply"]
                agent_meta["summary"] = resource_contract_fallback["summary"]
                agent_meta["next_step"] = resource_contract_fallback["next_step"]
                agent_meta["teaching_note"] = resource_contract_fallback["teaching_note"]
                agent_meta["resume_thread"] = resource_contract_fallback["resume_thread"]
                agent_meta["grounded_resource_contract_repaired"] = True
                agent_meta["scenario"] = str(coach_turn.get("scenario") or scenario)
                updated_coach_turn = merge_agent_finalize_into_coach_turn(
                    coach_turn_mapping(coach_turn),
                    summary=resource_contract_fallback["summary"],
                    next_step=resource_contract_fallback["next_step"],
                    blocker=agent_meta.get("blocker"),
                    resume_thread=resource_contract_fallback["resume_thread"],
                    decision=agent_meta.get("decision"),
                    teaching_note=resource_contract_fallback["teaching_note"],
                    confidence=agent_meta.get("confidence"),
                    evidence=agent_meta.get("evidence"),
                )
                coach_turn = extract_coach_turn_payload(updated_coach_turn)
            assistant_content, updated_coach_turn, agent_meta, _guided_lane_repaired = (
                apply_guided_lane_visible_fallback(
                    reply=assistant_content,
                    scenario=str(coach_turn.get("scenario") or scenario),
                    learner_message=request.message,
                    response_language=request.response_language,
                    coach_turn=coach_turn_mapping(coach_turn),
                    agent_meta=agent_meta,
                )
            )
            coach_turn = extract_coach_turn_payload(updated_coach_turn)
            ensure_explicit_training_card_after_coach_reply(
                state=state,
                message=request.message,
                current_file=request.current_file,
                response_language=request.response_language,
                fallback_scenario=str(coach_turn.get("scenario") or scenario),
                force_training_card=auto_preference_requests_training_card(
                    request.message,
                    requested_scenario=str(coach_turn.get("scenario") or scenario),
                    requested_answer_mode=raw_requested_answer_mode,
                    saved_answer_mode=saved_answer_mode,
                    profile=profile,
                )
                or auto_lane_learn_first_force_training_card(
                    request.message,
                    requested_scenario=str(coach_turn.get("scenario") or scenario),
                    requested_answer_mode=raw_requested_answer_mode,
                    saved_answer_mode=saved_answer_mode,
                    profile=profile,
                ),
                provider_service_override=coaching_service,
            )
        if should_attach_auto_resource_events(agent_meta):
            agent_meta = apply_auto_resource_agent_evidence(agent_meta, auto_resource_events)
        if not use_agent_loop and agent_meta:
            agent_meta["agentic"] = False
        persist_turn_reflection(
            workspace_id=workspace_id,
            session_id=state.session_id,
            user_message=request.message,
            scenario=str(coach_turn["scenario"]),
            response_language=request.response_language,
            answer_mode=answer_mode_preference_for_persistence(
                raw_requested_answer_mode,
                saved_answer_mode,
                request.answer_mode,
                profile.answer_policy if profile else None,
            ),
            coach_defaults=request.coach_defaults,
            coach_turn_data=coach_turn_mapping(coach_turn),
            stop_reason=str(agent_meta.get("stop_reason") or ""),
            recovered_stop_reason=str(agent_meta.get("recovered_stop_reason") or ""),
            local_sequence_fallback=bool(agent_meta.get("local_sequence_fallback")),
        )
        persist_recovered_plan_resume_after_turn(
            workspace_id=workspace_id,
            request=request,
            reply_content=assistant_content,
            agent_meta=agent_meta if isinstance(agent_meta, dict) else None,
            coach_context=coach_turn.get("coach_context") if isinstance(coach_turn, dict) else None,
            recovered_status=state.snapshot.plan_runtime_status
            if isinstance(state.snapshot.plan_runtime_status, dict)
            else None,
        )
        if not language_corruption_detected and not provider_failure_detected:
            persist_external_references_as_background(
                workspace_id=workspace_id,
                scenario=str(coach_turn["scenario"]),
                coach_turn_data=coach_turn_mapping(coach_turn),
            )
        state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
        state.snapshot.profile = runtime.repository.get_profile(workspace_id) or profile
        runtime.hydrate_plan_context(state.snapshot, workspace_id)
        hydrate_snapshot(
            state.snapshot,
            response_language=request.response_language,
            answer_mode=request.answer_mode or (profile.answer_policy if profile else None),
            scenario=str(coach_turn["scenario"]),
            learner_signal=str(coach_turn["learner_signal"]),
            message=request.message,
            session_workspace_id=workspace_id,
        )
        session_suggested_actions = list(coach_turn["suggested_actions"])
        if not provider_live_usable:
            session_suggested_actions = honest_suggested_actions_without_usable_provider(
                session_suggested_actions,
                response_language=request.response_language,
                snapshot=state.snapshot,
                current_task=state.snapshot.current_task,
                current_plan=state.snapshot.plan,
                current_evaluation=state.snapshot.evaluation,
            )
        response = build_session_response(
            state=state,
            request=request,
            reply_content=assistant_content,
            artifacts=dict(coach_turn["artifacts"]),
            suggested_actions=session_suggested_actions,
            scenario=str(coach_turn["scenario"]),
            learner_signal=str(coach_turn["learner_signal"]),
            coach_turn_data=coach_turn_mapping(coach_turn),
            agent_meta=agent_meta or None,
            attachment_delivery=attachment_delivery,
        )
        runtime.save_session_state(state.session_id)
        response_payload = json_object_payload(response)
        if agent_meta:
            response_payload.setdefault("agent_meta", agent_meta)
        return _finish_session_response(response_payload)

    @router.get("/session/history", response_model=None)
    def session_history(
        session_id: str | None = None,
        workspace_id: str | None = None,
        limit: int = 12,
    ) -> list[dict[str, object]]:
        resolved_workspace_id = current_workspace_id(session_id=session_id, workspace_id=workspace_id)
        _, state = resolve_session_history_state(session_id=session_id, workspace_id=resolved_workspace_id)
        if state is None:
            return []

        snapshot = getattr(state, "snapshot", None)
        messages = list(getattr(snapshot, "messages", []) or [])
        message_count = len(messages)
        latest_user_message = next(
            (
                message
                for message in reversed(messages)
                if getattr(message, "role", "") == "user" and str(getattr(message, "content", "") or "").strip()
            ),
            None,
        )
        latest_assistant_message = next(
            (
                message
                for message in reversed(messages)
                if getattr(message, "role", "") == "assistant" and str(getattr(message, "content", "") or "").strip()
            ),
            None,
        )
        session_memory = runtime.memory_service.snapshot(resolved_workspace_id)
        workspace_memory = session_memory.workspace if isinstance(session_memory.workspace, dict) else {}
        rolling_summary = str(workspace_memory.get("recent_summary") or session_memory.recent_summary or "").strip()
        summary = summarize_session_state(state) or rolling_summary
        if not summary:
            summary = rolling_summary or str(getattr(latest_assistant_message, "content", "") or "").strip()
        updated_at: str | None = None
        if messages:
            last_message = messages[-1]
            updated_at = str(getattr(last_message, "created_at", "") or "").strip()
            if not updated_at:
                timestamp = getattr(last_message, "timestamp", None)
                timestamp_isoformat = getattr(timestamp, "isoformat", None)
                if callable(timestamp_isoformat):
                    updated_at = str(timestamp_isoformat())
                elif timestamp is not None:
                    updated_at = str(timestamp)
        history_item: dict[str, object] = {
            "session_id": getattr(state, "session_id", session_id or ""),
            "workspace_id": getattr(state, "workspace_id", resolved_workspace_id),
            "workspace_name": getattr(state, "workspace_name", "") or "",
            "summary": summary,
            "message_count": message_count,
            "updated_at": updated_at,
        }
        if latest_user_message is not None:
            history_item["latest_user_message"] = str(getattr(latest_user_message, "content", "") or "").strip()
        if latest_assistant_message is not None:
            history_item["latest_assistant_message"] = str(
                getattr(latest_assistant_message, "content", "") or ""
            ).strip()
        return [history_item][:max(1, min(limit, 50))]

    @router.get("/session/checkpoints", response_model=None)
    def list_session_checkpoints(
        workspace_id: str,
        session_id: str | None = None,
        limit: int = 20,
    ) -> dict[str, object]:
        try:
            checkpoints = runtime.list_agent_turn_checkpoints(
                workspace_id=workspace_id,
                session_id=session_id,
                limit=limit,
            )
        except ValueError as exc:
            raise HTTPException(status_code=422, detail=str(exc)) from exc
        return {"checkpoints": checkpoints}

    def read_agent_checkpoint_or_raise(
        *,
        checkpoint_id: str,
        scope: AgentCheckpointAccessRequest,
    ) -> dict[str, object]:
        try:
            checkpoint = runtime.read_agent_turn_checkpoint(
                checkpoint_id=checkpoint_id,
                workspace_id=scope.workspace_id,
                session_id=scope.session_id,
            )
        except ValueError as exc:
            raise HTTPException(status_code=422, detail=str(exc)) from exc
        except PermissionError as exc:
            raise HTTPException(status_code=403, detail="Checkpoint access was denied.") from exc
        if checkpoint is None:
            raise HTTPException(status_code=404, detail="Checkpoint was not found for this workspace.")
        return checkpoint

