    @router.post("/session/steer")
    async def session_steer(payload: dict) -> dict[str, object]:
        """Queue a follow-up that the in-flight agent loop injects before the next LLM call."""

        session_id = str(payload.get("session_id") or payload.get("sessionId") or "").strip()
        text = str(payload.get("message") or payload.get("text") or "").strip()
        if not session_id or not text:
            raise HTTPException(status_code=400, detail="session_id and message are required.")
        queued = runtime.enqueue_steer_message(session_id, text)
        return {"ok": queued, "session_id": session_id, "queued": queued}

    @router.post("/session/message/stream")
    async def session_message_stream(payload: dict, http_request: Request):
        _stream_snapshot_fields.set(
            "slim" if str(payload.get("fields") or "") == "slim" else "full"
        )

        """Streaming coaching response via SSE."""
        stream_id = resolve_stream_id(payload)
        request = SessionMessageRequest.model_validate(payload)
        workspace_id = current_workspace_id(
            session_id=request.session_id,
            workspace_id=request.workspace_id,
        )
        # Mid-session host re-attest so trust flips apply before authority/capability.
        apply_host_workspace_trust_attestation(workspace_id, payload)
        state = runtime.ensure_session(request.session_id, workspace_id=workspace_id)
        profile = resolved_profile(state.workspace_id)
        raw_requested_answer_mode = str(
            payload.get("answer_mode") or payload.get("answerMode") or ""
        ).strip()
        saved_answer_mode = str(workspace_preferences(workspace_id).get("answer_mode") or "").strip()
        request = request_with_workspace_defaults(
            request,
            workspace_id=workspace_id,
            profile=profile,
        )
        profile = profile_with_teaching_style(profile, request.teaching_style)
        coaching_service = runtime.provider_service
        override_config = provider_config_from_payload(payload)
        api_key_override = provider_api_key_from_payload(payload)
        if override_config is not None or api_key_override is not None:
            coaching_service = runtime.provider_service_for(override_config, api_key_override)
        ensure_coach_provider_ready(
            coaching_service,
            response_language=request.response_language,
        )
        # Fail-closed: claim before unusable early-return so same request_id cannot
        # double-run honesty SSE. Live SSE is not fan-out-shared; waiters get
        # complete-frame replay with honesty stamps after owner publish.
        request_id = str(request.request_id or "").strip()
        request_key = (workspace_id, str(request.session_id or "").strip(), request_id)

        def _overlay_completed_session_response(cached_response: dict[str, object]) -> dict[str, object]:
            overlay_state = runtime.ensure_session(request.session_id, workspace_id=workspace_id)
            snapshot = overlay_state.snapshot
            pressure_blocks = pressure_without_live_object_blocks_mint(
                workspace_id,
                snapshot=snapshot,
                current_task=snapshot.current_task,
                current_plan=snapshot.plan,
                message=request.message,
            )
            streak_blocks = streak_without_live_object_blocks_mint(
                workspace_id,
                snapshot=snapshot,
                current_task=snapshot.current_task,
                current_plan=snapshot.plan,
            )
            live_status = (
                snapshot.plan_runtime_status
                if isinstance(snapshot.plan_runtime_status, dict)
                else {}
            )
            leftover_plan, leftover_runtime = leftover_runtime_for_workspace(workspace_id)
            leftover_runtime = leftover_runtime if isinstance(leftover_runtime, dict) else {}
            live_for_attach = bool(leftover_runtime) and leftover_formal_plan_is_live_for_fill(
                plan=snapshot.plan or leftover_plan,
                runtime=leftover_runtime,
                existing=leftover_runtime,
            )
            recovered_leftover = False
            if not live_for_attach:
                if leftover_plan is not None:
                    recovered_leftover = True
                elif live_status.get("recovered") is True and snapshot.plan is None:
                    recovered_leftover = True
            stamped = overlay_session_response_honesty_stamps(
                cached_response,
                pressure_blocks=pressure_blocks,
                streak_blocks=streak_blocks,
                recovered_leftover=recovered_leftover,
            )
            if stamped is not cached_response:
                with completed_session_requests_guard:
                    completed_session_requests[request_key] = stamped
            return stamped

        def _publish_stream_session_response(payload: dict[str, object]) -> dict[str, object]:
            if not request_id:
                return payload
            return publish_session_request_singleflight(
                request_key,
                payload,
                completed=completed_session_requests,
                inflight=inflight_session_requests,
                guard=completed_session_requests_guard,
            )

        def _fail_stream_session_singleflight(error: BaseException) -> None:
            if not request_id:
                return
            fail_session_request_singleflight(
                request_key,
                error,
                inflight=inflight_session_requests,
                guard=completed_session_requests_guard,
            )

        async def _waiter_stream_generate(
            kind: Literal["wait", "cached"],
            cached_response: dict[str, object] | None,
            shared_future: asyncio.Future | None,
        ):
            try:
                if kind == "wait":
                    assert shared_future is not None
                    shared_payload = await shared_future
                else:
                    assert cached_response is not None
                    shared_payload = cached_response
                stamped = _overlay_completed_session_response(shared_payload)
                yield sse_complete_frame(
                    tokens=0,
                    response_data=stamped,
                    stream_id=stream_id,
                    request_id=request_id,
                )
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                # Owner fail_inflight leaves no complete frame — still overlay honesty
                # stamps onto a failure complete so waiters do not drop recovered/
                # pressure/streak after cancel or mid-turn abort.
                failure_payload = attach_operation_reliability(
                    {},
                    phase="acked",
                    outcome="failure",
                    request_id=request_id or None,
                )
                stamped = _overlay_completed_session_response(failure_payload)
                yield stream_status_event("failed", stream_id)
                yield stream_status_event("acked", stream_id)
                yield (
                    "event: error\n"
                    f"data: {json.dumps({'error': redact_provider_error(exc, api_key=getattr(coaching_service, '_api_key', None)), 'stream_id': stream_id, 'terminal': True})}\n\n"
                )
                yield sse_complete_frame(
                    tokens=0,
                    response_data=stamped,
                    stream_id=stream_id,
                    outcome="failure",
                    request_id=request_id,
                    provider_failure_detected=True,
                )

        if request_id:
            kind, cached_response, shared_future = claim_session_request_singleflight(
                request_key,
                completed=completed_session_requests,
                inflight=inflight_session_requests,
                guard=completed_session_requests_guard,
            )
            if kind in ("wait", "cached"):
                # Do not register stream_id — owner already holds cancellation slot.
                return StreamingResponse(
                    _waiter_stream_generate(kind, cached_response, shared_future),
                    media_type="text/event-stream",
                )

        provider_live_usable = provider_is_live_usable(coaching_service, payload)
        if not provider_live_usable:
            turn_request = turn_request_from_stream_payload(payload, intent="coach")
            register_stream_cancellation(stream_id)
            return StreamingResponse(
                honest_unusable_provider_stream(
                    turn_request,
                    payload,
                    stream_id=stream_id,
                    original_intent="coach",
                    http_request=http_request,
                    publish_complete=_publish_stream_session_response if request_id else None,
                    fail_inflight=_fail_stream_session_singleflight if request_id else None,
                ),
                media_type="text/event-stream",
            )
        ensure_streaming_ready(coaching_service, request.response_language)
        ensure_agent_tools_ready(request, coaching_service)

        use_agent_stream = _resolve_agent_loop_enabled(
            request, coaching_service, stream=True, payload=payload
        )
        attachment_delivery = describe_request_attachment_delivery(
            request,
            coaching_service,
            use_agent_loop=use_agent_stream,
        )
        attachments_payload = [a.model_dump() for a in request.attachments]
        stream_recovery_requested = resource_contract_stream_recovery_requested(request.message)
        learning_project_state = workspace_learning_project_state(state.workspace_id)
        if learning_project_state.get("prompt_status") == "pending" and (
            message_confirms_learning_project_folder(request.message)
            or message_rejects_learning_project_folder(request.message)
        ):
            stream_recovery_requested = True

        async def stream_cancelled() -> bool:
            if stream_cancellation_requested(stream_id):
                return True
            try:
                return await http_request.is_disconnected()
            except RuntimeError:
                # Test clients and a few ASGI adapters do not expose a live
                # receive channel after the response starts.
                return False

        async def generate():
            token_count = 0
            streamed_reply_content = ""
            pending_streamed_reply_content = ""
            stream_user_message: ChatMessage | None = None
            stream_assistant_message_ids: set[str] = set()
            stream_committed = False
            stream_failed = False
            stream_singleflight_published = False
            preexisting_assistant_ids = {
                message.id
                for message in state.snapshot.messages
                if message.role == "assistant"
            }

            async def _abort_fail_closed(*, error_detail: object | None = None):
                """Emit failed->acked and publish failure complete so same request_id cannot remint."""
                nonlocal stream_failed, stream_singleflight_published
                stream_failed = True
                failure_payload: dict[str, object] = attach_operation_reliability(
                    {},
                    phase="acked",
                    outcome="failure",
                    request_id=request_id or None,
                )
                if request_id and not stream_singleflight_published:
                    failure_payload = _publish_stream_session_response(failure_payload)
                    stream_singleflight_published = True
                yield stream_status_event("failed", stream_id)
                if error_detail is not None:
                    yield (
                        "event: error\n"
                        f"data: {json.dumps({'error': error_detail, 'stream_id': stream_id, 'terminal': True})}\n\n"
                    )
                yield stream_status_event("acked", stream_id)
                yield sse_complete_frame(
                    tokens=token_count,
                    response_data=failure_payload,
                    stream_id=stream_id,
                    outcome="failure",
                    request_id=request_id or None,
                    provider_failure_detected=True,
                )

            async def _abort_interrupted():
                """Client disconnected: no listener remains for a terminal frame.

                Mint no failure complete so the user turn stays recoverable as
                interrupted on reconnect instead of looking conclusively failed.
                """
                yield stream_status_event("cancelled", stream_id)

            async def _abort_for_cancellation():
                """Explicit /stream/cancel stays fail-closed; a client disconnect only interrupts."""
                if stream_cancellation_requested(stream_id):
                    async for _closed_frame in _abort_fail_closed():
                        yield _closed_frame
                    return
                async for _abort_frame in _abort_interrupted():
                    yield _abort_frame

            try:
                if await stream_cancelled():
                    async for _abort_frame in _abort_for_cancellation():
                        yield _abort_frame
                    return
                yield stream_status_event("preparing_context", stream_id)
                stream_user_message, _ = prepare_stream_user_message(
                    state=state,
                    request=request,
                    profile=profile,
                    attachment_delivery=attachment_delivery,
                    stream_id=stream_id,
                )
                safe_activate_training_card_from_coach_request(
                    workspace_id=state.workspace_id,
                    snapshot=state.snapshot,
                    message=request.message,
                    current_file=request.current_file,
                    response_language=request.response_language,
                    provider_service_override=coaching_service,
                )
                state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
                coach_turn: CoachTurnPayload = resolve_coach_turn(
                    state=state,
                    profile=profile,
                    request=request,
                    message=request.message,
                    coaching_service=coaching_service,
                    current_task=state.snapshot.current_task,
                    current_plan=state.snapshot.plan,
                    current_evaluation=state.snapshot.evaluation,
                )
                scenario = str(coach_turn.get("scenario") or "general")
                if guarantee_guided_learn_first_training_card(
                    workspace_id=state.workspace_id,
                    scenario=str(coach_turn["scenario"] or ""),
                    message=request.message,
                    current_file=request.current_file,
                    response_language=request.response_language,
                    active_thread=state.snapshot.memory.active_thread,
                    requested_answer_mode=raw_requested_answer_mode,
                    saved_answer_mode=saved_answer_mode,
                    profile=profile,
                ):
                    state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
                guided_training_prefers_local_reply = should_bypass_agent_loop_for_guided_training(
                    workspace_id=state.workspace_id,
                    scenario=str(coach_turn["scenario"] or scenario),
                    message=request.message,
                    active_view=request.active_view,
                    requested_answer_mode=raw_requested_answer_mode,
                    saved_answer_mode=saved_answer_mode,
                    profile=profile,
                )
                guided_training_local_reply = (
                    build_guided_training_visible_fallback(
                        workspace_id=state.workspace_id,
                        response_language=request.response_language,
                    )
                    if guided_training_prefers_local_reply
                    else None
                )
                auto_resource_events = auto_resource_lookup_tool_events(
                    dict(coach_turn["coach_context"]),
                    request.message,
                )

                full_content = ""
                agent_summary: str | None = None
                agent_next_step: str | None = None
                agent_stop_reason: str | None = None
                agent_decision: str | None = None
                agent_blocker: str | None = None
                agent_teaching_note: str | None = None
                agent_resume_thread: str | None = None
                agent_confidence: str | None = None
                agent_evidence: list[object] | None = None
                agent_tool_events: list[dict[str, object]] = []
                agent_steps: list[dict[str, object]] = []
                provider_failure_detected = False
                final_agent_meta: dict[str, object] = {}
                if guided_training_local_reply is None:
                    yield stream_status_event("requesting_model", stream_id)
                if guided_training_local_reply is not None:
                    full_content, updated_coach_turn, guided_meta = apply_guided_training_visible_fallback(
                        coach_turn=coach_turn_mapping(coach_turn),
                        fallback=guided_training_local_reply,
                    )
                    coach_turn = extract_coach_turn_payload(updated_coach_turn)
                    final_agent_meta.update(guided_meta)
                    token_count += 1
                elif use_agent_stream and not guided_training_prefers_local_reply:
                    agent_context = dict(coach_turn["coach_context"])
                    agent_context["__runtime__"] = runtime
                    agent_context["workspace_id"] = workspace_id
                    agent_context["session_id"] = state.session_id
                    agent_context["stream_cancel_event"] = stream_cancellation_events.get(stream_id)
                    async for event in coaching_service.coaching_reply_agentic_stream(
                        profile,
                        request.message,
                        request.current_file.model_dump() if request.current_file else None,
                        response_language=request.response_language,
                        answer_mode=request.answer_mode,
                        coach_context=agent_context,
                        attachments=attachments_payload,
                        protocol=getattr(coaching_service._config, "protocol", None) if coaching_service._config else None,
                        history=build_conversation_history(
                            state.snapshot.messages,
                            drop_latest_user=True,
                        ),
                        ):
                            if await stream_cancelled():
                                async for _abort_frame in _abort_for_cancellation():
                                    yield _abort_frame
                                return
                            event_type = str(event.get("type") or "")
                            if event_type == "text":
                                delta = str(event.get("delta") or "")
                                if delta:
                                    full_content += delta
                                    token_count += 1
                                    if event.get("safe_to_stream") is True and (
                                        not requires_formal_plan_commit(request)
                                        or formal_plan_commit_tool_succeeded(agent_tool_events)
                                    ):
                                        visible_delta, pending_streamed_reply_content = safe_stream_delta(
                                            pending_streamed_reply_content,
                                            delta,
                                            full_content,
                                        )
                                        if visible_delta:
                                            streamed_reply_content += visible_delta
                                            yield f"data: {json.dumps({'chunk': visible_delta})}\n\n"
                            elif event_type == "tool_call":
                                agent_tool_events.append(dict(event))
                                yield stream_frame("tool_call", event, stream_id)
                            elif event_type == "tool_result":
                                agent_tool_events.append(dict(event))
                                yield stream_frame("tool_result", event, stream_id)
                            elif event_type == "step":
                                agent_steps.append(dict(event))
                                yield stream_frame("step", event, stream_id)
                            elif event_type == "final":
                                final_content = str(event.get("content") or "")
                                if final_content:
                                    full_content = final_content
                                agent_summary = event.get("summary")
                                agent_next_step = event.get("next_step")
                                agent_stop_reason = event.get("stop_reason")
                                agent_decision = event.get("decision")
                                agent_blocker = event.get("blocker")
                                agent_teaching_note = event.get("teaching_note")
                                agent_resume_thread = event.get("resume_thread")
                                agent_confidence = event.get("confidence")
                                agent_evidence = (
                                    list(event.get("evidence") or [])
                                    if isinstance(event.get("evidence"), list)
                                    else None
                                )
                            elif event_type == "error":
                                async for _abort_frame in _abort_fail_closed(
                                    error_detail=redact_provider_error(
                                        event.get("detail"),
                                        api_key=getattr(coaching_service, "_api_key", None),
                                    ),
                                ):
                                    yield _abort_frame
                                return
                    if full_content:
                        full_content = coaching_service.finalize_coaching_reply(
                            full_content,
                            profile=profile,
                            message=request.message,
                            current_file=request.current_file.model_dump() if request.current_file else None,
                            response_language=request.response_language,
                            answer_mode=request.answer_mode,
                            coach_context=dict(coach_turn["coach_context"]),
                        )
                    if not agent_resume_thread and (agent_summary or agent_next_step):
                        agent_resume_thread = build_resume_thread_text(
                            str(agent_summary or "").strip(),
                            str(agent_next_step or "").strip(),
                            response_language=request.response_language,
                        )
                    if not full_content:
                        local_sequence_fallback = build_local_sequence_visible_fallback(
                            coach_context=dict(coach_turn["coach_context"]),
                            response_language=request.response_language,
                        )
                        if local_sequence_fallback is not None:
                            full_content = local_sequence_fallback["reply"]
                            coaching_service.clear_last_reply_override()
                            agent_summary = agent_summary or local_sequence_fallback["summary"]
                            agent_next_step = agent_next_step or local_sequence_fallback["next_step"]
                            agent_teaching_note = (
                                agent_teaching_note or local_sequence_fallback["teaching_note"]
                            )
                            agent_resume_thread = (
                                agent_resume_thread or local_sequence_fallback["resume_thread"]
                            )
                            final_agent_meta["local_sequence_fallback"] = True
                            if str(agent_stop_reason or "").strip() == "empty_response":
                                final_agent_meta["fell_back"] = True
                                final_agent_meta["recovered_stop_reason"] = "empty_response"
                                final_agent_meta["stop_reason"] = "completed"
                        else:
                            full_content = coaching_service._fallback_empty_reply(
                                profile=profile,
                                message=request.message,
                                current_file=(
                                    request.current_file.model_dump() if request.current_file else None
                                ),
                                response_language=request.response_language,
                                answer_mode=request.answer_mode,
                                coach_context=dict(coach_turn["coach_context"]),
                            )
                        token_count += 1
                    updated_coach_turn = merge_agent_finalize_into_coach_turn(
                        coach_turn_mapping(coach_turn),
                        summary=agent_summary,
                        next_step=agent_next_step,
                        blocker=agent_blocker,
                        resume_thread=agent_resume_thread,
                        decision=agent_decision,
                        teaching_note=agent_teaching_note,
                        confidence=agent_confidence,
                        evidence=agent_evidence,
                    )
                    coach_turn = extract_coach_turn_payload(updated_coach_turn)
                else:
                    try:
                        async for chunk in coaching_service.coaching_reply_stream(
                            profile,
                            request.message,
                            request.current_file.model_dump() if request.current_file else None,
                            response_language=request.response_language,
                            answer_mode=request.answer_mode,
                            coach_context=dict(coach_turn["coach_context"]),
                            history=build_conversation_history(
                                state.snapshot.messages,
                                drop_latest_user=True,
                            ),
                            cancel_event=stream_cancellation_events.get(stream_id),
                        ):
                            if await stream_cancelled():
                                async for _abort_frame in _abort_for_cancellation():
                                    yield _abort_frame
                                return
                            full_content += chunk
                            token_count += 1
                            visible_chunk, pending_streamed_reply_content = safe_stream_delta(
                                pending_streamed_reply_content,
                                chunk,
                                full_content,
                            )
                            if visible_chunk and not requires_formal_plan_commit(request):
                                streamed_reply_content += visible_chunk
                                yield f"data: {json.dumps({'chunk': visible_chunk})}\n\n"
                    except Exception:
                        if not stream_recovery_requested or streamed_reply_content or full_content:
                            raise
                        # A grounded resource/project confirmation may recover through
                        # the existing synchronous contract only after the live stream
                        # failed before any visible provider text was emitted.
                        # Nested /session/message must not re-claim this stream's request_id
                        # (owner future would deadlock waiters + this generator).
                        nested_payload = dict(payload)
                        nested_payload.pop("request_id", None)
                        nested_payload.pop("requestId", None)
                        response_data = await session_message(nested_payload)
                        response_payload = (
                            {str(key): value for key, value in response_data.items()}
                            if isinstance(response_data, dict)
                            else json_object_payload(response_data)
                        )
                        if "agent" not in response_payload and isinstance(
                            response_payload.get("agent_meta"),
                            dict,
                        ):
                            response_payload["agent"] = response_payload["agent_meta"]
                        reply_record = response_payload.get("reply")
                        reply_content = (
                            str(reply_record.get("content") or "").strip()
                            if isinstance(reply_record, dict)
                            else ""
                        )
                        if reply_content:
                            token_count += 1
                            yield f"data: {json.dumps({'chunk': reply_content})}\n\n"
                        response_payload = _publish_stream_session_response(response_payload)
                        stream_singleflight_published = True
                        yield sse_complete_frame(
                            tokens=token_count,
                            response_data=response_payload,
                            stream_id=stream_id,
                            provider_failure_detected=True,
                        )
                        return
                    stream_finalization = coaching_service.consume_stream_finalization()
                    if stream_finalization is not None:
                        full_content = stream_finalization[1]
                    else:
                        full_content = coaching_service.finalize_coaching_reply(
                            full_content,
                            profile=profile,
                            message=request.message,
                            current_file=request.current_file.model_dump() if request.current_file else None,
                            response_language=request.response_language,
                            answer_mode=request.answer_mode,
                            coach_context=dict(coach_turn["coach_context"]),
                        )

                if await stream_cancelled():
                    async for _abort_frame in _abort_for_cancellation():
                        yield _abort_frame
                    return
                provider_empty_reply_override = consume_provider_empty_reply_override(
                    coaching_service=coaching_service,
                    snapshot=state.snapshot,
                    coach_turn=coach_turn_mapping(coach_turn),
                    response_language=request.response_language,
                    assistant_content=full_content,
                )
                if provider_empty_reply_override is not None:
                    provider_failure_detected = True
                    full_content, updated_coach_turn, override_meta = provider_empty_reply_override
                    coach_turn = extract_coach_turn_payload(updated_coach_turn)
                    final_agent_meta.update(override_meta)
                else:
                    provider_failure_override = consume_provider_reply_failure_override(
                        coaching_service=coaching_service,
                        snapshot=state.snapshot,
                        coach_turn=coach_turn_mapping(coach_turn),
                        message=request.message,
                        response_language=request.response_language,
                        workspace_id=state.workspace_id,
                    )
                    if provider_failure_override is not None:
                        provider_failure_detected = True
                        full_content, updated_coach_turn, override_meta = provider_failure_override
                        coach_turn = extract_coach_turn_payload(updated_coach_turn)
                        final_agent_meta.update(override_meta)

                if not provider_failure_detected:
                    visible_agent_meta = {
                        "stop_reason": agent_stop_reason,
                        "summary": agent_summary,
                        "next_step": agent_next_step,
                        "decision": agent_decision,
                        "blocker": agent_blocker,
                        "teaching_note": agent_teaching_note,
                        "resume_thread": agent_resume_thread,
                        "confidence": agent_confidence,
                        "evidence": agent_evidence,
                        "steps": agent_steps,
                        "tool_events": agent_tool_events,
                        "agentic": use_agent_stream and not guided_training_prefers_local_reply,
                        **final_agent_meta,
                    }
                    full_content, updated_coach_turn, final_agent_meta, _guided_lane_repaired = (
                        apply_guided_lane_visible_fallback(
                            reply=full_content,
                            scenario=str(coach_turn.get("scenario") or scenario),
                            learner_message=request.message,
                            response_language=request.response_language,
                            coach_turn=coach_turn_mapping(coach_turn),
                            agent_meta=visible_agent_meta,
                        )
                    )
                    coach_turn = extract_coach_turn_payload(updated_coach_turn)
                    repaired_summary = final_agent_meta.get("summary")
                    agent_summary = repaired_summary if isinstance(repaired_summary, str) else None
                    repaired_next_step = final_agent_meta.get("next_step")
                    agent_next_step = (
                        repaired_next_step if isinstance(repaired_next_step, str) else None
                    )
                    repaired_decision = final_agent_meta.get("decision")
                    agent_decision = repaired_decision if isinstance(repaired_decision, str) else None
                    repaired_blocker = final_agent_meta.get("blocker")
                    agent_blocker = repaired_blocker if isinstance(repaired_blocker, str) else None
                    repaired_teaching_note = final_agent_meta.get("teaching_note")
                    agent_teaching_note = (
                        repaired_teaching_note if isinstance(repaired_teaching_note, str) else None
                    )
                    repaired_resume_thread = final_agent_meta.get("resume_thread")
                    agent_resume_thread = (
                        repaired_resume_thread if isinstance(repaired_resume_thread, str) else None
                    )
                    repaired_confidence = final_agent_meta.get("confidence")
                    agent_confidence = (
                        repaired_confidence if isinstance(repaired_confidence, str) else None
                    )
                    repaired_evidence = final_agent_meta.get("evidence")
                    agent_evidence = (
                        list(repaired_evidence)
                        if isinstance(repaired_evidence, list)
                        else None
                    )
                    ensure_explicit_training_card_after_coach_reply(
                        state=state,
                        message=request.message,
                        current_file=request.current_file,
                        response_language=request.response_language,
                        fallback_scenario=str(coach_turn.get("scenario") or ""),
                        force_training_card=auto_preference_requests_training_card(
                            request.message,
                            requested_scenario=str(coach_turn.get("scenario") or scenario),
                            requested_answer_mode=raw_requested_answer_mode,
                            saved_answer_mode=saved_answer_mode,
                            profile=profile,
                        )
                        or auto_lane_learn_first_force_training_card(
                            request.message,
                            requested_scenario=str(coach_turn.get("scenario") or scenario),
                            requested_answer_mode=raw_requested_answer_mode,
                            saved_answer_mode=saved_answer_mode,
                            profile=profile,
                        ),
                        provider_service_override=coaching_service,
                    )

                if await stream_cancelled():
                    async for _abort_frame in _abort_for_cancellation():
                        yield _abort_frame
                    return
                persist_turn_reflection(
                    workspace_id=workspace_id,
                    session_id=state.session_id,
                    user_message=request.message,
                    scenario=str(coach_turn["scenario"]),
                    response_language=request.response_language,
                    answer_mode=answer_mode_preference_for_persistence(
                        raw_requested_answer_mode,
                        saved_answer_mode,
                        request.answer_mode,
                        profile.answer_policy if profile else None,
                    ),
                    coach_defaults=request.coach_defaults,
                    coach_turn_data=coach_turn_mapping(coach_turn),
                    stop_reason=str(final_agent_meta.get("stop_reason") or ""),
                    recovered_stop_reason=str(final_agent_meta.get("recovered_stop_reason") or ""),
                    local_sequence_fallback=bool(final_agent_meta.get("local_sequence_fallback")),
                )
                persist_recovered_plan_resume_after_turn(
                    workspace_id=workspace_id,
                    request=request,
                    reply_content=full_content,
                    agent_meta=final_agent_meta if isinstance(final_agent_meta, dict) else None,
                    coach_context=coach_turn.get("coach_context") if isinstance(coach_turn, dict) else None,
                    recovered_status=state.snapshot.plan_runtime_status
                    if isinstance(state.snapshot.plan_runtime_status, dict)
                    else None,
                )
                if not provider_failure_detected:
                    persist_external_references_as_background(
                        workspace_id=workspace_id,
                        scenario=str(coach_turn["scenario"]),
                        coach_turn_data=coach_turn_mapping(coach_turn),
                    )
                state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
                state.snapshot.profile = runtime.repository.get_profile(workspace_id) or profile
                runtime.hydrate_plan_context(state.snapshot, workspace_id)
                hydrate_snapshot(
                    state.snapshot,
                    response_language=request.response_language,
                    answer_mode=request.answer_mode or (profile.answer_policy if profile else None),
                    scenario=str(coach_turn["scenario"]),
                    learner_signal=str(coach_turn["learner_signal"]),
                    message=request.message,
                    session_workspace_id=workspace_id,
                )

                if use_agent_stream and not guided_training_prefers_local_reply:
                    stream_agent_meta = {
                        "stop_reason": agent_stop_reason,
                        "summary": agent_summary,
                        "next_step": agent_next_step,
                        "decision": agent_decision,
                        "blocker": agent_blocker,
                        "teaching_note": agent_teaching_note,
                        "resume_thread": agent_resume_thread,
                        "confidence": agent_confidence,
                        "evidence": agent_evidence,
                        "steps": agent_steps,
                        "tool_events": agent_tool_events,
                        "agentic": True,
                        **(normalize_attachment_delivery_payload(attachment_delivery) or {}),
                    }
                    final_agent_meta = {**stream_agent_meta, **final_agent_meta}
                if should_attach_auto_resource_events(final_agent_meta):
                    final_agent_meta = apply_auto_resource_agent_evidence(
                        final_agent_meta,
                        auto_resource_events,
                    )
                response_data = json_object_payload(
                    build_session_response(
                        state=state,
                        request=request,
                        reply_content=full_content,
                        artifacts=dict(coach_turn["artifacts"]),
                        suggested_actions=list(coach_turn["suggested_actions"]),
                        scenario=str(coach_turn["scenario"]),
                        learner_signal=str(coach_turn["learner_signal"]),
                        coach_turn_data=coach_turn_mapping(coach_turn),
                        agent_meta=final_agent_meta or None,
                        attachment_delivery=attachment_delivery,
                    )
                )
                reply_record = response_data.get("reply")
                visible_content = (
                    str(reply_record.get("content") or "").strip()
                    if isinstance(reply_record, dict)
                    else ""
                )
                visible_delta = completion_stream_delta(streamed_reply_content, visible_content)
                if visible_delta:
                    token_count += 1
                    yield f"data: {json.dumps({'chunk': visible_delta})}\n\n"
                if final_agent_meta:
                    response_data["agent"] = final_agent_meta
                if await stream_cancelled():
                    if not stream_cancellation_requested(stream_id):
                        # Client disconnected: no listener remains for a terminal frame;
                        # leave the turn recoverable as interrupted, mint no fake complete.
                        yield stream_status_event("cancelled", stream_id)
                        return
                    # Built payload but aborted before commit: publish failure so same
                    # request_id cannot remint, waiters get stamped complete, not hang.
                    stream_failed = True
                    response_data = attach_operation_reliability(
                        response_data,
                        phase="acked",
                        outcome="failure",
                        request_id=request_id or None,
                    )
                    response_data = _publish_stream_session_response(response_data)
                    stream_singleflight_published = True
                    yield stream_status_event("failed", stream_id)
                    yield stream_status_event("acked", stream_id)
                    yield sse_complete_frame(
                        tokens=token_count,
                        response_data=response_data,
                        stream_id=stream_id,
                        outcome="failure",
                        request_id=request_id or None,
                        provider_failure_detected=True,
                    )
                    return
                stream_assistant_message_ids.update(
                    message.id
                    for message in state.snapshot.messages
                    if message.role == "assistant" and message.id not in preexisting_assistant_ids
                )
                runtime.save_session_state(state.session_id)
                stream_committed = True
                response_data = _publish_stream_session_response(response_data)
                stream_singleflight_published = True
                yield sse_complete_frame(
                    tokens=token_count,
                    response_data=response_data,
                    stream_id=stream_id,
                    provider_failure_detected=provider_failure_detected,
                )

            except asyncio.CancelledError:
                # Fail-closed: failed->acked + publish failure complete (no remint).
                logger.info("trainer_stream_cancelled", extra={"stream_id": stream_id})
                async for _abort_frame in _abort_fail_closed():
                    yield _abort_frame
                return
            except Exception as exc:
                async for _abort_frame in _abort_fail_closed(
                    error_detail=redact_provider_error(
                        exc,
                        api_key=getattr(coaching_service, "_api_key", None),
                    ),
                ):
                    yield _abort_frame
            finally:
                if request_id and not stream_singleflight_published:
                    fail_session_request_singleflight(
                        request_key,
                        RuntimeError(
                            "session stream failed"
                            if stream_failed
                            else "session stream completed without publishing a payload"
                        ),
                        inflight=inflight_session_requests,
                        guard=completed_session_requests_guard,
                    )
                finalize_stream_persistence(
                    state=state,
                    user_message=stream_user_message,
                    stream_id=stream_id,
                    committed=stream_committed,
                    assistant_message_ids=stream_assistant_message_ids,
                    stream_state=(
                        "completed"
                        if stream_committed
                        else ("failed" if stream_failed else "interrupted")
                    ),
                )
                unregister_stream_cancellation(stream_id)

        register_stream_cancellation(stream_id)
        return StreamingResponse(generate(), media_type="text/event-stream")

    @router.post("/turn/stream")
    async def turn_stream(payload: dict, http_request: Request):
        _stream_snapshot_fields.set(
            "slim" if str(payload.get("fields") or "") == "slim" else "full"
        )

        stream_id = resolve_stream_id(payload)
        parsed_request = TurnRequest.model_validate(payload)
        if not isinstance(parsed_request, TurnRequest):
            raise TypeError("Turn stream payload did not produce a TurnRequest.")
        request: TurnRequest = _normalize_resource_turn_request(parsed_request)
        original_intent = parsed_request.intent
        state: SessionState | None = None
        profile: UserProfile | None = None
        coaching_service: ProviderService | None = None
        use_agent_stream = False
        workspace_id = current_workspace_id(
            session_id=request.session_id,
            workspace_id=request.workspace_id,
        )
        # Mid-session host re-attest so trust flips apply before authority/capability.
        apply_host_workspace_trust_attestation(workspace_id, payload)
        state = runtime.ensure_session(request.session_id, workspace_id=workspace_id)
        profile = resolved_profile(state.workspace_id)
        raw_requested_answer_mode = str(
            payload.get("answer_mode") or payload.get("answerMode") or ""
        ).strip()
        saved_answer_mode = str(
            workspace_preferences(workspace_id).get("answer_mode") or ""
        ).strip()
        request_with_defaults = request_with_workspace_defaults(
            request,
            workspace_id=workspace_id,
            profile=profile,
        )
        if not isinstance(request_with_defaults, TurnRequest):
            raise TypeError("Workspace defaults did not produce a TurnRequest.")
        request = request_with_defaults
        profile = profile_with_teaching_style(profile, request.teaching_style)
        # Validate every streaming lane before returning StreamingResponse.
        # Otherwise a formal Plan/tools request can be sent as HTTP 200 and
        # fail only after the SSE body has started, which makes capability
        # state look successful to the webview and prevents reliable recovery.
        coaching_service = build_coaching_service(payload)
        ensure_coach_provider_ready(
            coaching_service,
            response_language=request.response_language,
        )
        # Fail-closed: same request_id must not double-mint on /turn/stream.
        # Claim before unusable early-return; waiters get complete-frame + honesty overlay.
        request_id = str(request.request_id or "").strip()
        request_key = (workspace_id, str(request.session_id or "").strip(), request_id)

        def _overlay_completed_turn_response(cached_response: dict[str, object]) -> dict[str, object]:
            overlay_state = runtime.ensure_session(request.session_id, workspace_id=workspace_id)
            snapshot = overlay_state.snapshot
            pressure_blocks = pressure_without_live_object_blocks_mint(
                workspace_id,
                snapshot=snapshot,
                current_task=snapshot.current_task,
                current_plan=snapshot.plan,
                message=request.message,
            )
            streak_blocks = streak_without_live_object_blocks_mint(
                workspace_id,
                snapshot=snapshot,
                current_task=snapshot.current_task,
                current_plan=snapshot.plan,
            )
            live_status = (
                snapshot.plan_runtime_status
                if isinstance(snapshot.plan_runtime_status, dict)
                else {}
            )
            leftover_plan, leftover_runtime = leftover_runtime_for_workspace(workspace_id)
            leftover_runtime = leftover_runtime if isinstance(leftover_runtime, dict) else {}
            live_for_attach = bool(leftover_runtime) and leftover_formal_plan_is_live_for_fill(
                plan=snapshot.plan or leftover_plan,
                runtime=leftover_runtime,
                existing=leftover_runtime,
            )
            recovered_leftover = False
            if not live_for_attach:
                if leftover_plan is not None:
                    recovered_leftover = True
                elif live_status.get("recovered") is True and snapshot.plan is None:
                    recovered_leftover = True
            stamped = overlay_session_response_honesty_stamps(
                cached_response,
                pressure_blocks=pressure_blocks,
                streak_blocks=streak_blocks,
                recovered_leftover=recovered_leftover,
            )
            if stamped is not cached_response:
                with completed_session_requests_guard:
                    completed_session_requests[request_key] = stamped
            return stamped

        def _publish_stream_turn_response(payload_map: dict[str, object]) -> dict[str, object]:
            if not request_id:
                return payload_map
            return publish_session_request_singleflight(
                request_key,
                payload_map,
                completed=completed_session_requests,
                inflight=inflight_session_requests,
                guard=completed_session_requests_guard,
            )

        def _fail_stream_turn_singleflight(error: BaseException) -> None:
            if not request_id:
                return
            fail_session_request_singleflight(
                request_key,
                error,
                inflight=inflight_session_requests,
                guard=completed_session_requests_guard,
            )

        if request_id:
            kind, cached_response, shared_future = claim_session_request_singleflight(
                request_key,
                completed=completed_session_requests,
                inflight=inflight_session_requests,
                guard=completed_session_requests_guard,
            )
            if kind in ("wait", "cached"):
                async def waiter_generate():
                    try:
                        if kind == "wait":
                            assert shared_future is not None
                            shared_payload = await shared_future
                        else:
                            assert cached_response is not None
                            shared_payload = cached_response
                        stamped = _overlay_completed_turn_response(shared_payload)
                        yield sse_complete_frame(
                            tokens=0,
                            response_data=stamped,
                            stream_id=stream_id,
                            request_id=request_id,
                        )
                    except asyncio.CancelledError:
                        raise
                    except Exception as exc:
                        # Owner fail_inflight leaves no complete frame — still overlay
                        # honesty stamps onto a failure complete for waiters.
                        failure_payload = attach_operation_reliability(
                            {},
                            phase="acked",
                            outcome="failure",
                            request_id=request_id or None,
                        )
                        stamped = _overlay_completed_turn_response(failure_payload)
                        yield stream_status_event("failed", stream_id)
                        yield stream_status_event("acked", stream_id)
                        yield (
                            "event: error\n"
                            f"data: {json.dumps({'error': redact_provider_error(exc, api_key=getattr(coaching_service, '_api_key', None)), 'stream_id': stream_id, 'terminal': True})}\n\n"
                        )
                        yield sse_complete_frame(
                            tokens=0,
                            response_data=stamped,
                            stream_id=stream_id,
                            outcome="failure",
                            request_id=request_id,
                            provider_failure_detected=True,
                        )

                return StreamingResponse(waiter_generate(), media_type="text/event-stream")

        provider_live_usable = provider_is_live_usable(coaching_service, payload)
        if not provider_live_usable:
            register_stream_cancellation(stream_id)
            return StreamingResponse(
                honest_unusable_provider_stream(
                    request,
                    payload,
                    stream_id=stream_id,
                    original_intent=original_intent,
                    http_request=http_request,
                    publish_complete=_publish_stream_turn_response if request_id else None,
                    fail_inflight=_fail_stream_turn_singleflight if request_id else None,
                ),
                media_type="text/event-stream",
            )
        ensure_streaming_ready(coaching_service, request.response_language)
        ensure_agent_tools_ready(request, coaching_service)
        use_agent_stream = _resolve_agent_loop_enabled(
            request, coaching_service, stream=True, payload=payload
        )
        stream_recovery_requested = (
            request.intent == "coach"
            and resource_contract_stream_recovery_requested(request.message)
        )
        def json_response_payload(value: object) -> dict[str, object]:
            encoded_value = to_json_payload(value)
            if not isinstance(encoded_value, dict):
                raise TypeError("Turn response payload must be a mapping.")
            return {str(key): item for key, item in encoded_value.items()}

        async def stream_cancelled() -> bool:
            if stream_cancellation_requested(stream_id):
                return True
            try:
                return await http_request.is_disconnected()
            except RuntimeError:
                return False

        async def generate():
            nonlocal coaching_service, profile, request, state, use_agent_stream, workspace_id
            token_count = 0
            streamed_reply_content = ""
            pending_streamed_reply_content = ""
            stream_user_message: ChatMessage | None = None
            stream_assistant_message_ids: set[str] = set()
            stream_committed = False
            stream_failed = False
            stream_singleflight_published = False
            preexisting_assistant_ids: set[str] = set()

            async def _abort_fail_closed(*, error_detail: object | None = None):
                """Emit failed->acked and publish failure complete so same request_id cannot remint."""
                nonlocal stream_failed, stream_singleflight_published
                stream_failed = True
                failure_payload: dict[str, object] = attach_operation_reliability(
                    {},
                    phase="acked",
                    outcome="failure",
                    request_id=request_id or None,
                )
                if request_id and not stream_singleflight_published:
                    failure_payload = _publish_stream_turn_response(failure_payload)
                    stream_singleflight_published = True
                yield stream_status_event("failed", stream_id)
                if error_detail is not None:
                    yield (
                        "event: error\n"
                        f"data: {json.dumps({'error': error_detail, 'stream_id': stream_id, 'terminal': True})}\n\n"
                    )
                yield stream_status_event("acked", stream_id)
                yield sse_complete_frame(
                    tokens=token_count,
                    response_data=failure_payload,
                    stream_id=stream_id,
                    outcome="failure",
                    request_id=request_id or None,
                    provider_failure_detected=True,
                )

            async def _abort_interrupted():
                """Client disconnected: no listener remains for a terminal frame.

                Mint no failure complete so the user turn stays recoverable as
                interrupted on reconnect instead of looking conclusively failed.
                """
                yield stream_status_event("cancelled", stream_id)

            async def _abort_for_cancellation():
                """Explicit /stream/cancel stays fail-closed; a client disconnect only interrupts."""
                if stream_cancellation_requested(stream_id):
                    async for _closed_frame in _abort_fail_closed():
                        yield _closed_frame
                    return
                async for _abort_frame in _abort_interrupted():
                    yield _abort_frame

            try:
                if await stream_cancelled():
                    async for _abort_frame in _abort_for_cancellation():
                        yield _abort_frame
                    return
                yield stream_status_event("preparing_context", stream_id)
                if request.intent != "coach":
                    preparation_or_response, prepared_artifacts, prepared_service = await execute_turn(
                        request,
                        payload,
                        stream=True,
                        stream_id=stream_id,
                    )
                    if not (
                        isinstance(preparation_or_response, dict)
                        and preparation_or_response.get("__turn_stream_preparation__") is True
                    ):
                        raise TypeError("Turn stream preparation was not produced for the requested turn.")

                    preparation = preparation_or_response
                    prepared_state = preparation.get("state")
                    prepared_request = preparation.get("request")
                    prepared_profile = preparation.get("profile")
                    prepared_coach_turn = preparation.get("coach_turn_data")
                    if not isinstance(prepared_state, SessionState):
                        raise TypeError("Turn stream preparation is missing session state.")
                    if not isinstance(prepared_request, TurnRequest):
                        raise TypeError("Turn stream preparation is missing the normalized request.")
                    if not isinstance(prepared_profile, UserProfile):
                        raise TypeError("Turn stream preparation is missing the learner profile.")
                    if not isinstance(prepared_coach_turn, dict):
                        raise TypeError("Turn stream preparation is missing coach-turn data.")
                    if not isinstance(prepared_service, ProviderService):
                        raise TypeError("Turn stream preparation is missing the provider service.")

                    state = prepared_state
                    preexisting_assistant_ids = {
                        message.id
                        for message in state.snapshot.messages
                        if message.role == "assistant"
                    }
                    stream_user_message = next(
                        (
                            message
                            for message in reversed(state.snapshot.messages)
                            if message.role == "user"
                            and str(message.metadata.get("stream_id") or "").strip() == stream_id
                        ),
                        None,
                    )
                    request = prepared_request
                    profile = prepared_profile
                    coaching_service = prepared_service
                    artifacts: dict[str, object] = normalized_object_mapping(
                        preparation.get("artifacts")
                    ) or {}
                    suggested_actions = list(preparation.get("suggested_actions") or [])
                    prepared_agent_meta = normalized_object_mapping(preparation.get("agent_meta")) or {}
                    coach_turn_data = dict(prepared_coach_turn)
                    response_snapshot = preparation.get("response_snapshot")
                    if not isinstance(response_snapshot, WorkbenchSnapshot):
                        response_snapshot = state.snapshot
                    scenario = str(preparation.get("scenario") or coach_turn_data.get("scenario") or "general")
                    learner_signal = str(preparation.get("learner_signal") or "")
                    attachment_delivery = preparation.get("attachment_delivery")
                    if not isinstance(attachment_delivery, dict):
                        attachment_delivery = None
                    fallback_reply = str(preparation.get("fallback_reply") or "").strip()
                    use_agent_stream = bool(preparation.get("use_agent_loop"))
                    attachments_payload = [attachment.model_dump() for attachment in request.attachments]
                    coach_context = coach_turn_data.get("coach_context")
                    if not isinstance(coach_context, dict):
                        coach_context = {}

                    full_content = ""
                    agent_summary: str | None = None
                    agent_next_step: str | None = None
                    agent_stop_reason: str | None = None
                    agent_decision: str | None = None
                    agent_blocker: str | None = None
                    agent_teaching_note: str | None = None
                    agent_resume_thread: str | None = None
                    agent_confidence: str | None = None
                    agent_evidence: list[object] | None = None
                    agent_tool_events: list[dict[str, object]] = []
                    agent_steps: list[dict[str, object]] = []
                    final_agent_meta: dict[str, object] = dict(prepared_agent_meta)
                    provider_failure_detected = False

                    yield stream_status_event("requesting_model", stream_id)
                    if use_agent_stream:
                        agent_context = dict(coach_context)
                        agent_context["__runtime__"] = runtime
                        agent_context["workspace_id"] = workspace_id
                        agent_context["session_id"] = state.session_id
                        agent_context["stream_cancel_event"] = stream_cancellation_events.get(stream_id)
                        async for event in coaching_service.coaching_reply_agentic_stream(
                            profile,
                            request.message,
                            request.current_file.model_dump() if request.current_file else None,
                            response_language=request.response_language,
                            answer_mode=request.answer_mode,
                            coach_context=agent_context,
                            attachments=attachments_payload,
                            protocol=(
                                getattr(coaching_service._config, "protocol", None)
                                if coaching_service._config
                                else None
                            ),
                            history=build_conversation_history(
                                state.snapshot.messages,
                                drop_latest_user=True,
                            ),
                        ):
                            if await stream_cancelled():
                                async for _abort_frame in _abort_for_cancellation():
                                    yield _abort_frame
                                return
                            if not isinstance(event, dict):
                                continue
                            event_type = str(event.get("type") or "")
                            if event_type == "text":
                                delta = str(event.get("delta") or "")
                                if delta:
                                    full_content += delta
                                    token_count += 1
                                    if event.get("safe_to_stream") is True and (
                                        not requires_formal_plan_commit(request)
                                        or formal_plan_commit_tool_succeeded(agent_tool_events)
                                    ):
                                        visible_delta, pending_streamed_reply_content = safe_stream_delta(
                                            pending_streamed_reply_content,
                                            delta,
                                            full_content,
                                        )
                                        if visible_delta:
                                            streamed_reply_content += visible_delta
                                            yield f"data: {json.dumps({'chunk': visible_delta})}\n\n"
                            elif event_type == "tool_call":
                                agent_tool_events.append(dict(event))
                                yield stream_frame("tool_call", event, stream_id)
                            elif event_type == "tool_result":
                                agent_tool_events.append(dict(event))
                                yield stream_frame("tool_result", event, stream_id)
                            elif event_type == "step":
                                agent_steps.append(dict(event))
                                yield stream_frame("step", event, stream_id)
                            elif event_type == "final":
                                final_content = str(event.get("content") or "")
                                if final_content:
                                    full_content = final_content
                                agent_summary = event.get("summary")
                                agent_next_step = event.get("next_step")
                                agent_stop_reason = event.get("stop_reason")
                                agent_decision = event.get("decision")
                                agent_blocker = event.get("blocker")
                                agent_teaching_note = event.get("teaching_note")
                                agent_resume_thread = event.get("resume_thread")
                                agent_confidence = event.get("confidence")
                                agent_evidence = (
                                    list(event.get("evidence") or [])
                                    if isinstance(event.get("evidence"), list)
                                    else None
                                )
                            elif event_type == "error":
                                async for _abort_frame in _abort_fail_closed(
                                    error_detail=redact_provider_error(
                                        event.get("detail"),
                                        api_key=getattr(coaching_service, "_api_key", None),
                                    ),
                                ):
                                    yield _abort_frame
                                return
                        if full_content:
                            full_content = coaching_service.finalize_coaching_reply(
                                full_content,
                                profile=profile,
                                message=request.message,
                                current_file=request.current_file.model_dump() if request.current_file else None,
                                response_language=request.response_language,
                                answer_mode=request.answer_mode,
                                coach_context=coach_context,
                            )
                        if not agent_resume_thread and (agent_summary or agent_next_step):
                            agent_resume_thread = build_resume_thread_text(
                                str(agent_summary or "").strip(),
                                str(agent_next_step or "").strip(),
                                response_language=request.response_language,
                            )
                    else:
                        async for chunk in coaching_service.coaching_reply_stream(
                            profile,
                            request.message,
                            request.current_file.model_dump() if request.current_file else None,
                            response_language=request.response_language,
                            answer_mode=request.answer_mode,
                            coach_context=coach_context,
                            history=build_conversation_history(
                                state.snapshot.messages,
                                drop_latest_user=True,
                            ),
                            cancel_event=stream_cancellation_events.get(stream_id),
                        ):
                            if await stream_cancelled():
                                async for _abort_frame in _abort_for_cancellation():
                                    yield _abort_frame
                                return
                            delta = str(chunk or "")
                            if not delta:
                                continue
                            full_content += delta
                            token_count += 1
                            visible_delta, pending_streamed_reply_content = safe_stream_delta(
                                pending_streamed_reply_content,
                                delta,
                                full_content,
                            )
                            if visible_delta and not requires_formal_plan_commit(request):
                                streamed_reply_content += visible_delta
                                yield f"data: {json.dumps({'chunk': visible_delta})}\n\n"
                        stream_finalization = coaching_service.consume_stream_finalization()
                        if stream_finalization is not None:
                            full_content = stream_finalization[1]
                        elif full_content:
                            full_content = coaching_service.finalize_coaching_reply(
                                full_content,
                                profile=profile,
                                message=request.message,
                                current_file=request.current_file.model_dump() if request.current_file else None,
                                response_language=request.response_language,
                                answer_mode=request.answer_mode,
                                coach_context=coach_context,
                            )

                    if not full_content:
                        full_content = fallback_reply
                    if not full_content:
                        full_content = coaching_service._fallback_empty_reply(
                            profile=profile,
                            message=request.message,
                            current_file=request.current_file.model_dump() if request.current_file else None,
                            response_language=request.response_language,
                            answer_mode=request.answer_mode,
                            coach_context=coach_context,
                        )
                        token_count += 1

                    provider_empty_reply_override = consume_provider_empty_reply_override(
                        coaching_service=coaching_service,
                        snapshot=state.snapshot,
                        coach_turn=coach_turn_data,
                        response_language=request.response_language,
                        assistant_content=full_content,
                    )
                    if provider_empty_reply_override is not None:
                        provider_failure_detected = True
                        full_content, updated_coach_turn, override_meta = provider_empty_reply_override
                        coach_turn_data = updated_coach_turn
                        final_agent_meta.update(override_meta)
                    else:
                        provider_failure_override = consume_provider_reply_failure_override(
                            coaching_service=coaching_service,
                            snapshot=state.snapshot,
                            coach_turn=coach_turn_data,
                            message=request.message,
                            response_language=request.response_language,
                            workspace_id=state.workspace_id,
                        )
                        if provider_failure_override is not None:
                            provider_failure_detected = True
                            full_content, updated_coach_turn, override_meta = provider_failure_override
                            coach_turn_data = updated_coach_turn
                            final_agent_meta.update(override_meta)

                    if use_agent_stream and not provider_failure_detected:
                        final_agent_meta = {
                            "stop_reason": agent_stop_reason,
                            "summary": agent_summary,
                            "next_step": agent_next_step,
                            "decision": agent_decision,
                            "blocker": agent_blocker,
                            "teaching_note": agent_teaching_note,
                            "resume_thread": agent_resume_thread,
                            "confidence": agent_confidence,
                            "evidence": agent_evidence,
                            "steps": agent_steps,
                            "tool_events": agent_tool_events,
                            "agentic": True,
                            **final_agent_meta,
                        }
                        coach_turn_data = merge_agent_finalize_into_coach_turn(
                            coach_turn_data,
                            summary=agent_summary,
                            next_step=agent_next_step,
                            blocker=agent_blocker,
                            resume_thread=agent_resume_thread,
                            decision=agent_decision,
                            teaching_note=agent_teaching_note,
                            confidence=agent_confidence,
                            evidence=agent_evidence,
                        )

                    state.snapshot.memory = runtime.memory_service.snapshot(workspace_id)
                    runtime.hydrate_plan_context(state.snapshot, workspace_id)
                    hydrate_snapshot(
                        state.snapshot,
                        response_language=request.response_language,
                        answer_mode=request.answer_mode or profile.answer_policy,
                        scenario=scenario,
                        learner_signal=learner_signal,
                        message=request.message,
                        current_file=request.current_file,
                        active_view=request.active_view,
                        session_workspace_id=workspace_id,
                    )
                    if request.intent == "plan" and request.formal_plan_mutation:
                        persisted_plan = runtime.repository.get_latest_plan(workspace_id)
                        _leftover_after, leftover_runtime_after = leftover_runtime_for_workspace(
                            workspace_id
                        )
                        if persisted_plan is not None and leftover_formal_plan_is_live_for_fill(
                            plan=persisted_plan,
                            runtime=leftover_runtime_after,
                            existing=leftover_runtime_after,
                        ):
                            state.snapshot.plan = persisted_plan
                    response_snapshot = state.snapshot

                    response_data = json_response_payload(
                        build_session_response(
                            state=state,
                            request=request,
                            reply_content=full_content,
                            artifacts=artifacts,
                            suggested_actions=suggested_actions,
                            scenario=scenario,
                            learner_signal=learner_signal,
                            coach_turn_data=coach_turn_data,
                            response_snapshot=response_snapshot,
                            agent_meta=final_agent_meta or None,
                            attachment_delivery=attachment_delivery,
                        )
                    )
                    response_data["artifacts"] = artifacts
                    response_data["intent"] = original_intent
                    reply_record = response_data.get("reply")
                    visible_content = (
                        str(reply_record.get("content") or "").strip()
                        if isinstance(reply_record, dict)
                        else ""
                    )
                    visible_delta = completion_stream_delta(streamed_reply_content, visible_content)
                    if visible_delta:
                        token_count += 1
                        yield f"data: {json.dumps({'chunk': visible_delta})}\n\n"
                    if final_agent_meta:
                        response_data["agent"] = final_agent_meta
                    if await stream_cancelled():
                        if not stream_cancellation_requested(stream_id):
                            # Client disconnected: no listener remains for a terminal frame;
                            # leave the turn recoverable as interrupted, mint no fake complete.
                            yield stream_status_event("cancelled", stream_id)
                            return
                        # Built payload but aborted before commit: publish failure so
                        # same request_id cannot remint; waiters get stamped complete.
                        stream_failed = True
                        response_data = attach_operation_reliability(
                            response_data,
                            phase="acked",
                            outcome="failure",
                            request_id=request_id or None,
                        )
                        response_data = _publish_stream_turn_response(response_data)
                        stream_singleflight_published = True
                        yield stream_status_event("failed", stream_id)
                        yield stream_status_event("acked", stream_id)
                        yield sse_complete_frame(
                            tokens=token_count,
                            response_data=response_data,
                            stream_id=stream_id,
                            outcome="failure",
                            request_id=request_id or None,
                            provider_failure_detected=True,
                        )
                        return
                    runtime.save_session_state(state.session_id)
                    response_data = _publish_stream_turn_response(response_data)
                    stream_singleflight_published = True
                    yield sse_complete_frame(
                        tokens=token_count,
                        response_data=response_data,
                        stream_id=stream_id,
                        provider_failure_detected=provider_failure_detected,
                    )
                    return

                workspace_id = current_workspace_id(
                    session_id=request.session_id, workspace_id=request.workspace_id
                )
                if state is None or profile is None:
                    raise RuntimeError("Coach stream state was not initialized.")
                coaching_service = build_coaching_service(payload)
                attachment_delivery = describe_request_attachment_delivery(
                    request,
                    coaching_service,
                    use_agent_loop=use_agent_stream,
                )
                attachments_payload = [a.model_dump() for a in request.attachments]

                preexisting_assistant_ids = {
                    message.id
                    for message in state.snapshot.messages
                    if message.role == "assistant"
                }
                stream_user_message, _ = prepare_stream_user_message(
                    state=state,
                    request=request,
                    profile=profile,
                    attachment_delivery=attachment_delivery,
                    stream_id=stream_id,
                )
                safe_activate_training_card_from_coach_request(
                    workspace_id=state.workspace_id,
                    snapshot=state.snapshot,
                    message=request.message,
                    current_file=request.current_file,
                    response_language=request.response_language,
                    provider_service_override=coaching_service,
                )
                state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
                coach_turn: CoachTurnPayload = resolve_coach_turn(
                    state=state,
                    profile=profile,
                    request=request,
                    message=request.message,
                    coaching_service=coaching_service,
                    current_task=state.snapshot.current_task,
                    current_plan=state.snapshot.plan,
                    current_evaluation=state.snapshot.evaluation,
                )
                scenario = str(coach_turn.get("scenario") or "general")
                if guarantee_guided_learn_first_training_card(
                    workspace_id=state.workspace_id,
                    scenario=str(coach_turn["scenario"] or ""),
                    message=request.message,
                    current_file=request.current_file,
                    response_language=request.response_language,
                    active_thread=state.snapshot.memory.active_thread,
                    requested_answer_mode=raw_requested_answer_mode,
                    saved_answer_mode=saved_answer_mode,
                    profile=profile,
                ):
                    state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
                guided_training_prefers_local_reply = should_bypass_agent_loop_for_guided_training(
                    workspace_id=state.workspace_id,
                    scenario=str(coach_turn["scenario"] or scenario),
                    message=request.message,
                    active_view=request.active_view,
                    requested_answer_mode=raw_requested_answer_mode,
                    saved_answer_mode=saved_answer_mode,
                    profile=profile,
                )
                guided_training_local_reply = (
                    build_guided_training_visible_fallback(
                        workspace_id=state.workspace_id,
                        response_language=request.response_language,
                    )
                    if guided_training_prefers_local_reply
                    else None
                )
                auto_resource_events = auto_resource_lookup_tool_events(
                    dict(coach_turn["coach_context"]),
                    request.message,
                )

                full_content = ""
                agent_summary: str | None = None
                agent_next_step: str | None = None
                agent_stop_reason: str | None = None
                agent_decision: str | None = None
                agent_blocker: str | None = None
                agent_teaching_note: str | None = None
                agent_resume_thread: str | None = None
                agent_confidence: str | None = None
                agent_evidence: list[object] | None = None
                agent_tool_events: list[dict[str, object]] = []
                agent_steps: list[dict[str, object]] = []
                provider_failure_detected = False
                final_agent_meta: dict[str, object] = {}
                if guided_training_local_reply is None:
                    yield stream_status_event("requesting_model", stream_id)
                if guided_training_local_reply is not None:
                    full_content, updated_coach_turn, guided_meta = apply_guided_training_visible_fallback(
                        coach_turn=coach_turn_mapping(coach_turn),
                        fallback=guided_training_local_reply,
                    )
                    coach_turn = extract_coach_turn_payload(updated_coach_turn)
                    final_agent_meta.update(guided_meta)
                    token_count += 1
                elif use_agent_stream and not guided_training_prefers_local_reply:
                    agent_context = dict(coach_turn["coach_context"])
                    agent_context["__runtime__"] = runtime
                    agent_context["workspace_id"] = workspace_id
                    agent_context["session_id"] = state.session_id
                    agent_context["stream_cancel_event"] = stream_cancellation_events.get(stream_id)
                    async for event in coaching_service.coaching_reply_agentic_stream(
                        profile,
                        request.message,
                        request.current_file.model_dump() if request.current_file else None,
                        response_language=request.response_language,
                        answer_mode=request.answer_mode,
                        coach_context=agent_context,
                        attachments=attachments_payload,
                        protocol=getattr(coaching_service._config, "protocol", None)
                        if coaching_service._config
                        else None,
                        history=build_conversation_history(
                            state.snapshot.messages,
                            drop_latest_user=True,
                        ),
                        ):
                            if await stream_cancelled():
                                async for _abort_frame in _abort_for_cancellation():
                                    yield _abort_frame
                                return
                            event_type = str(event.get("type") or "")
                            if event_type == "text":
                                delta = str(event.get("delta") or "")
                                if delta:
                                    full_content += delta
                                    token_count += 1
                                    if event.get("safe_to_stream") is True and (
                                        not requires_formal_plan_commit(request)
                                        or formal_plan_commit_tool_succeeded(agent_tool_events)
                                    ):
                                        visible_delta, pending_streamed_reply_content = safe_stream_delta(
                                            pending_streamed_reply_content,
                                            delta,
                                            full_content,
                                        )
                                        if visible_delta:
                                            streamed_reply_content += visible_delta
                                            yield f"data: {json.dumps({'chunk': visible_delta})}\n\n"
                            elif event_type == "tool_call":
                                agent_tool_events.append(dict(event))
                                yield stream_frame("tool_call", event, stream_id)
                            elif event_type == "tool_result":
                                agent_tool_events.append(dict(event))
                                yield stream_frame("tool_result", event, stream_id)
                            elif event_type == "step":
                                agent_steps.append(dict(event))
                                yield stream_frame("step", event, stream_id)
                            elif event_type == "final":
                                final_content = str(event.get("content") or "")
                                if final_content:
                                    full_content = final_content
                                agent_summary = event.get("summary")
                                agent_next_step = event.get("next_step")
                                agent_stop_reason = event.get("stop_reason")
                                agent_decision = event.get("decision")
                                agent_blocker = event.get("blocker")
                                agent_teaching_note = event.get("teaching_note")
                                agent_resume_thread = event.get("resume_thread")
                                agent_confidence = event.get("confidence")
                                agent_evidence = (
                                    list(event.get("evidence") or [])
                                    if isinstance(event.get("evidence"), list)
                                    else None
                                )
                            elif event_type == "error":
                                async for _abort_frame in _abort_fail_closed(
                                    error_detail=redact_provider_error(
                                        event.get("detail"),
                                        api_key=getattr(coaching_service, "_api_key", None),
                                    ),
                                ):
                                    yield _abort_frame
                                return
                    if full_content:
                        full_content = coaching_service.finalize_coaching_reply(
                            full_content,
                            profile=profile,
                            message=request.message,
                            current_file=request.current_file.model_dump() if request.current_file else None,
                            response_language=request.response_language,
                            answer_mode=request.answer_mode,
                            coach_context=dict(coach_turn["coach_context"]),
                        )
                    if not full_content:
                        local_sequence_fallback = build_local_sequence_visible_fallback(
                            coach_context=dict(coach_turn["coach_context"]),
                            response_language=request.response_language,
                        )
                        if local_sequence_fallback is not None:
                            full_content = local_sequence_fallback["reply"]
                            coaching_service.clear_last_reply_override()
                            agent_summary = agent_summary or local_sequence_fallback["summary"]
                            agent_next_step = agent_next_step or local_sequence_fallback["next_step"]
                            agent_teaching_note = (
                                agent_teaching_note or local_sequence_fallback["teaching_note"]
                            )
                            agent_resume_thread = (
                                agent_resume_thread or local_sequence_fallback["resume_thread"]
                            )
                            final_agent_meta["local_sequence_fallback"] = True
                            if str(agent_stop_reason or "").strip() == "empty_response":
                                final_agent_meta["fell_back"] = True
                                final_agent_meta["recovered_stop_reason"] = "empty_response"
                                final_agent_meta["stop_reason"] = "completed"
                        else:
                            full_content = coaching_service._fallback_empty_reply(
                                profile=profile,
                                message=request.message,
                                current_file=(
                                    request.current_file.model_dump() if request.current_file else None
                                ),
                                response_language=request.response_language,
                                answer_mode=request.answer_mode,
                                coach_context=dict(coach_turn["coach_context"]),
                            )
                        token_count += 1
                    updated_coach_turn = merge_agent_finalize_into_coach_turn(
                        coach_turn_mapping(coach_turn),
                        summary=agent_summary,
                        next_step=agent_next_step,
                        blocker=agent_blocker,
                        resume_thread=agent_resume_thread,
                        decision=agent_decision,
                        teaching_note=agent_teaching_note,
                        confidence=agent_confidence,
                        evidence=agent_evidence,
                    )
                    coach_turn = extract_coach_turn_payload(updated_coach_turn)
                else:
                    try:
                        async for chunk in coaching_service.coaching_reply_stream(
                            profile,
                            request.message,
                            request.current_file.model_dump() if request.current_file else None,
                            response_language=request.response_language,
                            answer_mode=request.answer_mode,
                            coach_context=dict(coach_turn["coach_context"]),
                            history=build_conversation_history(
                                state.snapshot.messages,
                                drop_latest_user=True,
                            ),
                            cancel_event=stream_cancellation_events.get(stream_id),
                        ):
                            if await stream_cancelled():
                                async for _abort_frame in _abort_for_cancellation():
                                    yield _abort_frame
                                return
                            full_content += chunk
                            token_count += 1
                            visible_chunk, pending_streamed_reply_content = safe_stream_delta(
                                pending_streamed_reply_content,
                                chunk,
                                full_content,
                            )
                            if visible_chunk and not requires_formal_plan_commit(request):
                                streamed_reply_content += visible_chunk
                                yield f"data: {json.dumps({'chunk': visible_chunk})}\n\n"
                    except Exception:
                        if not stream_recovery_requested or streamed_reply_content or full_content:
                            raise
                        # Grounding recovery is deliberately exceptional: the
                        # nominal path above is always provider-backed SSE.
                        fallback_response, fallback_artifacts, _ = await execute_turn(
                            request,
                            payload,
                            stream=False,
                        )
                        if isinstance(fallback_response, SessionMessageResponse):
                            fallback_workspace_id = current_workspace_id(
                                session_id=request.session_id,
                                workspace_id=request.workspace_id,
                            )
                            fallback_response.snapshot.memory = repair_guided_lane_memory_snapshot_for_response(
                                runtime.memory_service.snapshot(fallback_workspace_id),
                                scenario=(
                                    fallback_response.coach_turn.scenario
                                    if fallback_response.coach_turn
                                    else None
                                ),
                                response_language=request.response_language,
                                learner_message=request.message,
                            )
                            fallback_workspace_memory = (
                                fallback_response.snapshot.memory.workspace
                                if isinstance(fallback_response.snapshot.memory.workspace, dict)
                                else {}
                            )
                            hydrate_snapshot(
                                fallback_response.snapshot,
                                response_language=request.response_language
                                or str(fallback_workspace_memory.get("response_language") or "").strip()
                                or None,
                                answer_mode=(
                                    str(fallback_workspace_memory.get("answer_mode") or "").strip()
                                    or (
                                        fallback_response.snapshot.profile.answer_policy
                                        if fallback_response.snapshot.profile is not None
                                        else None
                                    )
                                ),
                                message=request.message,
                                session_workspace_id=fallback_workspace_id,
                            )
                        response_data = json_response_payload(fallback_response)
                        response_data["artifacts"] = fallback_artifacts
                        response_data["intent"] = original_intent
                        if "agent" not in response_data and isinstance(
                            response_data.get("agent_meta"),
                            dict,
                        ):
                            response_data["agent"] = response_data["agent_meta"]
                        reply = response_data.get("reply")
                        reply_content = (
                            str(reply.get("content") or "").strip()
                            if isinstance(reply, dict)
                            else ""
                        )
                        if reply_content:
                            token_count += 1
                            yield f"data: {json.dumps({'chunk': reply_content})}\n\n"
                        response_data = _publish_stream_turn_response(response_data)
                        stream_singleflight_published = True
                        yield sse_complete_frame(
                            tokens=token_count,
                            response_data=response_data,
                            stream_id=stream_id,
                            provider_failure_detected=True,
                        )
                        return
                    stream_finalization = coaching_service.consume_stream_finalization()
                    if stream_finalization is not None:
                        full_content = stream_finalization[1]
                    else:
                        full_content = coaching_service.finalize_coaching_reply(
                            full_content,
                            profile=profile,
                            message=request.message,
                            current_file=request.current_file.model_dump() if request.current_file else None,
                            response_language=request.response_language,
                            answer_mode=request.answer_mode,
                            coach_context=dict(coach_turn["coach_context"]),
                        )

                provider_empty_reply_override = consume_provider_empty_reply_override(
                    coaching_service=coaching_service,
                    snapshot=state.snapshot,
                    coach_turn=coach_turn_mapping(coach_turn),
                    response_language=request.response_language,
                    assistant_content=full_content,
                )
                if provider_empty_reply_override is not None:
                    provider_failure_detected = True
                    full_content, updated_coach_turn, override_meta = provider_empty_reply_override
                    coach_turn = extract_coach_turn_payload(updated_coach_turn)
                    final_agent_meta.update(override_meta)
                else:
                    provider_failure_override = consume_provider_reply_failure_override(
                        coaching_service=coaching_service,
                        snapshot=state.snapshot,
                        coach_turn=coach_turn_mapping(coach_turn),
                        message=request.message,
                        response_language=request.response_language,
                        workspace_id=state.workspace_id,
                    )
                    if provider_failure_override is not None:
                        provider_failure_detected = True
                        full_content, updated_coach_turn, override_meta = provider_failure_override
                        coach_turn = extract_coach_turn_payload(updated_coach_turn)
                        final_agent_meta.update(override_meta)

                if not provider_failure_detected:
                    visible_agent_meta = {
                        "stop_reason": agent_stop_reason,
                        "summary": agent_summary,
                        "next_step": agent_next_step,
                        "decision": agent_decision,
                        "blocker": agent_blocker,
                        "teaching_note": agent_teaching_note,
                        "resume_thread": agent_resume_thread,
                        "confidence": agent_confidence,
                        "evidence": agent_evidence,
                        "steps": agent_steps,
                        "tool_events": agent_tool_events,
                        "agentic": use_agent_stream and not guided_training_prefers_local_reply,
                        **final_agent_meta,
                    }
                    full_content, updated_coach_turn, final_agent_meta, _guided_lane_repaired = (
                        apply_guided_lane_visible_fallback(
                            reply=full_content,
                            scenario=str(coach_turn.get("scenario") or scenario),
                            learner_message=request.message,
                            response_language=request.response_language,
                            coach_turn=coach_turn_mapping(coach_turn),
                            agent_meta=visible_agent_meta,
                        )
                    )
                    coach_turn = extract_coach_turn_payload(updated_coach_turn)
                    repaired_summary = final_agent_meta.get("summary")
                    agent_summary = (
                        repaired_summary if isinstance(repaired_summary, str) else None
                    )
                    repaired_next_step = final_agent_meta.get("next_step")
                    agent_next_step = (
                        repaired_next_step if isinstance(repaired_next_step, str) else None
                    )
                    repaired_decision = final_agent_meta.get("decision")
                    agent_decision = (
                        repaired_decision if isinstance(repaired_decision, str) else None
                    )
                    repaired_blocker = final_agent_meta.get("blocker")
                    agent_blocker = (
                        repaired_blocker if isinstance(repaired_blocker, str) else None
                    )
                    repaired_teaching_note = final_agent_meta.get("teaching_note")
                    agent_teaching_note = (
                        repaired_teaching_note if isinstance(repaired_teaching_note, str) else None
                    )
                    repaired_resume_thread = final_agent_meta.get("resume_thread")
                    agent_resume_thread = (
                        repaired_resume_thread if isinstance(repaired_resume_thread, str) else None
                    )
                    repaired_confidence = final_agent_meta.get("confidence")
                    agent_confidence = (
                        repaired_confidence if isinstance(repaired_confidence, str) else None
                    )
                    repaired_evidence = final_agent_meta.get("evidence")
                    agent_evidence = (
                        list(repaired_evidence)
                        if isinstance(repaired_evidence, list)
                        else None
                    )
                    ensure_explicit_training_card_after_coach_reply(
                        state=state,
                        message=request.message,
                        current_file=request.current_file,
                        response_language=request.response_language,
                        fallback_scenario=str(coach_turn.get("scenario") or ""),
                        force_training_card=auto_preference_requests_training_card(
                            request.message,
                            requested_scenario=str(coach_turn.get("scenario") or scenario),
                            requested_answer_mode=raw_requested_answer_mode,
                            saved_answer_mode=saved_answer_mode,
                            profile=profile,
                        )
                        or auto_lane_learn_first_force_training_card(
                            request.message,
                            requested_scenario=str(coach_turn.get("scenario") or scenario),
                            requested_answer_mode=raw_requested_answer_mode,
                            saved_answer_mode=saved_answer_mode,
                            profile=profile,
                        ),
                        provider_service_override=coaching_service,
                    )

                if await stream_cancelled():
                    async for _abort_frame in _abort_for_cancellation():
                        yield _abort_frame
                    return
                persist_turn_reflection(
                    workspace_id=workspace_id,
                    session_id=state.session_id,
                    user_message=request.message,
                    scenario=str(coach_turn["scenario"]),
                    response_language=request.response_language,
                    answer_mode=answer_mode_preference_for_persistence(
                        raw_requested_answer_mode,
                        saved_answer_mode,
                        request.answer_mode,
                        profile.answer_policy,
                    ),
                    coach_defaults=request.coach_defaults,
                    coach_turn_data=coach_turn_mapping(coach_turn),
                    stop_reason=str(final_agent_meta.get("stop_reason") or ""),
                    recovered_stop_reason=str(final_agent_meta.get("recovered_stop_reason") or ""),
                    local_sequence_fallback=bool(final_agent_meta.get("local_sequence_fallback")),
                )
                persist_recovered_plan_resume_after_turn(
                    workspace_id=workspace_id,
                    request=request,
                    reply_content=full_content,
                    agent_meta=final_agent_meta if isinstance(final_agent_meta, dict) else None,
                    coach_context=coach_turn.get("coach_context") if isinstance(coach_turn, dict) else None,
                    recovered_status=state.snapshot.plan_runtime_status
                    if isinstance(state.snapshot.plan_runtime_status, dict)
                    else None,
                )
                if not provider_failure_detected:
                    persist_external_references_as_background(
                        workspace_id=workspace_id,
                        scenario=str(coach_turn["scenario"]),
                        coach_turn_data=coach_turn_mapping(coach_turn),
                    )
                state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
                state.snapshot.profile = runtime.repository.get_profile(workspace_id) or profile
                runtime.hydrate_plan_context(state.snapshot, workspace_id)
                hydrate_snapshot(
                    state.snapshot,
                    response_language=request.response_language,
                    answer_mode=request.answer_mode or profile.answer_policy,
                    scenario=str(coach_turn["scenario"]),
                    learner_signal=str(coach_turn["learner_signal"]),
                    message=request.message,
                    session_workspace_id=workspace_id,
                )
                update_snapshot_plan_from_turn(
                    state=state,
                    reply_content=full_content,
                    coach_turn=coach_turn_mapping(coach_turn),
                    # Session/coach streams never formal-mutate; only explicit plan intent.
                    allow_formal_plan_mutation=requires_formal_plan_commit(request),
                )
                if use_agent_stream and not guided_training_prefers_local_reply:
                    stream_agent_meta = {
                        "stop_reason": agent_stop_reason,
                        "summary": agent_summary,
                        "next_step": agent_next_step,
                        "decision": agent_decision,
                        "blocker": agent_blocker,
                        "teaching_note": agent_teaching_note,
                        "confidence": agent_confidence,
                        "evidence": agent_evidence,
                        "steps": agent_steps,
                        "tool_events": agent_tool_events,
                        "agentic": True,
                        **(normalize_attachment_delivery_payload(attachment_delivery) or {}),
                    }
                    final_agent_meta = {**stream_agent_meta, **final_agent_meta}
                if should_attach_auto_resource_events(final_agent_meta):
                    final_agent_meta = apply_auto_resource_agent_evidence(
                        final_agent_meta,
                        auto_resource_events,
                    )
                response_data = json_response_payload(
                    build_session_response(
                        state=state,
                        request=request,
                        reply_content=full_content,
                        artifacts=dict(coach_turn["artifacts"]),
                        suggested_actions=list(coach_turn["suggested_actions"]),
                        scenario=str(coach_turn["scenario"]),
                        learner_signal=str(coach_turn["learner_signal"]),
                        coach_turn_data=coach_turn_mapping(coach_turn),
                        agent_meta=final_agent_meta or None,
                        attachment_delivery=attachment_delivery,
                    )
                )
                response_data["artifacts"] = dict(coach_turn["artifacts"])
                response_data["intent"] = original_intent
                reply_record = response_data.get("reply")
                visible_content = (
                    str(reply_record.get("content") or "").strip()
                    if isinstance(reply_record, dict)
                    else ""
                )
                visible_delta = completion_stream_delta(streamed_reply_content, visible_content)
                if visible_delta:
                    token_count += 1
                    yield f"data: {json.dumps({'chunk': visible_delta})}\n\n"
                if final_agent_meta:
                    response_data["agent"] = final_agent_meta
                if await stream_cancelled():
                    if not stream_cancellation_requested(stream_id):
                        # Client disconnected: no listener remains for a terminal frame;
                        # leave the turn recoverable as interrupted, mint no fake complete.
                        yield stream_status_event("cancelled", stream_id)
                        return
                    # Built payload but aborted before commit: publish failure so same
                    # request_id cannot remint, waiters get stamped complete, not hang.
                    stream_failed = True
                    response_data = attach_operation_reliability(
                        response_data,
                        phase="acked",
                        outcome="failure",
                        request_id=request_id or None,
                    )
                    response_data = _publish_stream_turn_response(response_data)
                    stream_singleflight_published = True
                    yield stream_status_event("failed", stream_id)
                    yield stream_status_event("acked", stream_id)
                    yield sse_complete_frame(
                        tokens=token_count,
                        response_data=response_data,
                        stream_id=stream_id,
                        outcome="failure",
                        request_id=request_id or None,
                        provider_failure_detected=True,
                    )
                    return
                stream_assistant_message_ids.update(
                    message.id
                    for message in state.snapshot.messages
                    if message.role == "assistant" and message.id not in preexisting_assistant_ids
                )
                runtime.save_session_state(state.session_id)
                stream_committed = True

                response_data = _publish_stream_turn_response(response_data)
                stream_singleflight_published = True
                yield sse_complete_frame(
                    tokens=token_count,
                    response_data=response_data,
                    stream_id=stream_id,
                    provider_failure_detected=provider_failure_detected,
                )
            except asyncio.CancelledError:
                # Fail-closed: failed->acked + publish failure complete (no remint).
                logger.info("trainer_stream_cancelled", extra={"stream_id": stream_id})
                async for _abort_frame in _abort_fail_closed():
                    yield _abort_frame
                return
            except Exception as exc:
                provider_api_key = (
                    getattr(coaching_service, "_api_key", None)
                    if coaching_service is not None
                    else None
                )
                async for _abort_frame in _abort_fail_closed(
                    error_detail=redact_provider_error(exc, api_key=provider_api_key),
                ):
                    yield _abort_frame
            finally:
                if request_id and not stream_singleflight_published:
                    fail_session_request_singleflight(
                        request_key,
                        RuntimeError(
                            "turn stream failed"
                            if stream_failed
                            else "turn stream completed without publishing a payload"
                        ),
                        inflight=inflight_session_requests,
                        guard=completed_session_requests_guard,
                    )
                if state is not None:
                    finalize_stream_persistence(
                        state=state,
                        user_message=stream_user_message,
                        stream_id=stream_id,
                        committed=stream_committed,
                        assistant_message_ids=stream_assistant_message_ids,
                        stream_state=(
                            "completed"
                            if stream_committed
                            else ("failed" if stream_failed else "interrupted")
                        ),
                    )
                unregister_stream_cancellation(stream_id)

        register_stream_cancellation(stream_id)
        return StreamingResponse(generate(), media_type="text/event-stream")

    def seed_plan_from_coach_outputs(
        plan: LearningPlan,
        snapshot: WorkbenchSnapshot,
    ) -> LearningPlan:
        current_step = ""
        why_now = ""
        verify_method: list[str] = []

        adaptation_guide = snapshot.project_adaptation_guide
        if adaptation_guide and adaptation_guide.first_migration_step:
            current_step = adaptation_guide.first_migration_step
            why_now = adaptation_guide.target_outcome or (
                snapshot.coaching_state.summary if snapshot.coaching_state else ""
            )
            verify_method = [item for item in adaptation_guide.validation_checkpoints[:3] if item]
        elif snapshot.project_ideas:
            top_idea = snapshot.project_ideas[0]
            current_step = top_idea.first_step or ""
            why_now = top_idea.why_now or top_idea.summary
            verify_method = [item for item in top_idea.acceptance_signals[:3] if item]
        elif snapshot.implementation_guide:
            guide = snapshot.implementation_guide
            current_step = guide.current_step or ""
            why_now = guide.mvp_definition or guide.idea_summary
            verify_method = [item for item in guide.validation_strategy[:3] if item]

        if not current_step and not why_now and not verify_method:
            return plan
        return runtime.planner_service.refresh_plan_lifecycle(
            plan,
            current_step=current_step or None,
            why_now=why_now or None,
            verify_method=verify_method or None,
        )

    def subplan_payload(subplan: SubPlan) -> dict[str, object]:
        return subplan.model_dump(mode="json", by_alias=False)

    def require_plan(plan_id: str) -> LearningPlan:
        plan_record = runtime.repository.get_plan_by_id(plan_id)
        if plan_record is None:
            raise HTTPException(status_code=404, detail=f"Learning plan '{plan_id}' was not found.")
        _, plan = plan_record
        return plan

    def plan_context_snapshot(
        *,
        session_id: str | None = None,
        workspace_id: str | None = None,
    ) -> WorkbenchSnapshot:
        resolved_workspace_id = current_workspace_id(
            session_id=session_id,
            workspace_id=workspace_id,
        )
        snapshot = current_snapshot(session_id=session_id, workspace_id=resolved_workspace_id)
        runtime.hydrate_plan_context(snapshot, resolved_workspace_id)
        return snapshot

    def global_plan_context_payload(snapshot: WorkbenchSnapshot) -> dict[str, object]:
        return {
            "global_plan": (
                snapshot.global_plan.model_dump(mode="json", by_alias=False)
                if snapshot.global_plan is not None
                else None
            ),
            "project_plan_link": (
                snapshot.project_plan_link.model_dump(mode="json", by_alias=False)
                if snapshot.project_plan_link is not None
                else None
            ),
            "snapshot": snapshot.model_dump(mode="json", by_alias=False),
        }

    def global_plan_seed(profile: UserProfile, request: GlobalPlanUpdateRequest) -> GlobalPlan:
        goals = [item.strip() for item in (request.goals or profile.long_term_goals) if item.strip()]
        if not goals and profile.long_term_goal.strip():
            goals = [profile.long_term_goal.strip()]
        generated = runtime.planner_service.generate_plan(
            PlanGenerateRequest(profile=profile, goals=goals)
        )
        owner = runtime.repository.ensure_default_local_owner()
        title = (request.title or generated.title or "Master plan").strip()
        if not title:
            raise HTTPException(status_code=422, detail="A master plan title is required.")
        return GlobalPlan(
            id=f"global-{uuid4().hex}",
            ownerId=owner.id,
            title=title,
            summary=(request.summary if request.summary is not None else generated.summary).strip(),
            goals=goals,
            stages=request.stages if request.stages is not None else generated.stages,
            frozen=bool(request.frozen),
            currentProjectPlanId=request.current_project_plan_id,
            currentStageId=request.current_stage_id or generated.current_stage_id,
            currentStep=request.current_step if request.current_step is not None else generated.current_step,
            whyNow=request.why_now if request.why_now is not None else generated.why_now,
            verifyMethod=(
                request.verify_method if request.verify_method is not None else generated.verify_method
            ),
        )

    def auto_link_project_plan_to_global_plan(
        *,
        workspace_id: str,
        project_plan: LearningPlan,
    ) -> GlobalPlanProjectLink | None:
        """Keep the active project plan attached to the editable global plan."""
        global_plan = runtime.repository.get_default_global_plan()
        if global_plan is None or global_plan.frozen:
            return None
        link = GlobalPlanProjectLink(
            globalPlanId=global_plan.id,
            workspaceId=workspace_id,
            projectPlanId=project_plan.id,
        )
        runtime.repository.save_global_plan_project_link(link)
        return link

    def validate_global_plan_project_reference(
        *,
        workspace_id: str,
        project_plan_id: str | None,
    ) -> None:
        """Reject global-plan pointers that cross the active project boundary."""
        normalized_id = str(project_plan_id or "").strip()
        if not normalized_id:
            return
        project_plan = runtime.repository.get_plan_by_id(normalized_id)
        if project_plan is None:
            raise HTTPException(status_code=409, detail="The referenced project plan does not exist.")
        project_workspace_id, _ = project_plan
        if project_workspace_id != workspace_id:
            raise HTTPException(
                status_code=409,
                detail="The referenced project plan belongs to another workspace.",
            )

    @router.get("/plan/context", response_model=None)
    def get_plan_context(
        session_id: str | None = None,
        workspace_id: str | None = None,
    ) -> dict[str, object]:
        snapshot = plan_context_snapshot(session_id=session_id, workspace_id=workspace_id)
        return global_plan_context_payload(snapshot)

    @router.post("/plan/global", response_model=None)
    def create_global_plan(request: GlobalPlanUpdateRequest) -> dict[str, object]:
        existing = runtime.repository.get_default_global_plan()
        if existing is not None:
            raise HTTPException(
                status_code=409,
                detail="A global plan already exists. Use PATCH /plan/global for an explicit update.",
            )
        workspace_id = current_workspace_id(
            session_id=request.session_id,
            workspace_id=request.workspace_id,
        )
        validate_global_plan_project_reference(
            workspace_id=workspace_id,
            project_plan_id=request.current_project_plan_id,
        )
        profile = runtime.repository.get_profile(workspace_id) or UserProfile(long_term_goal="Trainer")
        global_plan = global_plan_seed(profile, request)
        runtime.repository.save_global_plan(global_plan)
        existing_project_plan = runtime.repository.get_latest_plan(workspace_id)
        if existing_project_plan is not None:
            auto_link_project_plan_to_global_plan(
                workspace_id=workspace_id,
                project_plan=existing_project_plan,
            )
        snapshot = plan_context_snapshot(
            session_id=request.session_id,
            workspace_id=workspace_id,
        )
        return global_plan_context_payload(snapshot)

    @router.patch("/plan/global", response_model=None)
    def update_global_plan(request: GlobalPlanUpdateRequest) -> dict[str, object]:
        existing = runtime.repository.get_default_global_plan()
        if existing is None:
            raise HTTPException(status_code=404, detail="No global plan is available yet.")
        if request.title is not None and not request.title.strip():
            raise HTTPException(status_code=422, detail="A master plan title is required.")
        workspace_id = current_workspace_id(
            session_id=request.session_id,
            workspace_id=request.workspace_id,
        )
        validate_global_plan_project_reference(
            workspace_id=workspace_id,
            project_plan_id=request.current_project_plan_id,
        )
        updates: dict[str, object] = {"updated_at": utc_now().isoformat()}
        for field_name in (
            "title",
            "summary",
            "goals",
            "stages",
            "frozen",
            "current_project_plan_id",
            "current_stage_id",
            "current_step",
            "why_now",
            "verify_method",
        ):
            value = getattr(request, field_name)
            if value is not None:
                updates[field_name] = value.strip() if isinstance(value, str) else value
        updated = existing.model_copy(update=updates)
        runtime.repository.save_global_plan(updated)
        snapshot = plan_context_snapshot(
            session_id=request.session_id,
            workspace_id=workspace_id,
        )
        return global_plan_context_payload(snapshot)

    @router.put("/plan/global/projects", response_model=None)
    def link_current_project_plan(request: GlobalPlanProjectLinkRequest) -> dict[str, object]:
        global_plan = runtime.repository.get_default_global_plan()
        if global_plan is None:
            raise HTTPException(status_code=404, detail="Create a global plan before linking a project plan.")
        if global_plan.frozen:
            raise HTTPException(status_code=409, detail="The global plan is frozen.")
        workspace_id = current_workspace_id(
            session_id=request.session_id,
            workspace_id=request.workspace_id,
        )
        project_plan = (
            runtime.repository.get_plan_by_id(request.project_plan_id)
            if request.project_plan_id
            else None
        )
        if project_plan is None:
            current_plan = runtime.repository.get_latest_plan(workspace_id)
            if current_plan is None:
                raise HTTPException(status_code=404, detail="No project plan is available to link.")
            project_plan = (workspace_id, current_plan)
        project_workspace_id, project_plan_value = project_plan
        if project_workspace_id != workspace_id:
            raise HTTPException(status_code=409, detail="The project plan belongs to another workspace.")
        link = GlobalPlanProjectLink(
            globalPlanId=global_plan.id,
            workspaceId=workspace_id,
            projectPlanId=project_plan_value.id,
        )
        runtime.repository.save_global_plan_project_link(link)
        snapshot = plan_context_snapshot(
            session_id=request.session_id,
            workspace_id=workspace_id,
        )
        return global_plan_context_payload(snapshot)

    @router.delete("/plan/global/projects/{workspace_id}", response_model=None)
    def unlink_project_plan(workspace_id: str) -> dict[str, object]:
        global_plan = runtime.repository.get_default_global_plan()
        if global_plan is None:
            raise HTTPException(status_code=404, detail="No global plan is available yet.")
        if global_plan.frozen:
            raise HTTPException(status_code=409, detail="The global plan is frozen.")
        runtime.repository.delete_global_plan_project_link(global_plan.id, workspace_id)
        snapshot = plan_context_snapshot(workspace_id=workspace_id)
        return global_plan_context_payload(snapshot)

    def frozen_plan_generation_detail(payload: dict) -> str:
        response_language = str(
            payload.get("response_language") or payload.get("responseLanguage") or ""
        ).strip()
        messages = {
            "zh-CN": "这条计划已冻结。先恢复为可编辑状态，再生成新的版本。",
            "en-US": "This plan is frozen. Resume it before creating a new version.",
            "es-ES": "Este plan esta congelado. Reanudalo antes de crear una nueva version.",
            "fr-FR": "Ce plan est gele. Reprenez-le avant de creer une nouvelle version.",
            "de-DE": "Dieser Plan ist eingefroren. Setzen Sie ihn fort, bevor Sie eine neue Version erstellen.",
            "ja-JP": "この計画は固定されています。新しい版を作る前に、再開してください。",
            "ko-KR": "이 계획은 고정되어 있습니다. 새 버전을 만들기 전에 다시 시작하세요.",
            "pt-BR": "Este plano esta congelado. Retome-o antes de criar uma nova versao.",
        }
        return messages.get(response_language, messages["en-US"])

    def reject_frozen_plan_generation(workspace_id: str, payload: dict) -> None:
        current_plan = runtime.repository.get_latest_plan(workspace_id)
        if current_plan is None or not current_plan.frozen:
            return
        leftover_plan, leftover_runtime, _leftover_task = runtime.memory_service._leftover_persist_context(
            workspace_id
        )
        if leftover_frozen_plan_blocks_generation(
            plan=leftover_plan or current_plan,
            runtime=leftover_runtime,
            existing=leftover_runtime,
        ):
            raise HTTPException(status_code=409, detail=frozen_plan_generation_detail(payload))

    def seed_generated_plan_if_leftover_live(
        plan: LearningPlan,
        snapshot: WorkbenchSnapshot,
        workspace_id: str,
    ) -> LearningPlan:
        # Explicit /plan/generate only. Coaching turns must never seed formal plan
        # identity from coach chrome (including under high urgency).
        leftover_plan, leftover_runtime, _leftover_task = runtime.memory_service._leftover_persist_context(
            workspace_id
        )
        if leftover_formal_plan_is_live_for_fill(
            plan=leftover_plan,
            runtime=leftover_runtime,
            existing=leftover_runtime,
        ):
            return seed_plan_from_coach_outputs(plan, snapshot)
        return plan

    def generated_plan_five_view_payload(
        *,
        plan_payload: dict[str, object],
        runtime_status: dict[str, object],
        snapshot: WorkbenchSnapshot,
        diagnostics: list[str],
        workspace_id: str,
    ) -> dict[str, object]:
        return {
            **plan_payload,
            "plan": plan_payload,
            "plan_runtime_status": runtime_status,
            "context_id": workspace_id,
            "workspace_id": workspace_id,
            "coach_orientation": snapshot.coach_orientation,
            "suggested_actions": [
                item.model_dump() if hasattr(item, "model_dump") else item
                for item in (snapshot.suggested_actions or [])
            ],
            "current_task": snapshot.current_task.model_dump() if snapshot.current_task else None,
            "memory": snapshot.memory.model_dump() if snapshot.memory is not None else {},
            "diagnostics": diagnostics,
            "reliability": operation_reliability_record(phase="acked", outcome="success"),
        }

    @router.post("/plan/generate", response_model=None)
    def generate_plan(payload: dict) -> object:
        requested_response_language = str(
            payload.get("response_language") or payload.get("responseLanguage") or ""
        ).strip() or None
        coaching_service = runtime.provider_service
        override_config = provider_config_from_payload(payload)
        api_key_override = provider_api_key_from_payload(payload)
        if override_config is not None or api_key_override is not None:
            coaching_service = runtime.provider_service_for(override_config, api_key_override)
        ensure_coach_provider_ready(
            coaching_service,
            response_language=requested_response_language,
        )
        if not provider_is_live_usable(coaching_service, payload):
            raise HTTPException(
                status_code=400,
                detail=localized_text(
                    "This connection is not ready. Test it in Settings, then resend this turn. Trainer did not invent a plan.",
                    "当前连接还不能用。请先在设置里测试，再重发这一轮。Trainer 没有生成新计划。",
                    requested_response_language,
                ),
            )
        if "session_id" in payload:
            session_id = payload["session_id"]
            state = runtime.ensure_session(session_id)
            reject_frozen_plan_generation(state.workspace_id, payload)
            profile = runtime.repository.get_profile(state.workspace_id) or UserProfile(long_term_goal="Trainer")
            workspace_memory = (
                state.snapshot.memory.workspace if isinstance(state.snapshot.memory.workspace, dict) else {}
            )
            workspace_response_language = (
                str(workspace_memory.get("response_language")).strip()
                if workspace_memory.get("response_language")
                else requested_response_language
            )
            objectives = [
                str(item).strip()
                for item in payload.get("objectives", [])
                if str(item).strip()
            ]
            if not objectives:
                first_look_goal = first_look_goal_hint(state.workspace_id)
                if first_look_goal:
                    objectives = [first_look_goal]
                elif profile.long_term_goal.strip():
                    objectives = [profile.long_term_goal.strip()]
            request = PlanGenerateRequest(
                profile=profile,
                goals=objectives,
                constraints=[
                    str(item).strip()
                    for item in payload.get("constraints", [])
                    if str(item).strip()
                ],
            )
            try:
                plan = runtime.planner_service.generate_plan(request)
                plan = seed_generated_plan_if_leftover_live(plan, state.snapshot, state.workspace_id)
                plan = runtime.planner_service.localize_plan(plan, workspace_response_language)
            except HTTPException:
                raise
            except Exception:
                raise HTTPException(
                    status_code=500,
                    detail="Plan generation failed. The stored plan and recovered runtime were left unchanged.",
                ) from None
            plan.session_id = session_id
            runtime.memory_service.record_profile(state.workspace_id, profile)
            runtime.repository.save_plan(state.workspace_id, plan)
            runtime.memory_service.bind_explicit_generated_plan(state.workspace_id, plan)
            auto_link_project_plan_to_global_plan(
                workspace_id=state.workspace_id,
                project_plan=plan,
            )
            state.snapshot.profile = profile
            state.snapshot.memory = runtime.memory_service.snapshot(state.workspace_id)
            runtime.hydrate_plan_context(state.snapshot, state.workspace_id)
            workspace_memory = (
                state.snapshot.memory.workspace if isinstance(state.snapshot.memory.workspace, dict) else {}
            )
            workspace_response_language = (
                str(workspace_memory.get("response_language")).strip()
                if workspace_memory.get("response_language")
                else None
            )
            workspace_answer_mode = (
                str(workspace_memory.get("answer_mode")).strip()
                if workspace_memory.get("answer_mode")
                else profile.answer_policy
            )
            hydrate_snapshot(
                state.snapshot,
                response_language=workspace_response_language,
                answer_mode=workspace_answer_mode,
            )
            runtime_status = attach_plan_runtime_status(
                workspace_id=state.workspace_id,
                snapshot=state.snapshot,
                response_language=workspace_response_language,
                profile=profile,
            )
            runtime.save_session_state(state.session_id)
            resolved_plan = stamp_produced_workspace_record(
                state.snapshot.plan or plan,
                state.workspace_id,
            )
            persist_plan_to_sandbox(state.workspace_id, resolved_plan, reason="generated")
            plan_payload = resolved_plan.model_dump()
            return generated_plan_five_view_payload(
                plan_payload=plan_payload,
                runtime_status=runtime_status,
                snapshot=state.snapshot,
                diagnostics=[
                    localized_text(
                        f"Constraints captured: {', '.join(payload.get('constraints', []))}",
                        f"已记录约束：{', '.join(payload.get('constraints', []))}",
                        workspace_response_language,
                    )
                ]
                if payload.get("constraints")
                else [],
                workspace_id=state.workspace_id,
            )

        request = PlanGenerateRequest.model_validate(payload)
        workspace_id = current_workspace_id(workspace_id=request.workspace_id)
        reject_frozen_plan_generation(workspace_id, payload)
        goals = [str(item).strip() for item in request.goals if str(item).strip()]
        if not goals:
            first_look_goal = first_look_goal_hint(workspace_id)
            if first_look_goal:
                goals = [first_look_goal]
            elif request.profile.long_term_goal.strip():
                goals = [request.profile.long_term_goal.strip()]
        request = request.model_copy(update={"goals": goals})
        try:
            plan = runtime.planner_service.generate_plan(request)
            plan = runtime.planner_service.localize_plan(plan, requested_response_language)
        except HTTPException:
            raise
        except Exception:
            raise HTTPException(
                status_code=500,
                detail="Plan generation failed. The stored plan and recovered runtime were left unchanged.",
            ) from None
        runtime.memory_service.record_profile(workspace_id, request.profile)
        runtime.repository.save_plan(workspace_id, plan)
        runtime.memory_service.bind_explicit_generated_plan(workspace_id, plan)
        auto_link_project_plan_to_global_plan(
            workspace_id=workspace_id,
            project_plan=plan,
        )
        snapshot = WorkbenchSnapshot(
            profile=request.profile,
            memory=runtime.memory_service.snapshot(workspace_id),
            plan=plan,
        )
        runtime.hydrate_plan_context(snapshot, workspace_id)
        workspace_memory = snapshot.memory.workspace if isinstance(snapshot.memory.workspace, dict) else {}
        workspace_response_language = (
            str(workspace_memory.get("response_language")).strip()
            if workspace_memory.get("response_language")
            else None
        )
        hydrate_snapshot(
            snapshot,
            response_language=workspace_response_language,
            answer_mode=(
                str(workspace_memory.get("answer_mode")).strip()
                if workspace_memory.get("answer_mode")
                else request.profile.answer_policy
            ),
        )
        runtime_status = attach_plan_runtime_status(
            workspace_id=workspace_id,
            snapshot=snapshot,
            response_language=workspace_response_language,
            profile=request.profile,
        )
        resolved_plan = stamp_produced_workspace_record(snapshot.plan or plan, workspace_id)
        persist_plan_to_sandbox(workspace_id, resolved_plan, reason="generated")
        plan_payload = resolved_plan.model_dump()
        return generated_plan_five_view_payload(
            plan_payload=plan_payload,
            runtime_status=runtime_status,
            snapshot=snapshot,
            diagnostics=[],
            workspace_id=workspace_id,
        )

    @router.post("/plan/update", response_model=None)
    def update_plan(payload: dict) -> object:
        request = PlanUpdateRequest.model_validate(payload)
        workspace_id = current_workspace_id(workspace_id=request.workspace_id)
        current: LearningPlan | None = None
        if request.plan_id:
            current_record = runtime.repository.get_plan_by_id(request.plan_id)
            if current_record:
                workspace_id, current = current_record
        if current is None:
            current = runtime.repository.get_latest_plan(workspace_id)
        if not current:
            raise HTTPException(status_code=404, detail="No learning plan is available yet.")
        # Explicit mutate by plan_id only when recovered runtime still matches that id.
        # Leftover stored plan with empty/mismatched recovered plan_id must not fill snapshot.plan.
        leftover_plan, leftover_runtime = leftover_runtime_for_workspace(workspace_id)
        if not leftover_formal_plan_is_live_for_fill(
            plan=current,
            runtime=leftover_runtime,
            existing=leftover_runtime,
        ):
            if leftover_plan is not None and leftover_runtime:
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "Recovered plan runtime is leftover-not-live. "
                        "/plan/update will not mutate or resurrect the leftover as live."
                    ),
                )
            raise HTTPException(
                status_code=409,
                detail=(
                    "No live learning plan is bound. Generate a plan first; "
                    "/plan/update does not resurrect leftover as live."
                ),
            )
        if current.frozen:
            has_content_update = bool(
                request.title or request.weekly_cadence or request.instructions.strip()
            )
            if has_content_update or request.frozen is not False:
                response_language = str(
                    payload.get("response_language") or payload.get("responseLanguage") or ""
                ).strip() or None
                raise HTTPException(
                    status_code=409,
                    detail=frozen_plan_mutation_notice(response_language),
                )
        has_content_update = bool(
            request.title or request.weekly_cadence or request.instructions.strip()
        )
        if has_content_update:
            requested_response_language = str(
                payload.get("response_language") or payload.get("responseLanguage") or ""
            ).strip() or None
            coaching_service = runtime.provider_service
            override_config = provider_config_from_payload(payload)
            api_key_override = provider_api_key_from_payload(payload)
            if override_config is not None or api_key_override is not None:
                coaching_service = runtime.provider_service_for(override_config, api_key_override)
            ensure_coach_provider_ready(
                coaching_service,
                response_language=requested_response_language,
            )
            if not provider_is_live_usable(coaching_service, payload):
                raise HTTPException(
                    status_code=400,
                    detail=localized_text(
                        "This connection is not ready. Test it in Settings, then resend this turn. Trainer did not invent a plan.",
                        "当前连接还不能用。请先在设置里测试，再重发这一轮。Trainer 没有生成新计划。",
                        requested_response_language,
                    ),
                )
        if request.title:
            current.title = request.title
        if request.frozen is not None:
            request.freeze = request.frozen
        if request.weekly_cadence:
            current.weekly_cadence = request.weekly_cadence
            current.cadence = request.weekly_cadence
        workspace_snapshot = runtime.memory_service.snapshot(workspace_id)
        workspace_memory = workspace_snapshot.workspace if isinstance(workspace_snapshot.workspace, dict) else {}
        workspace_response_language = (
            str(workspace_memory.get("response_language")).strip()
            if workspace_memory.get("response_language")
            else None
        )
        updated = runtime.planner_service.update_plan(current, request)
        updated = runtime.planner_service.localize_plan(updated, workspace_response_language)
        runtime.repository.save_plan(workspace_id, updated)
        # Keep the recovered runtime identity in sync with the mutated plan:
        # update_plan may rewrite current_step/why_now, and a stale runtime record
        # would make /task/next and /task/specify see this live plan as leftover-not-live.
        runtime.memory_service.bind_explicit_generated_plan(workspace_id, updated)
        profile = runtime.repository.get_profile(workspace_id)
        snapshot = current_snapshot(workspace_id=workspace_id)
        snapshot.plan = updated
        workspace_memory = snapshot.memory.workspace if isinstance(snapshot.memory.workspace, dict) else {}
        workspace_response_language = (
            str(workspace_memory.get("response_language")).strip()
            if workspace_memory.get("response_language")
            else None
        )
        workspace_answer_mode = (
            str(workspace_memory.get("answer_mode")).strip()
            if workspace_memory.get("answer_mode")
            else (profile.answer_policy if profile else None)
        )
        hydrate_snapshot(
            snapshot,
            response_language=workspace_response_language,
            answer_mode=workspace_answer_mode,
            scenario="plan",
            learner_signal="steady",
        )
        snapshot.plan = runtime.planner_service.refresh_plan_lifecycle(
            snapshot.plan or updated,
            current_step=(updated.current_step or updated.summary or updated.title),
            why_now=(updated.why_now or updated.summary or updated.title),
            verify_method=list(updated.verify_method),
            blocked_reason=updated.blocked_reason,
            next_after_current=updated.next_after_current,
        )
        runtime_status = attach_plan_runtime_status(
            workspace_id=workspace_id,
            snapshot=snapshot,
            response_language=workspace_response_language,
            profile=profile,
        )
        updated_plan = stamp_produced_workspace_record(snapshot.plan or updated, workspace_id)
        persist_plan_to_sandbox(workspace_id, updated_plan, reason="updated")
        active_stage = active_plan_stage(updated_plan)
        persist_chrome = live_plan_update_persist_chrome(
            plan=updated_plan,
            runtime=coach_focus_runtime_from_snapshot(snapshot)
            or (runtime_status if isinstance(runtime_status, dict) else None),
            existing=runtime_status if isinstance(runtime_status, dict) else None,
            stage_title=active_stage.title if active_stage else "",
            stage_goal=active_stage.goal if active_stage else "",
        )
        diagnostics: list[str] = []
        if request.instructions.strip():
            diagnostics.append(
                localized_text(
                    f"Coach instruction captured: {request.instructions}",
                    f"已记录教练指令：{request.instructions}",
                    workspace_response_language,
                )
            )
        if request.weekly_cadence:
            diagnostics.append(f"Cadence updated to {request.weekly_cadence}.")
        if request.freeze:
            diagnostics.append("Plan is now frozen for execution focus.")
        response_payload = {
            "plan": updated_plan.model_dump(),
            "plan_runtime_status": runtime_status,
            "coach_turn": CoachTurnSummary(
                scenario="plan",
                learner_signal="steady",
                summary=localized_text(
                    persist_chrome["summary_en"],
                    persist_chrome["summary_zh"],
                    workspace_response_language,
                ),
                next_step=persist_chrome["next_step"]
                or (
                    "Turn the active stage into today's first task."
                    if active_stage is None
                    else ""
                ),
                encouragement=localized_text(
                    "Keep the next move visible and small.",
                    "把下一步保持得清晰而且足够小。",
                    workspace_response_language,
                ),
                active_stage=persist_chrome["stage_focus"] or None,
                due_review_count=0,
                review_queue_summary=localized_text(
                    "Background review stays embedded in future turns.",
                    "背景复习会继续嵌在后续轮次里。",
                    workspace_response_language,
                ),
                artifact_kinds=["plan_update"],
                suggested_action_types=["plan", "next_task"],
            ).model_dump(),
            "suggested_actions": structured_suggested_actions(
                coach_suggested_actions(workspace_response_language, scenario="plan"),
                response_language=workspace_response_language,
                scenario="plan",
                focus_area=stateful_focus_area(
                    None,
                    updated_plan,
                    runtime=runtime_status if isinstance(runtime_status, dict) else None,
                ),
            ),
            "diagnostics": diagnostics,
        }
        if "weekly_cadence" in payload or "frozen" in payload or "title" in payload or request.instructions:
            return response_payload
        return response_payload["plan"]

